// ─── Admin panel (interno) ────────────────────────────────────────────────────
// Login con cookie de sesión (12h). Credenciales en ADMIN_USER / ADMIN_PASSWORD
// (env vars). Sin esas dos variables, el panel queda desactivado.
// Edita los .md de /prompts y el bot los releé en cada request, así los cambios
// se aplican al instante.

const PROMPT_SECTIONS = {
  general:   'general.md',
  kairos:    'kairos.md',
  firulais:  'firulais.md',
  banny:     'banny.md',
  mayorista: 'mayorista.md',
};

const ADMIN_COOKIE = 'zadm';
const ADMIN_TTL_MS = 12 * 60 * 60 * 1000; // 12 horas
const ADMIN_SESSIONS = new Map(); // token → { username, expiresAt }

function parseCookies(req){
  const header = req.headers.cookie || '';
  const out = {};
  for (const part of header.split(';')) {
    const i = part.indexOf('=');
    if (i < 0) continue;
    const k = part.slice(0, i).trim();
    const v = part.slice(i + 1).trim();
    if (k) out[k] = decodeURIComponent(v);
  }
  return out;
}

function adminSessionFor(req){
  const token = parseCookies(req)[ADMIN_COOKIE];
  if (!token) return null;
  const s = ADMIN_SESSIONS.get(token);
  if (!s) return null;
  if (s.expiresAt < Date.now()) { ADMIN_SESSIONS.delete(token); return null; }
  return { token, ...s };
}

// Credenciales del panel. Idealmente se setean en Railway como ADMIN_USER /
// ADMIN_PASSWORD. Si no están, caen a un default para no dejar el panel
// inaccesible — CAMBIALAS en producción seteando las env vars.
const ADMIN_USER_DEFAULT = 'zorbo';
const ADMIN_PASSWORD_DEFAULT = 'zorbo2026';
function adminCreds(){
  return {
    user: (process.env.ADMIN_USER || ADMIN_USER_DEFAULT),
    pass: (process.env.ADMIN_PASSWORD || ADMIN_PASSWORD_DEFAULT),
  };
}
function isAdminConfigured(){
  return true; // siempre hay credenciales (env o default)
}
// Usuarios con rol LIMITADO "costeo": solo ven el módulo Costeo de carta, y dentro
// solo pueden EDITAR Recetas base y Platos/Tragos. Cada uno acotado a UN servicio
// (svc): Mao → comida, Raúl → barra. Ven ambos, pero editan solo el suyo.
const COSTEO_USERS = {
  'mcastillo@grupomilsabores.com': { svc: 'comida' },
  'rquispe@kairosdrinks.com': { svc: 'barra' },
};
const COSTEO_USERS_PASS = 'Kairos2026.-';
// ¿Puede el rol "costeo" tocar esta request? Ve todo lo de costeo (GET) pero solo
// edita recetas base y platos/tragos, y solo en su servicio (sess.costeoSvc).
function costeoRoleAllows(req, sess){
  const p = req.path, m = req.method;
  if (p === '/admin' || p === '/admin/' || p === '/admin/me' || p === '/admin/logout') return true;
  if (p.startsWith('/admin/costeo')) {
    if (m === 'GET' || m === 'HEAD') return true; // ver todo (comida y barra)
    const isEdit = /^\/admin\/costeo\/recetas(\/|$)/.test(p) || /^\/admin\/costeo\/platos(\/|$)/.test(p);
    if (!isEdit) return false; // insumos, carta/asignar, secciones, precio-real → solo ver
    const scope = sess && sess.costeoSvc; // 'comida' | 'barra' | undefined(=todo)
    if (scope) {
      const svc = (req.query.svc === 'barra') ? 'barra' : 'comida';
      if (svc !== scope) return false;
    }
    return true;
  }
  return false;
}

// Rol "miembro": solo el Espacio de trabajo. No ve ni por accidente los módulos
// con plata adentro (Estado de Resultado, Costos, Gastos, nómina…). La lista es
// de PERMITIDOS, no de bloqueados: un módulo nuevo nace cerrado para el miembro,
// que es el default correcto cuando lo que se filtra es información sensible.
function miembroRoleAllows(req){
  const p = req.path, m = req.method;
  if (p === '/admin' || p === '/admin/' || p === '/admin/me' || p === '/admin/logout') return true;
  if (p.startsWith('/admin/ws/')) return true;               // el espacio de trabajo entero
  if (p === '/admin/team' && (m === 'GET' || m === 'HEAD')) return true; // roster para asignar
  if (p === '/admin/team/me' && m === 'PUT') return true;    // editar el perfil propio
  if (p === '/admin/upload' && m === 'POST') return true;    // subir su propio avatar
  if (p === '/admin/_diag/almacenamiento') return true;      // aviso de disco efímero
  return false;
}

function wantsHtml(req){
  const accept = String(req.headers.accept || '');
  return accept.includes('text/html');
}

// Login ACTIVO por defecto. Para abrir el panel sin login (debug) setear
// ADMIN_AUTH_ENABLED=0.
function requireAdmin(req, res, next){
  if (process.env.ADMIN_AUTH_ENABLED === '0') return next();
  const sess = adminSessionFor(req);
  if (!sess) {
    if (wantsHtml(req)) return res.redirect(302, '/login');
    return res.status(401).json({ error: 'No autorizado. Iniciá sesión en /login.' });
  }
  // Rol limitado "costeo": bloquea todo lo que no sea ver/editar lo permitido.
  if (sess.role === 'costeo' && !costeoRoleAllows(req, sess)) {
    if (wantsHtml(req)) return res.redirect(302, '/admin');
    return res.status(403).json({ error: 'No tenés permiso para editar esta sección.' });
  }
  if (sess.role === 'miembro' && !miembroRoleAllows(req)) {
    if (wantsHtml(req)) return res.redirect(302, '/admin');
    return res.status(403).json({ error: 'Tu cuenta solo tiene acceso al Espacio de trabajo.' });
  }
  return next();
}

// Limpieza periódica de sesiones expiradas (cada hora)
setInterval(() => {
  const now = Date.now();
  for (const [t, s] of ADMIN_SESSIONS) if (s.expiresAt < now) ADMIN_SESSIONS.delete(t);
}, 60 * 60 * 1000).unref?.();

// ─── Rutas de login ─────────────────────────────────────────────────────────

app.get('/admin/login', (req, res) => {
  // Si ya hay sesión válida, redirige al panel
  if (isAdminConfigured() && adminSessionFor(req)) return res.redirect(302, '/admin');
  // La puerta de acceso ahora es la de K-BROS (/login). El login viejo de ZORBO
  // queda deprecado: cualquier link/bookmark a /admin/login cae en la puerta K-BROS.
  res.redirect(302, '/login');
});

app.post('/admin/login', async (req, res) => {
  if (!isAdminConfigured()) return res.status(503).json({ error: 'Panel admin no configurado.' });
  const { username, password } = req.body || {};
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Faltan credenciales.' });
  }

  const creds = adminCreds();
  const userLc = username.trim().toLowerCase();

  // Admin completo (env/default), cuenta individual propia, o usuario de rol "costeo".
  let account = null;
  if (safeStrEq(userLc, String(creds.user).trim().toLowerCase()) && safeStrEq(password, String(creds.pass))) {
    account = { username: creds.user, role: 'admin' };
  } else {
    const teamMember = teamFindByUsername(userLc);
    if (teamMember && teamMember.passwordHash && teamVerifyPassword(password, teamMember.passwordHash)) {
      account = { username: teamMember.username, role: teamRol(teamMember.role), teamId: teamMember.id };
    } else if (COSTEO_USERS[userLc] && safeStrEq(password, COSTEO_USERS_PASS)) {
      account = { username: userLc, role: 'costeo', costeoSvc: COSTEO_USERS[userLc].svc };
    }
  }

  // Pequeño delay artificial para frenar fuerza bruta
  await new Promise(r => setTimeout(r, 250));

  if (!account) {
    return res.status(401).json({ error: 'Usuario o contraseña incorrectos.' });
  }

  // Perfil (nombre/apodo) enganchado por username, sin importar la puerta de login.
  const profile = teamProfileFor(account.username) || {};
  const token = randomBytes(32).toString('hex');
  const expiresAt = Date.now() + ADMIN_TTL_MS;
  ADMIN_SESSIONS.set(token, {
    username: account.username, role: account.role, costeoSvc: account.costeoSvc, teamId: account.teamId || null,
    nombre: profile.nombre || '', apodo: profile.apodo || '', expiresAt,
  });

  const secure = req.secure || req.headers['x-forwarded-proto'] === 'https';
  const parts = [
    `${ADMIN_COOKIE}=${encodeURIComponent(token)}`,
    'HttpOnly',
    'Path=/',
    'SameSite=Lax',
    `Max-Age=${Math.floor(ADMIN_TTL_MS / 1000)}`,
  ];
  if (secure) parts.push('Secure');
  res.setHeader('Set-Cookie', parts.join('; '));
  res.json({ ok: true, expiresAt });
});

app.post('/admin/logout', (req, res) => {
  const s = adminSessionFor(req);
  if (s) ADMIN_SESSIONS.delete(s.token);
  res.setHeader('Set-Cookie', `${ADMIN_COOKIE}=; HttpOnly; Path=/; SameSite=Lax; Max-Age=0`);
  res.json({ ok: true });
});

function safeStrEq(a, b){
  const A = Buffer.from(a, 'utf-8');
  const B = Buffer.from(b, 'utf-8');
  if (A.length !== B.length) {
    // Igualar longitudes para que timingSafeEqual no tire
    timingSafeEqual(A, A);
    return false;
  }
  return timingSafeEqual(A, B);
}

// ─── Cuentas individuales de equipo (saludo personalizado) ─────────────────
// ADITIVO — no reemplaza ni toca ADMIN_USER/ADMIN_PASSWORD: esa credencial
// compartida sigue funcionando exactamente igual. Esto agrega:
//  (a) cuentas propias reales (usuario + clave propios) para el rol admin, y
//  (b) "perfiles" (nombre/apodo) que se enganchan por username a CUALQUIER
//      login exitoso (compartido, propio o costeo) para poder saludar por
//      apodo sin importar por qué puerta entró la persona.
const TEAM_FILE = join(PROMPTS_EFFECTIVE_DIR, 'team.json');
function teamHashPassword(pw){
  const salt = randomBytes(16).toString('hex');
  const hash = scryptSync(pw, salt, 64).toString('hex');
  return salt + ':' + hash;
}
function teamVerifyPassword(pw, stored){
  const [salt, hash] = String(stored || '').split(':');
  if (!salt || !hash) return false;
  let calc; try { calc = scryptSync(pw, salt, 64); } catch { return false; }
  const orig = Buffer.from(hash, 'hex');
  if (calc.length !== orig.length) return false;
  return timingSafeEqual(calc, orig);
}
let TEAM_ID_SEQ = 0;
function teamNewId(){ TEAM_ID_SEQ = (TEAM_ID_SEQ + 1) % 100000; return 'team_' + Date.now().toString(36) + '_' + TEAM_ID_SEQ.toString(36); }
function teamSave(d){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(TEAM_FILE, JSON.stringify(d, null, 2)); }
function teamLoad(){
  let data = { members: [] };
  try { if (existsSync(TEAM_FILE)) { const p = JSON.parse(readFileSync(TEAM_FILE, 'utf-8')); if (Array.isArray(p.members)) data.members = p.members; } }
  catch (e) { console.warn('team load:', e.message); }
  // Semilla única: perfil de Arie enganchado al username ya usado hoy para
  // entrar (la credencial compartida) — sin contraseña propia (profileOnly),
  // así el saludo funciona apenas se despliega, sin tocar el login existente.
  if (!data.members.some(m => (m.username || '').toLowerCase() === 'afinkelstein@kairosdrinks.com')) {
    data.members.push({
      id: teamNewId(), username: 'afinkelstein@kairosdrinks.com', passwordHash: null, profileOnly: true,
      nombre: 'Arie', apellido: '', apodo: 'Dj Cookie', role: 'admin', createdAt: Date.now(),
    });
    teamSave(data);
  }
  return data;
}
function teamFindByUsername(username){
  const uLc = String(username || '').trim().toLowerCase();
  if (!uLc) return null;
  return teamLoad().members.find(m => (m.username || '').toLowerCase() === uLc) || null;
}
// Perfil (nombre/apodo) para decorar el saludo, sin importar la puerta de login.
function teamProfileFor(username){
  const m = teamFindByUsername(username);
  if (!m) return null;
  return { nombre: m.nombre || '', apellido: m.apellido || '', apodo: m.apodo || '' };
}

// ─── Rutas protegidas ───────────────────────────────────────────────────────

app.get('/admin', requireAdmin, (_req, res) => {
  res.sendFile(join(__dirname, 'admin-views', 'admin.html'));
});

app.get('/admin/me', requireAdmin, (req, res) => {
  const s = adminSessionFor(req);
  if (!s) return res.json({ username: null, role: 'admin', costeoSvc: null, nombre: '', apodo: '', teamId: null, avatar: '', color: teamColor(null, 'kbros'), expiresAt: null }); // auth deshabilitada
  const perfil = teamFindByUsername(s.username);
  res.json({
    username: s.username, role: s.role || 'admin', costeoSvc: s.costeoSvc || null,
    nombre: s.nombre || '', apodo: s.apodo || '', teamId: s.teamId || (perfil && perfil.id) || null,
    avatar: (perfil && perfil.avatar) || '', color: teamColor(perfil && perfil.color, s.username),
    expiresAt: s.expiresAt,
  });
});

// ─── Cuentas de equipo: alta / edición / listado ────────────────────────────
// Mismo permiso plano que el resto del panel (cualquier sesión admin puede
// gestionar el equipo, igual que ya puede tocar cualquier otra sección).
// Roles del panel: 'admin' ve y edita todo; 'miembro' solo el Espacio de trabajo
// (ver miembroRoleAllows). Las cuentas que ya existían no declaran rol → 'admin',
// así nadie pierde acceso por este cambio.
const TEAM_ROLES = ['admin', 'miembro'];
const teamRol = (r) => TEAM_ROLES.includes(String(r || '')) ? String(r) : 'admin';
// Paleta de identidad: cada persona tiene un color para avatares y tarjetas.
const WS_COLORES = ['#f5a623','#2e9c5a','#4a90d9','#c1447e','#7c6bb8','#1f8a70','#d9534f','#b87333','#5b6472','#0ea5a5'];
const teamColor = (v, semilla) => {
  const c = String(v || '').trim();
  if (/^#[0-9a-fA-F]{6}$/.test(c)) return c;
  let h = 0; for (const ch of String(semilla || '')) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return WS_COLORES[h % WS_COLORES.length];
};
const teamPublic = (m) => ({ id: m.id, username: m.username, email: m.email || m.username || '', nombre: m.nombre || '', apellido: m.apellido || '', apodo: m.apodo || '', role: teamRol(m.role), avatar: m.avatar || '', color: teamColor(m.color, m.username), profileOnly: !!m.profileOnly, createdAt: m.createdAt || null });
app.get('/admin/team', requireAdmin, (req, res) => {
  res.json({ members: teamLoad().members.map(teamPublic) });
});
app.post('/admin/team', requireAdmin, (req, res) => {
  const b = req.body || {};
  const username = costosStr(b.username, 120).toLowerCase();
  const password = String(b.password || '');
  const nombre = costosStr(b.nombre, 80);
  const apellido = costosStr(b.apellido, 80);
  const apodo = costosStr(b.apodo, 40);
  if (!username || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(username)) return res.status(400).json({ error: 'Ingresá un correo válido como usuario.' });
  if (!nombre) return res.status(400).json({ error: 'Falta el nombre.' });
  if (!password || password.length < 8) return res.status(400).json({ error: 'La contraseña debe tener al menos 8 caracteres.' });
  const data = teamLoad();
  if (data.members.some(m => (m.username || '').toLowerCase() === username)) return res.status(409).json({ error: 'Ya existe una cuenta con ese correo.' });
  // Rol: si el alta no lo declara, 'miembro' — el acceso total se da a propósito,
  // no por omisión. Las cuentas viejas no se tocan (siguen siendo admin).
  const role = TEAM_ROLES.includes(String(b.role || '')) ? String(b.role) : 'miembro';
  const member = {
    id: teamNewId(), username, passwordHash: teamHashPassword(password), profileOnly: false,
    nombre, apellido, apodo, role, createdAt: Date.now(),
    email: costosStr(b.email, 120).toLowerCase() || username,
    avatar: costosStr(b.avatar, 400), color: teamColor(b.color, username),
  };
  data.members.push(member); teamSave(data);
  res.json({ ok: true, member: teamPublic(member) });
});
app.put('/admin/team/me', requireAdmin, (req, res) => {
  const s = adminSessionFor(req);
  if (!s) return res.status(401).json({ error: 'No autorizado.' });
  const data = teamLoad();
  let member = (s.teamId && data.members.find(m => m.id === s.teamId)) || data.members.find(m => (m.username || '').toLowerCase() === String(s.username || '').toLowerCase());
  if (!member) {
    // Primera vez que esta persona edita su perfil (venía solo del saludo genérico): lo crea profileOnly.
    member = { id: teamNewId(), username: s.username, passwordHash: null, profileOnly: true, nombre: '', apellido: '', apodo: '', role: s.role || 'admin', createdAt: Date.now() };
    data.members.push(member);
  }
  const b = req.body || {};
  if (b.nombre != null) member.nombre = costosStr(b.nombre, 80);
  if (b.apellido != null) member.apellido = costosStr(b.apellido, 80);
  if (b.apodo != null) member.apodo = costosStr(b.apodo, 40);
  teamSave(data);
  // Refresca la sesión activa (en memoria) para que el saludo se actualice sin
  // requerir un nuevo login: adminSessionFor() devuelve una copia, así que
  // mutamos el objeto real del Map directamente.
  const rawSession = ADMIN_SESSIONS.get(s.token);
  if (rawSession) { rawSession.nombre = member.nombre; rawSession.apodo = member.apodo; rawSession.teamId = member.id; }
  res.json({ ok: true, member: teamPublic(member) });
});
app.put('/admin/team/:id', requireAdmin, (req, res) => {
  const data = teamLoad();
  const member = data.members.find(m => m.id === req.params.id);
  if (!member) return res.status(404).json({ error: 'No se encontró la cuenta.' });
  const b = req.body || {};
  if (b.nombre != null) member.nombre = costosStr(b.nombre, 80);
  if (b.apellido != null) member.apellido = costosStr(b.apellido, 80);
  if (b.apodo != null) member.apodo = costosStr(b.apodo, 40);
  if (b.email != null) member.email = costosStr(b.email, 120).toLowerCase();
  if (b.avatar != null) member.avatar = costosStr(b.avatar, 400);
  if (b.color != null) member.color = teamColor(b.color, member.username);
  if (b.role != null && TEAM_ROLES.includes(String(b.role))) member.role = String(b.role);
  if (b.password) {
    if (String(b.password).length < 8) return res.status(400).json({ error: 'La contraseña debe tener al menos 8 caracteres.' });
    member.passwordHash = teamHashPassword(String(b.password)); member.profileOnly = false;
  }
  teamSave(data);
  res.json({ ok: true, member: teamPublic(member) });
});
app.delete('/admin/team/:id', requireAdmin, (req, res) => {
  const data = teamLoad();
  const n = data.members.length;
  data.members = data.members.filter(m => m.id !== req.params.id);
  if (data.members.length === n) return res.status(404).json({ error: 'No se encontró la cuenta.' });
  teamSave(data);
  res.json({ ok: true });
});

// ════════════════════════════════════════════════════════════════════════════
// ESPACIO DE TRABAJO — proyectos, tareas, notificaciones
// ════════════════════════════════════════════════════════════════════════════
// Todo vive en un solo doc, workspace.json, en el mismo directorio de datos que
// el resto (volumen persistente en Railway). Las semillas SOLO completan lo que
// está vacío: si el usuario borra un proyecto sembrado, no vuelve a aparecer
// (por eso el flag `sembrado`, y no "¿está la lista vacía?").
//
// La identidad de una persona en el espacio es su USERNAME (el correo con el que
// entra), no el id del registro de equipo: es lo único que existe siempre, tanto
// si entró con su cuenta propia como con la credencial de administrador.
const WS_FILE = join(PROMPTS_EFFECTIVE_DIR, 'workspace.json');
const WS_V = 1;
const WS_ESTADOS_DEFAULT = [
  { id: 'por_hacer', nombre: 'Por hacer', color: '#5b6472', orden: 0 },
  { id: 'haciendo',  nombre: 'Haciendo',  color: '#4a90d9', orden: 1 },
  { id: 'listo',     nombre: 'Listo',     color: '#2e9c5a', orden: 2 },
];
const WS_PRIORIDADES = ['baja', 'media', 'alta', 'urgente'];
const WS_CANALES_SEMILLA = [
  { nombre: 'general',      emoji: '💬', descripcion: 'Todo el equipo' },
  { nombre: 'produccion',   emoji: '🏭', descripcion: 'Cocciones, envasado, planta' },
  { nombre: 'ventas',       emoji: '🛒', descripcion: 'Pedidos, clientes y canales' },
  { nombre: 'restaurantes', emoji: '🍽️', descripcion: 'Garden, Badass y Hospitality' },
];
const WS_PROYECTOS_SEMILLA = [
  { nombre: 'Producción',        emoji: '🏭', color: '#b87333' },
  { nombre: 'Marketing',         emoji: '📣', color: '#f5a623' },
  { nombre: 'Restaurantes',      emoji: '🍽️', color: '#c1447e' },
  { nombre: 'Ventas',            emoji: '🛒', color: '#2e9c5a' },
  { nombre: 'Distribución',      emoji: '🚚', color: '#4a90d9' },
  { nombre: 'Alertas del sistema', emoji: '🔔', color: '#d9534f', descripcion: 'Tareas que genera solo el ERP cuando detecta algo que revisar.' },
];

let WS_ID_SEQ = 0;
function wsNewId(pfx){ WS_ID_SEQ = (WS_ID_SEQ + 1) % 100000; return pfx + '_' + Date.now().toString(36) + '_' + WS_ID_SEQ.toString(36); }
const wsStr = (v, m = 200) => String(v == null ? '' : v).trim().slice(0, m);
const wsArr = (v) => Array.isArray(v) ? v : [];
// Fecha "YYYY-MM-DD" o vacío. Nunca un Date: el vencimiento es un día del
// calendario, no un instante — con zona horaria de por medio se corre un día.
const wsFecha = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? String(v) : '';

function wsSave(d){
  if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true });
  writeFileSync(WS_FILE, JSON.stringify(d, null, 2));
}
function wsLoad(){
  // El doc arranca con TODAS las claves que va a usar el espacio (metas todavía
  // sin endpoints) para que las partes que vienen después no tengan que migrar
  // el archivo. `lecturas` es un objeto {username: {canalId: ts}}, no un array.
  const base = { v: WS_V, sembrado: false, canalesSembrados: false, estados: [], proyectos: [], tareas: [], notificaciones: [], eventos: [], canales: [], mensajes: [], metas: [], lecturas: {} };
  let d = { ...base };
  try {
    if (existsSync(WS_FILE)) {
      const p = JSON.parse(readFileSync(WS_FILE, 'utf-8'));
      // Copia campo por campo pero conservando cualquier clave extra que haya
      // escrito una versión más nueva: descartar lo que no se reconoce es
      // justo cómo se pierde el trabajo cargado a mano.
      d = { ...base, ...p };
      for (const k of ['estados','proyectos','tareas','notificaciones','eventos','canales','mensajes','metas']) d[k] = wsArr(d[k]);
      if (!d.lecturas || typeof d.lecturas !== 'object' || Array.isArray(d.lecturas)) d.lecturas = {};
    }
  } catch (e) { console.warn('workspace load:', e.message); }
  let cambio = false;
  if (!d.estados.length) { d.estados = WS_ESTADOS_DEFAULT.map(e => ({ ...e })); cambio = true; }
  if (!d.sembrado) {
    // Semilla única de proyectos. Dedupe por nombre normalizado para que correr
    // dos veces (o sobre datos que ya los tenían) no duplique nada.
    const yaHay = new Set(d.proyectos.map(p => wsStr(p.nombre).toLowerCase()));
    for (const s of WS_PROYECTOS_SEMILLA) {
      if (yaHay.has(s.nombre.toLowerCase())) continue;
      d.proyectos.push({
        id: wsNewId('pr'), nombre: s.nombre, color: s.color, emoji: s.emoji,
        descripcion: s.descripcion || '', responsable: '', archivado: false, createdAt: Date.now(),
      });
    }
    d.sembrado = true; cambio = true;
  }
  if (!d.canalesSembrados) {
    // Igual que los proyectos: una sola vez, con dedupe por nombre. Si el admin
    // borra #ventas, no reaparece en el próximo arranque.
    const yaHay = new Set(d.canales.map(c => wsStr(c.nombre).toLowerCase()));
    for (const s of WS_CANALES_SEMILLA) {
      if (yaHay.has(s.nombre)) continue;
      d.canales.push({
        id: wsNewId('cn'), tipo: 'canal', nombre: s.nombre, emoji: s.emoji,
        descripcion: s.descripcion, miembros: [], archivado: false, creadoPor: '', createdAt: Date.now(),
      });
    }
    d.canalesSembrados = true; cambio = true;
  }
  if (d.v !== WS_V) { d.v = WS_V; cambio = true; }
  if (cambio) { try { wsSave(d); } catch (e) { console.warn('workspace seed:', e.message); } }
  return d;
}

// Quién está haciendo la request. Con ADMIN_AUTH_ENABLED=0 no hay sesión: cae a
// una identidad de sistema para que el panel siga usable en desarrollo.
function wsActor(req){
  const s = adminSessionFor(req);
  const username = (s && s.username) ? String(s.username).toLowerCase() : 'admin@local';
  const perfil = teamFindByUsername(username);
  return {
    username,
    role: (s && s.role) || 'admin',
    nombre: (perfil && (perfil.apodo || perfil.nombre)) || (s && (s.apodo || s.nombre)) || username,
    avatar: (perfil && perfil.avatar) || '',
    color: teamColor(perfil && perfil.color, username),
  };
}
// El roster del espacio: las cuentas de equipo + quien esté logueado ahora (que
// puede no tener registro propio si entró con la credencial de administrador).
// Sin esto, el admin no podría asignarse una tarea a sí mismo.
function wsUsuarios(req){
  const out = teamLoad().members.map(teamPublic);
  const yo = wsActor(req);
  if (!out.some(u => (u.username || '').toLowerCase() === yo.username)) {
    out.push({ id: 'sesion:' + yo.username, username: yo.username, email: yo.username, nombre: yo.nombre, apellido: '', apodo: '', role: yo.role === 'miembro' ? 'miembro' : 'admin', avatar: yo.avatar, color: yo.color, profileOnly: true, createdAt: null });
  }
  return wsAsignarHandles(out);
}
// Handle para las menciones del chat: la parte del correo antes de la arroba.
// Se resuelve acá, en un solo lugar, y viaja en el roster para que el front
// escriba exactamente el mismo @handle que el server después parsea.
function wsAsignarHandles(usuarios){
  const usados = new Set();
  // Por antigüedad: si dos correos comparten la parte de la izquierda, el
  // handle "limpio" queda para la cuenta más vieja y no se mueve nunca.
  const orden = usuarios.slice().sort((a, b) => (a.createdAt || Number.MAX_SAFE_INTEGER) - (b.createdAt || Number.MAX_SAFE_INTEGER));
  for (const u of orden) {
    const base = String(u.username || '').split('@')[0].toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9._-]/g, '') || 'user';
    let h = base, n = 2;
    while (usados.has(h)) h = base + (n++);
    usados.add(h); u.handle = h;
  }
  return usuarios;
}
const wsNombreUsuario = (usuarios, username) => {
  const u = usuarios.find(x => (x.username || '').toLowerCase() === String(username || '').toLowerCase());
  return u ? (u.apodo || u.nombre || u.username) : String(username || '');
};

// Notificar (campanita). destinos = usernames; nunca se notifica a quien hizo la
// acción — que te avise de lo que acabás de hacer vos es solo ruido.
function wsNotificar(d, destinos, { tipo, texto, tareaId = null, eventoId = null, canalId = null, de = '' }){
  const vistos = new Set();
  for (const raw of wsArr(destinos)) {
    const u = String(raw || '').toLowerCase();
    if (!u || u === String(de || '').toLowerCase() || vistos.has(u)) continue;
    vistos.add(u);
    d.notificaciones.push({ id: wsNewId('nt'), username: u, tipo, texto: wsStr(texto, 300), tareaId, eventoId, canalId, de: String(de || ''), ts: Date.now(), leida: false });
  }
  // Techo por persona: la campanita es un aviso, no un historial. Sin esto el
  // doc crece para siempre.
  const porUser = new Map();
  for (const n of d.notificaciones) { const a = porUser.get(n.username) || []; a.push(n); porUser.set(n.username, a); }
  let recortar = false;
  for (const a of porUser.values()) if (a.length > 200) recortar = true;
  if (recortar) {
    const keep = [];
    for (const a of porUser.values()) { a.sort((x, y) => y.ts - x.ts); keep.push(...a.slice(0, 200)); }
    d.notificaciones = keep.sort((x, y) => x.ts - y.ts);
  }
}

function wsProyecto(b, prev){
  const p = prev || { id: wsNewId('pr'), createdAt: Date.now(), archivado: false };
  if (b.nombre != null) p.nombre = wsStr(b.nombre, 80);
  if (b.color != null) p.color = teamColor(b.color, p.nombre || p.id);
  if (b.emoji != null) p.emoji = wsStr(b.emoji, 8);
  if (b.descripcion != null) p.descripcion = wsStr(b.descripcion, 600);
  if (b.responsable != null) p.responsable = wsStr(b.responsable, 120).toLowerCase();
  if (b.archivado != null) p.archivado = !!b.archivado;
  if (!p.color) p.color = teamColor(null, p.nombre || p.id);
  if (!p.emoji) p.emoji = '📁';
  return p;
}

// Normaliza una tarea desde el body. `prev` = tarea existente (edición parcial:
// solo se toca lo que vino en el body, así dos personas editando campos
// distintos no se pisan).
function wsTarea(d, b, prev, actor){
  const t = prev || {
    id: wsNewId('tk'), createdAt: Date.now(), creadoPor: actor.username,
    checklist: [], comentarios: [], etiquetas: [], asignados: [],
    auto: false, fuente: null, completadaAt: null,
  };
  if (b.titulo != null) t.titulo = wsStr(b.titulo, 200);
  if (b.descripcion != null) t.descripcion = wsStr(b.descripcion, 4000);
  if (b.proyectoId != null) {
    const pid = wsStr(b.proyectoId, 60);
    t.proyectoId = d.proyectos.some(p => p.id === pid) ? pid : '';
  }
  if (b.asignados != null) {
    const validos = new Set(teamLoad().members.map(m => (m.username || '').toLowerCase()));
    t.asignados = [...new Set(wsArr(b.asignados).map(x => wsStr(x, 120).toLowerCase()).filter(Boolean))]
      // Se acepta un username que no esté en team.json solo si es quien está
      // logueado (credencial de administrador sin registro propio).
      .filter(u => validos.has(u) || u === actor.username).slice(0, 12);
  }
  if (b.estado != null) {
    const e = wsStr(b.estado, 40);
    t.estado = d.estados.some(x => x.id === e) ? e : (d.estados[0] && d.estados[0].id) || 'por_hacer';
  }
  if (b.prioridad != null) t.prioridad = WS_PRIORIDADES.includes(String(b.prioridad)) ? String(b.prioridad) : 'media';
  if (b.vence != null) t.vence = wsFecha(b.vence);
  if (b.etiquetas != null) t.etiquetas = [...new Set(wsArr(b.etiquetas).map(x => wsStr(x, 40)).filter(Boolean))].slice(0, 12);
  if (b.checklist != null) {
    t.checklist = wsArr(b.checklist).slice(0, 60).map(it => ({
      id: wsStr(it && it.id, 60) || wsNewId('ck'),
      texto: wsStr(it && it.texto, 200),
      hecho: !!(it && it.hecho),
    })).filter(it => it.texto);
  }
  if (b.orden != null && isFinite(Number(b.orden))) t.orden = Number(b.orden);
  // Defaults de alta
  if (t.estado == null) t.estado = (d.estados[0] && d.estados[0].id) || 'por_hacer';
  if (t.prioridad == null) t.prioridad = 'media';
  if (t.vence == null) t.vence = '';
  if (t.proyectoId == null) t.proyectoId = '';
  if (t.orden == null) t.orden = Date.now();
  // Marca de completada: sirve para "listas esta semana" sin recorrer el log.
  const esListo = (d.estados.find(e => e.id === t.estado) || {}).id === 'listo';
  if (esListo && !t.completadaAt) t.completadaAt = Date.now();
  if (!esListo) t.completadaAt = null;
  t.updatedAt = Date.now();
  return t;
}

app.get('/admin/ws/bootstrap', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  res.json({
    me: yo, usuarios: wsUsuarios(req), estados: d.estados,
    proyectos: d.proyectos, tareas: d.tareas, eventos: d.eventos, prioridades: WS_PRIORIDADES,
    notificaciones: d.notificaciones.filter(n => n.username === yo.username).sort((a, b) => b.ts - a.ts).slice(0, 60),
  });
});

// ── Proyectos ──
app.post('/admin/ws/proyectos', requireAdmin, (req, res) => {
  const d = wsLoad();
  const p = wsProyecto(req.body || {}, null);
  if (!p.nombre) return res.status(400).json({ error: 'Ponele un nombre al proyecto.' });
  if (d.proyectos.some(x => wsStr(x.nombre).toLowerCase() === p.nombre.toLowerCase() && !x.archivado)) {
    return res.status(409).json({ error: 'Ya hay un proyecto activo con ese nombre.' });
  }
  d.proyectos.push(p); wsSave(d);
  res.json({ ok: true, proyecto: p });
});
app.put('/admin/ws/proyectos/:id', requireAdmin, (req, res) => {
  const d = wsLoad();
  const p = d.proyectos.find(x => x.id === req.params.id);
  if (!p) return res.status(404).json({ error: 'No se encontró el proyecto.' });
  wsProyecto(req.body || {}, p);
  if (!p.nombre) return res.status(400).json({ error: 'Ponele un nombre al proyecto.' });
  wsSave(d);
  res.json({ ok: true, proyecto: p });
});
app.delete('/admin/ws/proyectos/:id', requireAdmin, (req, res) => {
  const d = wsLoad();
  const p = d.proyectos.find(x => x.id === req.params.id);
  if (!p) return res.status(404).json({ error: 'No se encontró el proyecto.' });
  const conTareas = d.tareas.filter(t => t.proyectoId === p.id).length;
  // Con tareas adentro no se borra: se archiva. Borrarlo dejaría las tareas
  // huérfanas sin que nadie se entere.
  if (conTareas && !req.query.forzar) {
    p.archivado = true; wsSave(d);
    return res.json({ ok: true, archivado: true, tareas: conTareas });
  }
  d.proyectos = d.proyectos.filter(x => x.id !== p.id);
  for (const t of d.tareas) if (t.proyectoId === p.id) t.proyectoId = '';
  wsSave(d);
  res.json({ ok: true, archivado: false });
});

// ── Tareas ──
app.post('/admin/ws/tareas', requireAdmin, (req, res) => {
  const d = wsLoad();
  const actor = wsActor(req);
  const t = wsTarea(d, req.body || {}, null, actor);
  if (!t.titulo) return res.status(400).json({ error: 'Ponele un título a la tarea.' });
  d.tareas.push(t);
  const usuarios = wsUsuarios(req);
  wsNotificar(d, t.asignados, {
    tipo: 'asignacion', de: actor.username, tareaId: t.id,
    texto: `${actor.nombre} te asignó “${t.titulo}”`,
  });
  wsSave(d);
  res.json({ ok: true, tarea: t, notificados: t.asignados.filter(u => u !== actor.username).map(u => wsNombreUsuario(usuarios, u)) });
});
app.put('/admin/ws/tareas/:id', requireAdmin, (req, res) => {
  const d = wsLoad();
  const t = d.tareas.find(x => x.id === req.params.id);
  if (!t) return res.status(404).json({ error: 'No se encontró la tarea.' });
  const actor = wsActor(req);
  const antes = { asignados: (t.asignados || []).slice(), estado: t.estado };
  wsTarea(d, req.body || {}, t, actor);
  if (!t.titulo) return res.status(400).json({ error: 'Ponele un título a la tarea.' });
  // Solo se avisa a los NUEVOS asignados: re-notificar a los de siempre en cada
  // edición convierte la campanita en spam y deja de mirarse.
  const nuevos = (t.asignados || []).filter(u => !antes.asignados.includes(u));
  if (nuevos.length) wsNotificar(d, nuevos, { tipo: 'asignacion', de: actor.username, tareaId: t.id, texto: `${actor.nombre} te asignó “${t.titulo}”` });
  if (antes.estado !== t.estado && t.completadaAt) {
    wsNotificar(d, [t.creadoPor, ...antes.asignados], { tipo: 'completada', de: actor.username, tareaId: t.id, texto: `${actor.nombre} completó “${t.titulo}”` });
  }
  wsSave(d);
  res.json({ ok: true, tarea: t });
});
// Mover en el tablero: cambia estado y/o posición. Endpoint aparte del PUT
// porque el drag & drop dispara muchas veces y tiene que ser lo más barato
// posible — y porque el PUT toca campos que el arrastre no debería tocar.
app.post('/admin/ws/tareas/:id/mover', requireAdmin, (req, res) => {
  const d = wsLoad();
  const t = d.tareas.find(x => x.id === req.params.id);
  if (!t) return res.status(404).json({ error: 'No se encontró la tarea.' });
  const b = req.body || {};
  const actor = wsActor(req);
  const estadoAntes = t.estado;
  if (b.estado != null) {
    const e = wsStr(b.estado, 40);
    if (!d.estados.some(x => x.id === e)) return res.status(400).json({ error: 'Estado inválido.' });
    t.estado = e;
  }
  // Reordenar dentro de la columna: el cliente manda la lista de ids en el
  // orden en que quedaron. Se numera de 10 en 10 por si hay que insertar.
  if (Array.isArray(b.orden)) {
    b.orden.forEach((id, i) => { const x = d.tareas.find(y => y.id === id); if (x) x.orden = (i + 1) * 10; });
  }
  const esListo = t.estado === 'listo';
  if (esListo && !t.completadaAt) t.completadaAt = Date.now();
  if (!esListo) t.completadaAt = null;
  t.updatedAt = Date.now();
  if (estadoAntes !== t.estado && esListo) {
    wsNotificar(d, [t.creadoPor, ...(t.asignados || [])], { tipo: 'completada', de: actor.username, tareaId: t.id, texto: `${actor.nombre} completó “${t.titulo}”` });
  }
  wsSave(d);
  res.json({ ok: true, tarea: t });
});
app.post('/admin/ws/tareas/:id/comentario', requireAdmin, (req, res) => {
  const d = wsLoad();
  const t = d.tareas.find(x => x.id === req.params.id);
  if (!t) return res.status(404).json({ error: 'No se encontró la tarea.' });
  const actor = wsActor(req);
  const texto = wsStr((req.body || {}).texto, 2000);
  if (!texto) return res.status(400).json({ error: 'Escribí algo.' });
  const c = { id: wsNewId('cm'), autor: actor.username, texto, ts: Date.now() };
  t.comentarios = wsArr(t.comentarios); t.comentarios.push(c);
  t.updatedAt = Date.now();
  wsNotificar(d, [t.creadoPor, ...(t.asignados || [])], { tipo: 'comentario', de: actor.username, tareaId: t.id, texto: `${actor.nombre} comentó en “${t.titulo}”` });
  wsSave(d);
  res.json({ ok: true, comentario: c, tarea: t });
});
app.delete('/admin/ws/tareas/:id', requireAdmin, (req, res) => {
  const d = wsLoad();
  const n = d.tareas.length;
  d.tareas = d.tareas.filter(x => x.id !== req.params.id);
  if (d.tareas.length === n) return res.status(404).json({ error: 'No se encontró la tarea.' });
  d.notificaciones = d.notificaciones.filter(x => x.tareaId !== req.params.id);
  wsSave(d);
  res.json({ ok: true });
});

// ── Calendario: eventos y reuniones ──────────────────────────────────────────
// Un evento es una fecha del calendario con hora opcional. `tipo` distingue una
// reunión (con participantes y link) de un hito suelto, pero el modelo es el
// mismo: no vale la pena partirlo en dos.
const WS_EVENTO_TIPOS = ['reunion', 'evento'];
const WS_TZ = 'America/Santiago';
// "HH:MM" en 24h, o vacío.
const wsHora = (v) => /^([01]\d|2[0-3]):([0-5]\d)$/.test(String(v || '')) ? String(v) : '';

function wsEvento(d, b, prev, actor){
  const e = prev || { id: wsNewId('ev'), createdAt: Date.now(), creadoPor: actor.username, participantes: [] };
  if (b.titulo != null) e.titulo = wsStr(b.titulo, 200);
  if (b.tipo != null) e.tipo = WS_EVENTO_TIPOS.includes(String(b.tipo)) ? String(b.tipo) : 'reunion';
  if (b.fecha != null) e.fecha = wsFecha(b.fecha);
  if (b.todoElDia != null) e.todoElDia = !!b.todoElDia;
  if (b.horaInicio != null) e.horaInicio = wsHora(b.horaInicio);
  if (b.horaFin != null) e.horaFin = wsHora(b.horaFin);
  if (b.lugar != null) e.lugar = wsStr(b.lugar, 200);
  if (b.link != null) {
    // Solo http(s): un javascript: acá terminaría siendo un enlace clickeable
    // para todo el equipo.
    const u = wsStr(b.link, 500);
    e.link = /^https?:\/\//i.test(u) ? u : '';
  }
  if (b.descripcion != null) e.descripcion = wsStr(b.descripcion, 4000);
  if (b.color != null) e.color = teamColor(b.color, e.titulo || e.id);
  if (b.participantes != null) {
    const validos = new Set(teamLoad().members.map(m => (m.username || '').toLowerCase()));
    e.participantes = [...new Set(wsArr(b.participantes).map(x => wsStr(x, 120).toLowerCase()).filter(Boolean))]
      .filter(u => validos.has(u) || u === actor.username).slice(0, 40);
  }
  if (e.tipo == null) e.tipo = 'reunion';
  if (e.todoElDia == null) e.todoElDia = false;
  if (e.horaInicio == null) e.horaInicio = '';
  if (e.horaFin == null) e.horaFin = '';
  if (e.lugar == null) e.lugar = '';
  if (e.link == null) e.link = '';
  if (e.descripcion == null) e.descripcion = '';
  if (!e.color) e.color = e.tipo === 'reunion' ? '#4a90d9' : '#f5a623';
  // Sin hora de inicio no hay franja horaria que mostrar: es de día completo.
  if (!e.horaInicio) { e.todoElDia = true; e.horaFin = ''; }
  // Fin antes que inicio no significa nada; se descarta en vez de guardar basura.
  if (e.horaFin && e.horaFin <= e.horaInicio) e.horaFin = '';
  e.updatedAt = Date.now();
  return e;
}

// Cuándo empieza/termina un evento, en formato lindo para el aviso.
function wsEventoCuando(e){
  const [a, m, dd] = String(e.fecha || '').split('-');
  const dia = (dd && m) ? `${dd}/${m}` : '';
  if (e.todoElDia || !e.horaInicio) return dia;
  return dia + ' a las ' + e.horaInicio;
}

app.post('/admin/ws/eventos', requireAdmin, (req, res) => {
  const d = wsLoad();
  const actor = wsActor(req);
  const e = wsEvento(d, req.body || {}, null, actor);
  if (!e.titulo) return res.status(400).json({ error: 'Ponele un título a la reunión.' });
  if (!e.fecha) return res.status(400).json({ error: 'Elegí una fecha.' });
  d.eventos.push(e);
  const usuarios = wsUsuarios(req);
  wsNotificar(d, e.participantes, {
    tipo: 'invitacion', de: actor.username, eventoId: e.id,
    texto: `${actor.nombre} te invitó a “${e.titulo}” · ${wsEventoCuando(e)}`,
  });
  wsSave(d);
  res.json({ ok: true, evento: e, invitados: e.participantes.filter(u => u !== actor.username).map(u => wsNombreUsuario(usuarios, u)) });
});
app.put('/admin/ws/eventos/:id', requireAdmin, (req, res) => {
  const d = wsLoad();
  const e = d.eventos.find(x => x.id === req.params.id);
  if (!e) return res.status(404).json({ error: 'No se encontró el evento.' });
  const actor = wsActor(req);
  const antes = { participantes: (e.participantes || []).slice(), fecha: e.fecha, horaInicio: e.horaInicio };
  wsEvento(d, req.body || {}, e, actor);
  if (!e.titulo) return res.status(400).json({ error: 'Ponele un título a la reunión.' });
  if (!e.fecha) return res.status(400).json({ error: 'Elegí una fecha.' });
  // A los nuevos, invitación. A los que ya estaban, aviso SOLO si se movió el
  // día o la hora — que es lo único que les cambia la agenda.
  const nuevos = (e.participantes || []).filter(u => !antes.participantes.includes(u));
  if (nuevos.length) wsNotificar(d, nuevos, { tipo: 'invitacion', de: actor.username, eventoId: e.id, texto: `${actor.nombre} te invitó a “${e.titulo}” · ${wsEventoCuando(e)}` });
  if (antes.fecha !== e.fecha || antes.horaInicio !== e.horaInicio) {
    const viejos = (e.participantes || []).filter(u => antes.participantes.includes(u));
    if (viejos.length) wsNotificar(d, viejos, { tipo: 'reagendada', de: actor.username, eventoId: e.id, texto: `${actor.nombre} movió “${e.titulo}” a ${wsEventoCuando(e)}` });
  }
  wsSave(d);
  res.json({ ok: true, evento: e });
});
app.delete('/admin/ws/eventos/:id', requireAdmin, (req, res) => {
  const d = wsLoad();
  const e = d.eventos.find(x => x.id === req.params.id);
  if (!e) return res.status(404).json({ error: 'No se encontró el evento.' });
  const actor = wsActor(req);
  d.eventos = d.eventos.filter(x => x.id !== e.id);
  wsNotificar(d, e.participantes, { tipo: 'cancelada', de: actor.username, texto: `${actor.nombre} canceló “${e.titulo}” (${wsEventoCuando(e)})` });
  d.notificaciones = d.notificaciones.filter(x => x.eventoId !== e.id);
  wsSave(d);
  res.json({ ok: true });
});

// ── Exportar a Google Calendar (.ics) ────────────────────────────────────────
// Se emite en UTC (sufijo Z) en vez de TZID+VTIMEZONE: es lo que interpreta
// igual cualquier cliente, sin depender de que traiga la definición de la zona.
// Chile cambia de huso dos veces al año, así que el offset se resuelve con Intl
// para la fecha concreta del evento — no con una constante.
function wsOffsetMin(tz, fecha){
  const p = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour12: false, year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit' })
    .formatToParts(fecha).reduce((a, x) => (a[x.type] = x.value, a), {});
  const comoUTC = Date.UTC(+p.year, +p.month - 1, +p.day, (+p.hour) % 24, +p.minute, +p.second);
  return (comoUTC - fecha.getTime()) / 60000;
}
function wsLocalAUTC(tz, iso, hhmm){
  const [a, m, d] = iso.split('-').map(Number);
  const [h, mi] = String(hhmm || '00:00').split(':').map(Number);
  const base = Date.UTC(a, m - 1, d, h, mi, 0);
  let ts = base;
  // Dos pasadas alcanzan salvo en el salto de horario, donde la tercera cierra.
  for (let i = 0; i < 3; i++) {
    const sig = base - wsOffsetMin(tz, new Date(ts)) * 60000;
    if (sig === ts) break;
    ts = sig;
  }
  return new Date(ts);
}
const wsIcsUTC = (dt) => dt.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
const wsIcsFecha = (iso) => String(iso || '').replace(/-/g, '');
const wsIcsTexto = (s) => String(s == null ? '' : s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
// Plegado a 75 octetos, como pide el RFC 5545: sin esto, una descripción larga
// rompe el archivo en algunos clientes.
function wsIcsFold(linea){
  const b = Buffer.from(linea, 'utf-8');
  if (b.length <= 75) return linea;
  const out = []; let i = 0;
  while (i < b.length) {
    let n = Math.min(i === 0 ? 75 : 74, b.length - i);
    // No cortar en medio de un carácter multibyte.
    while (n > 1 && (b[i + n] & 0xc0) === 0x80) n--;
    out.push((i === 0 ? '' : ' ') + b.slice(i, i + n).toString('utf-8'));
    i += n;
  }
  return out.join('\r\n');
}
function wsEventoIcs(e, usuarios){
  const L = ['BEGIN:VEVENT', 'UID:' + e.id + '@k-bros.cl', 'DTSTAMP:' + wsIcsUTC(new Date())];
  if (e.todoElDia || !e.horaInicio) {
    const fin = new Date(wsLocalAUTC('UTC', e.fecha, '00:00').getTime() + 86400000);
    L.push('DTSTART;VALUE=DATE:' + wsIcsFecha(e.fecha));
    L.push('DTEND;VALUE=DATE:' + wsIcsFecha(fin.toISOString().slice(0, 10)));
  } else {
    const ini = wsLocalAUTC(WS_TZ, e.fecha, e.horaInicio);
    // Sin hora de fin se asume una hora, que es lo que espera cualquier agenda.
    const fin = e.horaFin ? wsLocalAUTC(WS_TZ, e.fecha, e.horaFin) : new Date(ini.getTime() + 3600000);
    L.push('DTSTART:' + wsIcsUTC(ini));
    L.push('DTEND:' + wsIcsUTC(fin));
  }
  L.push('SUMMARY:' + wsIcsTexto(e.titulo));
  const cuerpo = [e.descripcion, e.link ? 'Link: ' + e.link : ''].filter(Boolean).join('\n');
  if (cuerpo) L.push('DESCRIPTION:' + wsIcsTexto(cuerpo));
  // Google muestra el link de videollamada si viene en LOCATION.
  const donde = e.lugar || e.link;
  if (donde) L.push('LOCATION:' + wsIcsTexto(donde));
  const org = usuarios.find(u => (u.username || '').toLowerCase() === String(e.creadoPor || '').toLowerCase());
  if (org) L.push('ORGANIZER;CN=' + wsIcsTexto(org.apodo || org.nombre || org.username) + ':mailto:' + (org.email || org.username));
  for (const p of (e.participantes || [])) {
    const u = usuarios.find(x => (x.username || '').toLowerCase() === p);
    L.push('ATTENDEE;CN=' + wsIcsTexto(u ? (u.apodo || u.nombre || u.username) : p) + ';RSVP=TRUE:mailto:' + ((u && u.email) || p));
  }
  L.push('END:VEVENT');
  return L;
}
function wsIcsDoc(eventos, usuarios){
  const L = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//K-BROS//Espacio de trabajo//ES', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH'];
  for (const e of eventos) L.push(...wsEventoIcs(e, usuarios));
  L.push('END:VCALENDAR');
  return L.map(wsIcsFold).join('\r\n') + '\r\n';
}
const wsIcsNombre = (s) => (String(s || 'evento').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase() || 'evento');

app.get('/admin/ws/eventos/:id/ics', requireAdmin, (req, res) => {
  const d = wsLoad();
  const e = d.eventos.find(x => x.id === req.params.id);
  if (!e) return res.status(404).json({ error: 'No se encontró el evento.' });
  res.setHeader('Content-Type', 'text/calendar; charset=utf-8');
  res.setHeader('Content-Disposition', `attachment; filename="${wsIcsNombre(e.titulo)}.ics"`);
  res.send(wsIcsDoc([e], wsUsuarios(req)));
});
// Todo mi calendario en un archivo, para importarlo de una a Google.
app.get('/admin/ws/calendario.ics', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const mios = d.eventos.filter(e => (e.participantes || []).includes(yo.username) || e.creadoPor === yo.username);
  res.setHeader('Content-Type', 'text/calendar; charset=utf-8');
  res.setHeader('Content-Disposition', 'attachment; filename="k-bros-calendario.ics"');
  res.send(wsIcsDoc(mios, wsUsuarios(req)));
});

// ── Chat interno: canales y mensajes directos ────────────────────────────────
// Un canal y un mensaje directo son la misma cosa con distinto `tipo`: así hay
// un solo almacén de mensajes, un solo contador de no leídos y un solo buscador.
//  · tipo 'canal' → lo ve todo el equipo. Solo un admin los crea/edita/borra.
//  · tipo 'dm'    → solo sus dos `miembros`. Cualquiera puede abrir uno.
// Lo leído se guarda como una marca de tiempo por persona y canal
// (`lecturas[username][canalId]`), no como un flag por mensaje: es O(1) para
// escribir y sobrevive a que alguien borre mensajes.
const WS_MSJ_MAX = 2000;          // por canal; más viejos se recortan al guardar
const WS_MSJ_LARGO = 4000;

const wsCanalNombre = (v) => wsStr(v, 40).toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);

function wsCanalVisible(c, username){
  if (!c) return false;
  if (c.tipo === 'dm') return (c.miembros || []).includes(username);
  return !c.archivado;
}
const wsCanalPublico = (c, usuarios, yo) => {
  if (c.tipo !== 'dm') return { ...c };
  // Un DM se muestra con el nombre del OTRO, no con el propio.
  const otro = (c.miembros || []).find(u => u !== yo) || yo;
  return { ...c, nombre: wsNombreUsuario(usuarios, otro), conQuien: otro };
};

// Menciones: se resuelven contra los handles del roster. `@todos` avisa a todo
// el canal — en un DM no tiene sentido, así que ahí se ignora.
function wsMenciones(texto, usuarios, canal){
  const porHandle = new Map(usuarios.map(u => [u.handle, u.username]));
  const out = new Set();
  for (const m of String(texto || '').matchAll(/(^|[^a-z0-9@._-])@([a-z0-9._-]{1,60})/gi)) {
    const h = String(m[2]).toLowerCase().replace(/[._-]+$/, '');  // no comerse el punto final de la frase
    if (h === 'todos' || h === 'canal') {
      if (canal && canal.tipo !== 'dm') for (const u of usuarios) out.add(u.username);
    } else if (porHandle.has(h)) out.add(porHandle.get(h));
  }
  return [...out];
}

// Quién tiene que enterarse de un mensaje: en un DM, el otro; en un canal,
// solo los mencionados. Avisar de cada mensaje de cada canal sería insufrible.
function wsChatDestinos(canal, menciones, usuarios, autor){
  if (canal.tipo === 'dm') return (canal.miembros || []).filter(u => u !== autor);
  return menciones.filter(u => u !== autor);
}

function wsNoLeidos(d, canal, username){
  const marca = ((d.lecturas || {})[username] || {})[canal.id] || 0;
  return d.mensajes.filter(m => m.canalId === canal.id && m.ts > marca && m.autor !== username).length;
}

app.get('/admin/ws/chat', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const usuarios = wsUsuarios(req);
  const canales = d.canales.filter(c => wsCanalVisible(c, yo.username)).map(c => {
    const suyos = d.mensajes.filter(m => m.canalId === c.id);
    const ultimo = suyos.length ? suyos[suyos.length - 1] : null;
    return {
      ...wsCanalPublico(c, usuarios, yo.username),
      noLeidos: wsNoLeidos(d, c, yo.username),
      ultimoTs: ultimo ? ultimo.ts : 0,
      ultimoTexto: ultimo ? wsStr(ultimo.texto, 90) : '',
      ultimoAutor: ultimo ? ultimo.autor : '',
    };
  });
  // Canales por nombre; los DM por actividad, que es como se usan.
  canales.sort((a, b) => (a.tipo === 'dm' ? 1 : 0) - (b.tipo === 'dm' ? 1 : 0)
    || (a.tipo === 'dm' ? b.ultimoTs - a.ultimoTs : String(a.nombre).localeCompare(String(b.nombre), 'es')));
  res.json({ canales, totalNoLeidos: canales.reduce((s, c) => s + c.noLeidos, 0), usuarios });
});

// Buscador. Va antes que /:id para que "buscar" no se lea como un id de canal.
app.get('/admin/ws/chat/buscar', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const usuarios = wsUsuarios(req);
  const q = wsStr(req.query.q, 120).toLowerCase();
  if (q.length < 2) return res.json({ resultados: [], q });
  const visibles = new Map(d.canales.filter(c => wsCanalVisible(c, yo.username)).map(c => [c.id, c]));
  const resultados = d.mensajes
    .filter(m => visibles.has(m.canalId) && String(m.texto || '').toLowerCase().includes(q))
    .sort((a, b) => b.ts - a.ts).slice(0, 60)
    .map(m => ({ ...m, canal: wsCanalPublico(visibles.get(m.canalId), usuarios, yo.username) }));
  res.json({ resultados, q });
});

app.post('/admin/ws/chat/dm', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const otro = wsStr((req.body || {}).username, 120).toLowerCase();
  if (!otro || otro === yo.username) return res.status(400).json({ error: 'Elegí a otra persona.' });
  const usuarios = wsUsuarios(req);
  if (!usuarios.some(u => (u.username || '').toLowerCase() === otro)) return res.status(404).json({ error: 'Esa persona no está en el equipo.' });
  const par = [yo.username, otro].sort();
  // Idempotente: si el DM ya existe se devuelve ese, no se crea otro.
  let c = d.canales.find(x => x.tipo === 'dm' && (x.miembros || []).slice().sort().join('|') === par.join('|'));
  if (!c) {
    c = { id: wsNewId('dm'), tipo: 'dm', nombre: '', emoji: '', descripcion: '', miembros: par, archivado: false, creadoPor: yo.username, createdAt: Date.now() };
    d.canales.push(c); wsSave(d);
  }
  res.json({ ok: true, canal: wsCanalPublico(c, usuarios, yo.username) });
});

app.get('/admin/ws/chat/:id/mensajes', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const c = d.canales.find(x => x.id === req.params.id);
  if (!wsCanalVisible(c, yo.username)) return res.status(404).json({ error: 'No se encontró el canal.' });
  // `desde` es para el sondeo: solo lo nuevo. Sin él, el último tramo.
  const desde = Number(req.query.desde || 0);
  const todos = d.mensajes.filter(m => m.canalId === c.id);
  const mensajes = desde ? todos.filter(m => m.ts > desde) : todos.slice(-120);
  res.json({ canal: wsCanalPublico(c, wsUsuarios(req), yo.username), mensajes, hayMas: !desde && todos.length > 120 });
});

app.post('/admin/ws/chat/:id/mensajes', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const c = d.canales.find(x => x.id === req.params.id);
  if (!wsCanalVisible(c, yo.username)) return res.status(404).json({ error: 'No se encontró el canal.' });
  const texto = wsStr((req.body || {}).texto, WS_MSJ_LARGO);
  const tareaId = wsStr((req.body || {}).tareaId, 60);
  if (!texto && !tareaId) return res.status(400).json({ error: 'Escribí algo.' });
  const usuarios = wsUsuarios(req);
  const menciones = wsMenciones(texto, usuarios, c);
  const m = {
    id: wsNewId('ms'), canalId: c.id, autor: yo.username, texto, ts: Date.now(),
    menciones, tareaId: d.tareas.some(t => t.id === tareaId) ? tareaId : '',
  };
  d.mensajes.push(m);
  // Recorte por canal: el doc se relee entero en cada request, no puede crecer
  // para siempre.
  const delCanal = d.mensajes.filter(x => x.canalId === c.id);
  if (delCanal.length > WS_MSJ_MAX) {
    const sobran = new Set(delCanal.slice(0, delCanal.length - WS_MSJ_MAX).map(x => x.id));
    d.mensajes = d.mensajes.filter(x => !sobran.has(x.id));
  }
  const etiqueta = c.tipo === 'dm' ? 'te escribió' : ('te nombró en #' + c.nombre);
  wsNotificar(d, wsChatDestinos(c, menciones, usuarios, yo.username), {
    tipo: c.tipo === 'dm' ? 'dm' : 'mencion', de: yo.username, canalId: c.id,
    texto: `${yo.nombre} ${etiqueta}: ${wsStr(texto, 90)}`,
  });
  // Escribir ya cuenta como leído hasta acá.
  d.lecturas[yo.username] = d.lecturas[yo.username] || {};
  d.lecturas[yo.username][c.id] = m.ts;
  wsSave(d);
  res.json({ ok: true, mensaje: m });
});

app.post('/admin/ws/chat/:id/leido', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const c = d.canales.find(x => x.id === req.params.id);
  if (!wsCanalVisible(c, yo.username)) return res.status(404).json({ error: 'No se encontró el canal.' });
  const ts = Number((req.body || {}).ts) || Date.now();
  d.lecturas[yo.username] = d.lecturas[yo.username] || {};
  // Nunca hacia atrás: dos pestañas abiertas no se pisan la marca entre sí.
  if (ts > (d.lecturas[yo.username][c.id] || 0)) { d.lecturas[yo.username][c.id] = ts; wsSave(d); }
  res.json({ ok: true });
});

// ── Administrar canales (solo admin) ──
function wsSoloAdmin(req, res){
  if (wsActor(req).role === 'miembro') { res.status(403).json({ error: 'Solo un admin puede administrar los canales.' }); return false; }
  return true;
}
app.post('/admin/ws/canales', requireAdmin, (req, res) => {
  if (!wsSoloAdmin(req, res)) return;
  const d = wsLoad();
  const b = req.body || {};
  const nombre = wsCanalNombre(b.nombre);
  if (!nombre) return res.status(400).json({ error: 'Ponele un nombre al canal.' });
  if (d.canales.some(c => c.tipo !== 'dm' && wsStr(c.nombre).toLowerCase() === nombre)) return res.status(409).json({ error: 'Ya existe un canal con ese nombre.' });
  const c = {
    id: wsNewId('cn'), tipo: 'canal', nombre, emoji: wsStr(b.emoji, 8) || '💬',
    descripcion: wsStr(b.descripcion, 300), miembros: [], archivado: false,
    creadoPor: wsActor(req).username, createdAt: Date.now(),
  };
  d.canales.push(c); wsSave(d);
  res.json({ ok: true, canal: c });
});
app.put('/admin/ws/canales/:id', requireAdmin, (req, res) => {
  if (!wsSoloAdmin(req, res)) return;
  const d = wsLoad();
  const c = d.canales.find(x => x.id === req.params.id && x.tipo !== 'dm');
  if (!c) return res.status(404).json({ error: 'No se encontró el canal.' });
  const b = req.body || {};
  if (b.nombre != null) {
    const nombre = wsCanalNombre(b.nombre);
    if (!nombre) return res.status(400).json({ error: 'Ponele un nombre al canal.' });
    if (d.canales.some(x => x.id !== c.id && x.tipo !== 'dm' && wsStr(x.nombre).toLowerCase() === nombre)) return res.status(409).json({ error: 'Ya existe un canal con ese nombre.' });
    c.nombre = nombre;
  }
  if (b.emoji != null) c.emoji = wsStr(b.emoji, 8) || '💬';
  if (b.descripcion != null) c.descripcion = wsStr(b.descripcion, 300);
  if (b.archivado != null) c.archivado = !!b.archivado;
  wsSave(d);
  res.json({ ok: true, canal: c });
});
app.delete('/admin/ws/canales/:id', requireAdmin, (req, res) => {
  if (!wsSoloAdmin(req, res)) return;
  const d = wsLoad();
  const c = d.canales.find(x => x.id === req.params.id && x.tipo !== 'dm');
  if (!c) return res.status(404).json({ error: 'No se encontró el canal.' });
  const conMensajes = d.mensajes.filter(m => m.canalId === c.id).length;
  // Con conversación adentro se archiva: borrarlo se llevaría el historial del
  // equipo sin que nadie pueda recuperarlo.
  if (conMensajes && !req.query.forzar) {
    c.archivado = true; wsSave(d);
    return res.json({ ok: true, archivado: true, mensajes: conMensajes });
  }
  d.canales = d.canales.filter(x => x.id !== c.id);
  d.mensajes = d.mensajes.filter(m => m.canalId !== c.id);
  d.notificaciones = d.notificaciones.filter(n => n.canalId !== c.id);
  wsSave(d);
  res.json({ ok: true, archivado: false });
});

// ── Metas personales ─────────────────────────────────────────────────────────
// Objetivos del mes de cada persona. Son PRIVADAS salvo que el dueño las marque
// como compartidas: el filtro se hace en el server, nunca mandando todo y
// escondiendo en el front.
const WS_METAS_MAX = 40;   // por persona y mes
const wsPeriodoActual = () => new Intl.DateTimeFormat('en-CA', { timeZone: WS_TZ, year: 'numeric', month: '2-digit' }).format(new Date()).slice(0, 7);
const wsPeriodo = (v) => /^\d{4}-(0[1-9]|1[0-2])$/.test(String(v || '')) ? String(v) : wsPeriodoActual();

app.get('/admin/ws/metas', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const periodo = wsPeriodo(req.query.periodo);
  const usuarios = wsUsuarios(req);
  const delMes = d.metas.filter(m => m.periodo === periodo);
  const mias = delMes.filter(m => m.username === yo.username).sort((a, b) => (a.orden || 0) - (b.orden || 0));
  const compartidas = delMes.filter(m => m.username !== yo.username && m.compartida)
    .map(m => ({ ...m, autor: wsNombreUsuario(usuarios, m.username) }))
    .sort((a, b) => String(a.autor).localeCompare(String(b.autor), 'es') || (a.orden || 0) - (b.orden || 0));
  res.json({ periodo, mias, compartidas, cumplidas: mias.filter(m => m.hecho).length, total: mias.length });
});
app.post('/admin/ws/metas', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const b = req.body || {};
  const titulo = wsStr(b.titulo, 200);
  if (!titulo) return res.status(400).json({ error: 'Escribí la meta.' });
  const periodo = wsPeriodo(b.periodo);
  const mias = d.metas.filter(m => m.username === yo.username && m.periodo === periodo);
  if (mias.length >= WS_METAS_MAX) return res.status(400).json({ error: `Máximo ${WS_METAS_MAX} metas por mes.` });
  const meta = {
    id: wsNewId('mt'), username: yo.username, periodo, titulo,
    descripcion: wsStr(b.descripcion, 600), hecho: false, compartida: !!b.compartida,
    orden: (mias.length + 1) * 10, createdAt: Date.now(), completadaAt: null,
  };
  d.metas.push(meta); wsSave(d);
  res.json({ ok: true, meta });
});
app.put('/admin/ws/metas/:id', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const m = d.metas.find(x => x.id === req.params.id);
  if (!m) return res.status(404).json({ error: 'No se encontró la meta.' });
  // Solo el dueño. Una meta ajena no se toca ni siendo admin: son personales.
  if (m.username !== yo.username) return res.status(403).json({ error: 'Esa meta es de otra persona.' });
  const b = req.body || {};
  if (b.titulo != null) { const t = wsStr(b.titulo, 200); if (!t) return res.status(400).json({ error: 'Escribí la meta.' }); m.titulo = t; }
  if (b.descripcion != null) m.descripcion = wsStr(b.descripcion, 600);
  if (b.compartida != null) m.compartida = !!b.compartida;
  if (b.hecho != null) { m.hecho = !!b.hecho; m.completadaAt = m.hecho ? Date.now() : null; }
  wsSave(d);
  res.json({ ok: true, meta: m });
});
app.delete('/admin/ws/metas/:id', requireAdmin, (req, res) => {
  const d = wsLoad();
  const yo = wsActor(req);
  const m = d.metas.find(x => x.id === req.params.id);
  if (!m) return res.status(404).json({ error: 'No se encontró la meta.' });
  if (m.username !== yo.username) return res.status(403).json({ error: 'Esa meta es de otra persona.' });
  d.metas = d.metas.filter(x => x.id !== m.id); wsSave(d);
  res.json({ ok: true });
});

// ── Tareas automáticas desde los otros módulos ───────────────────────────────
// El ERP ya sabe cuándo algo necesita atención; lo que faltaba era que eso
// llegara a la lista de alguien en vez de quedar en un cartelito que se mira
// una vez. Cada detector devuelve "hallazgos" con una CLAVE estable, y el
// espacio los convierte en tareas.
//
// Tres reglas que hacen que esto no se vuelva insoportable:
//  1. Dedupe por clave, para siempre. Si ya se creó la tarea de un hallazgo, no
//     se vuelve a crear — ni aunque la hayan completado. Nada peor que una
//     tarea que reaparece después de resolverla.
//  2. Techo de tareas ABIERTAS por detector. Si hay 10 sin atender, no se
//     agregan más hasta que se cierren algunas: evita que el primer escaneo
//     sobre datos viejos entierre el tablero.
//  3. Si un detector falla (Shopify caído, un archivo raro), se salta ese y los
//     demás siguen. Un módulo roto no puede tumbar el escaneo entero.
const WS_AUTO_PROYECTO = 'Alertas del sistema';
const WS_AUTO_MAX_ABIERTAS = 10;
// Cuánto puede pasarse un plato de su propio objetivo de costo antes de que
// valga la pena avisar. Es tolerancia para no hacer ruido por redondeos: el
// objetivo de cada plato ya lo define el usuario en `margenPct`.
const WS_AUTO_COSTEO_HOLGURA = 5;

function wsAutoProyectoId(d){
  let p = d.proyectos.find(x => wsStr(x.nombre).toLowerCase() === WS_AUTO_PROYECTO.toLowerCase());
  if (!p) {
    p = { id: wsNewId('pr'), nombre: WS_AUTO_PROYECTO, color: '#d9534f', emoji: '🔔',
      descripcion: 'Tareas que genera solo el ERP cuando detecta algo que revisar.',
      responsable: '', archivado: false, createdAt: Date.now() };
    d.proyectos.push(p);
  }
  if (p.archivado) p.archivado = false;   // si vuelve a haber alertas, se desarchiva
  return p.id;
}
// A quién se le asignan: la cuenta admin más antigua, que es la dueña del
// panel. Si el hallazgo sugiere otra persona, gana esa.
function wsAutoResponsable(){
  const admins = teamLoad().members.filter(m => teamRol(m.role) === 'admin')
    .sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
  return admins.length ? admins[0].username : '';
}

// Códigos → hallazgos. Aparte del detector para poder probarlo sin depender de
// que Shopify conteste: la lectura remota es una línea, el criterio es esto.
function wsAutoHallazgosCodigos(codigos){
  const vistos = new Set();
  const out = [];
  for (const raw of wsArr(codigos)) {
    const code = wsStr(raw, 80).toUpperCase();
    if (!code || vistos.has(code)) continue;   // el mismo código en varios pedidos es UNA alerta
    vistos.add(code);
    out.push({
      clave: 'codigo:' + code,
      titulo: `Clasificar código ${code}`,
      prioridad: 'alta',
      etiquetas: ['ingresos'],
      descripcion: `El Estado de Resultado encontró pedidos con el código de descuento «${code}» y no sabe a qué canal imputarlos.\n\n`
        + `Mientras no esté clasificado, esas ventas no se suman al canal que corresponde. Hay que mapearlo indicando canal, local y razón social.`,
    });
  }
  return out;
}

const WS_AUTO_DETECTORES = [
  {
    id: 'codigos_nuevos',
    label: 'Códigos de descuento sin clasificar',
    // Ingreso por Venta ya detecta los códigos que no están en el diccionario;
    // hasta ahora eso solo salía como aviso en pantalla.
    async hallazgos(){
      const est = await estadoResolve(wsPeriodoActual(), null);
      // Si Shopify no responde, `codigosNuevos` viene vacío: no se inventan
      // alertas cuando la fuente no está disponible.
      return wsAutoHallazgosCodigos((est && est.alertas && est.alertas.codigosNuevos) || []);
    },
  },
  {
    id: 'costeo_rojo',
    label: 'Platos vendiéndose por encima de su objetivo de costo',
    // Se compara el % de costo REAL (contra el precio que se cobra) con el
    // objetivo que el propio usuario le puso a ese plato — no contra un número
    // inventado acá.
    async hallazgos(){
      const all = loadCosteoAll();
      const nombres = { garden: 'Garden · comida', badass: 'Badass · comida', garden_barra: 'Garden · barra', badass_barra: 'Badass · barra' };
      const out = [];
      for (const set of ['garden', 'badass', 'garden_barra', 'badass_barra']) {
        const doc = all[set];
        if (!doc) continue;
        let platos = [];
        try { platos = resolveCosteo(doc).platos || []; } catch { continue; }
        for (const p of platos) {
          if (p.pctCostoReal == null || !p.precioReal) continue;      // sin precio cargado no hay nada que comparar
          const objetivo = Number(p.margenPct) || 30;
          const exceso = p.pctCostoReal - objetivo;
          if (exceso < WS_AUTO_COSTEO_HOLGURA) continue;
          out.push({
            clave: `costeo:${set}:${p.id}`,
            titulo: `Revisar costeo de ${p.nombre}`,
            prioridad: exceso >= 20 ? 'urgente' : 'alta',
            etiquetas: ['costeo'],
            _peso: exceso,
            descripcion: `${nombres[set] || set} · ${p.categoria || 'Sin categoría'}\n\n`
              + `Cuesta ${p.pctCostoReal}% de lo que se cobra, y el objetivo de este plato es ${objetivo}%: se está pasando por ${Math.round(exceso * 10) / 10} puntos.\n\n`
              + `Costo final $${(p.costoFinal || 0).toLocaleString('es-CL')} · precio de venta $${(p.precioReal || 0).toLocaleString('es-CL')}.\n\n`
              + `Puede ser precio desactualizado de un insumo, una receta cargada de más o un precio de venta que quedó viejo.`,
          });
        }
      }
      // Los peores primero: si hay techo, que entren los que más duelen.
      return out.sort((a, b) => b._peso - a._peso);
    },
  },
  // Falta el tercero del pedido original (proveedor sugiere un punto de venta):
  // el portal de proveedores todavía no tiene esa función, así que no hay dato
  // real que leer. Cuando exista, es agregar un objeto más a esta lista.
];

async function wsAutoEscanear(){
  const resumen = { creadas: 0, porDetector: {}, errores: [] };
  let d = wsLoad();
  const responsable = wsAutoResponsable();
  for (const det of WS_AUTO_DETECTORES) {
    let hallazgos = [];
    try { hallazgos = await det.hallazgos(); }
    catch (e) { resumen.errores.push({ detector: det.id, error: e.message }); resumen.porDetector[det.id] = { creadas: 0, error: e.message }; continue; }
    // Releer: un detector puede tardar (Shopify) y mientras tanto alguien pudo
    // haber tocado el doc. Sin esto le pisaríamos los cambios.
    d = wsLoad();
    const proyectoId = wsAutoProyectoId(d);
    const yaVistas = new Set(d.tareas.filter(t => t.fuente && t.fuente.clave).map(t => t.fuente.clave));
    const abiertas = d.tareas.filter(t => t.auto && t.fuente && t.fuente.detector === det.id && t.estado !== 'listo').length;
    let cupo = Math.max(0, WS_AUTO_MAX_ABIERTAS - abiertas);
    let creadas = 0;
    for (const h of hallazgos) {
      if (cupo <= 0) break;
      if (yaVistas.has(h.clave)) continue;
      const ahora = Date.now();
      d.tareas.push({
        id: wsNewId('tk'), titulo: h.titulo, descripcion: h.descripcion || '',
        proyectoId, asignados: (h.asignados && h.asignados.length) ? h.asignados : (responsable ? [responsable] : []),
        estado: (d.estados[0] || {}).id || 'por_hacer', prioridad: h.prioridad || 'media',
        vence: h.vence || '', etiquetas: h.etiquetas || [], checklist: [], comentarios: [],
        orden: ahora, auto: true, fuente: { detector: det.id, clave: h.clave },
        creadoPor: 'sistema', createdAt: ahora, updatedAt: ahora, completadaAt: null,
      });
      const t = d.tareas[d.tareas.length - 1];
      wsNotificar(d, t.asignados, { tipo: 'auto', de: '', tareaId: t.id, texto: `El sistema detectó algo: “${t.titulo}”` });
      yaVistas.add(h.clave); creadas++; cupo--;
    }
    resumen.porDetector[det.id] = {
      label: det.label, encontrados: hallazgos.length, creadas,
      abiertas: abiertas + creadas,
      // Si hay hallazgos que no entraron, decirlo: un techo silencioso se lee
      // como "no hay nada más".
      omitidos: Math.max(0, hallazgos.filter(h => !yaVistas.has(h.clave)).length),
      topeAlcanzado: cupo <= 0 && hallazgos.length > creadas,
    };
    resumen.creadas += creadas;
    if (creadas) wsSave(d);
  }
  return resumen;
}

app.post('/admin/ws/auto/escanear', requireAdmin, async (req, res) => {
  if (!wsSoloAdmin(req, res)) return;
  try { res.json({ ok: true, ...(await wsAutoEscanear()) }); }
  catch (e) { res.status(500).json({ error: 'No se pudo escanear: ' + e.message }); }
});

// Escaneo periódico. Arranca despegado del boot para no competir con la carga
// inicial, y después cada 6 h. `unref` para que no sostenga el proceso.
setTimeout(() => { wsAutoEscanear().then(r => { if (r.creadas) console.log('[ws-auto] tareas creadas:', r.creadas); }).catch(e => console.warn('[ws-auto]', e.message)); }, 90 * 1000).unref?.();
setInterval(() => { wsAutoEscanear().catch(e => console.warn('[ws-auto]', e.message)); }, 6 * 60 * 60 * 1000).unref?.();

