async function estadoResolve(month, rango){
  const all = estadoLoad(); const per = estadoNormPeriodo(all.periodos[month]);
  const precios = per.preciosTransfer;
  const r = (rango && rango.from && rango.to) ? rango : cdMonthRange(month);
  const sh = await cdShopifyMonth(month, precios, r).catch(e => ({ error: String(e.message || e) }));
  const shOk = !sh.error;
  const sum = (arr) => (arr || []).reduce((a, x) => a + (Number(x.monto) || 0), 0);
  const shCd = shOk ? sh.bucket.cd_kairos_mall.original : 0;
  const shCruz = shOk ? sh.bucket.ventas_cruzada.original : 0;
  const shWeb = shOk ? sh.bucket.retail.cobrado : 0;
  const shWalmart = shOk ? sh.bucket.walmart.original : 0;
  const ratio = (shop, base) => (base ? Math.round((shop / base) * 1000) / 10 : (shop ? 100 : 0));
  // Antofagasta: tabla manual valorizada a precio de transferencia (cerveza).
  const antoTabla = per.antofagasta.map(r => ({ estilo: r.estilo, precioLt: precios.cerveza, despachoLt: precios.despacho, litros: r.litros, valor: Math.round(r.litros * precios.cerveza + precios.despacho * r.litros) }));
  const antoLitros = antoTabla.reduce((a, r) => a + r.litros, 0);
  const antoValor = antoTabla.reduce((a, r) => a + r.valor, 0);
  antoTabla.forEach(r => r.pct = antoLitros ? Math.round((r.litros / antoLitros) * 1000) / 10 : 0);
  const mkTabla = (t) => (t && t.porEstilo || []).map(e => ({ estilo: e.estilo, tipo: e.tipo, precioLt: precios[e.tipo] || precios.cerveza, despachoLt: precios.despacho, litros: e.litros, valor: Math.round(e.litros * (precios[e.tipo] || precios.cerveza) + precios.despacho * e.litros), pct: t.litros ? Math.round((e.litros / t.litros) * 1000) / 10 : 0 }));
  // Seed de transferencias históricas a Garden Antofagasta (pre-Shopify): se suma
  // al garden como si fueran pedidos de Shopify (litros + valor revaluado).
  // Dedupe: si Shopify YA devolvió ese mismo pedido (por número), el seed no se
  // suma — si no, el mismo despacho contaría dos veces. Importa ahora que
  // Antofagasta tiene bucket propio: el pedido podía entrar por Shopify a
  // 'antofagasta' y por el seed a 'garden' sin que se notara.
  const pedidosShopify = new Set(shOk
    ? Object.values(sh.transfers).flatMap(t => (t.pedidos || []).map(p => String(p.pedido || '').trim()).filter(Boolean))
    : []);
  const gardenSeed = (CD_GARDEN_SEED[month] || []).filter(p => !pedidosShopify.has(String(p.pedido || '').trim()));
  const seedLitros = gardenSeed.reduce((a, p) => a + (p.lineas || []).reduce((s, l) => s + (Number(l.litros) || 0), 0), 0);
  const seedValor = gardenSeed.reduce((a, p) => a + (p.lineas || []).reduce((s, l) => s + (Number(l.litros) || 0) * ((precios[l.tipo] || precios.cerveza) + precios.despacho), 0), 0);
  const gardenValor = (shOk ? sh.transfers.garden.valor : 0) + Math.round(seedValor);
  const badassValor = shOk ? sh.transfers.badass.valor : 0;
  const garden = { litros: cdR3((shOk ? sh.transfers.garden.litros : 0) + seedLitros), valor: gardenValor, tabla: shOk ? mkTabla(sh.transfers.garden) : [], pedidos: [...(shOk ? sh.transfers.garden.pedidos : []), ...gardenSeed] };
  const badass = { litros: shOk ? sh.transfers.badass.litros : 0, valor: badassValor, tabla: shOk ? mkTabla(sh.transfers.badass) : [], pedidos: shOk ? sh.transfers.badass.pedidos : [] };
  // Antofagasta: los pedidos que Shopify marca con PEDIDOSANTOFAGASTA, más las
  // líneas cargadas a mano en el período (la tabla manual que ya existía y hasta
  // ahora no sumaba a ningún lado).
  const antoShopifyValor = shOk ? sh.transfers.antofagasta.valor : 0;
  const antofagasta = {
    litros: cdR3((shOk ? sh.transfers.antofagasta.litros : 0) + antoLitros),
    valor: antoShopifyValor + antoValor,
    tabla: [...(shOk ? mkTabla(sh.transfers.antofagasta) : []), ...antoTabla],
    pedidos: shOk ? sh.transfers.antofagasta.pedidos : [],
    manual: per.antofagasta,
  };
  // 100% automático de Shopify: sin líneas manuales.
  const cdNeto = shCd;
  const cruzTotal = shCruz;
  const hospitalityTotal = gardenValor + badassValor + antofagasta.valor;
  // ③ Retail = Walmart, 100% automático de Shopify (código PEDIDOSWALMART) +
  // pedidos históricos puntuales inyectados como si vinieran de Shopify.
  const walmartSeed = CD_WALMART_SEED[month] || [];
  const walmartPedidos = [...(shOk ? sh.bucket.walmart.pedidos : []), ...walmartSeed];
  const retail = shWalmart + walmartSeed.reduce((a, p) => a + (Number(p.original) || 0), 0);
  // Venta por día = total real de Shopify por día + seeds históricos puntuales (que
  // también traen su fecha real). Misma base de valorización que totalIngresos.
  const porDia = {};
  const addDia = (fecha, monto) => { if (!fecha || !monto) return; porDia[fecha] = (porDia[fecha] || 0) + Math.round(monto); };
  if (shOk) Object.entries(sh.porDia).forEach(([f, v]) => addDia(f, v));
  gardenSeed.forEach(p => addDia(p.fecha, (p.lineas || []).reduce((s, l) => s + (Number(l.litros) || 0) * ((precios[l.tipo] || precios.cerveza) + precios.despacho), 0)));
  walmartSeed.forEach(p => addDia(p.fecha, Number(p.original) || 0));
  // Walmart por marca (vendor de Shopify): resumen + filtro, igual que Venta Online.
  const wmProvKeys = [...CD_WEB_PROVEEDORES, 'Otros'];
  const walmartPorProv = {}; for (const k of wmProvKeys) walmartPorProv[k] = { total: 0, n: 0, pedidos: [] };
  for (const ped of walmartPedidos) {
    const monto = Number(ped.original) || 0;
    const provs = (ped.porProveedor && ped.porProveedor.length) ? ped.porProveedor : [{ proveedor: ped.proveedor || 'Otros', monto }];
    const base = provs.reduce((a, x) => a + (x.monto || 0), 0) || 1;
    for (const pp of provs) {
      const key = walmartPorProv[pp.proveedor] ? pp.proveedor : 'Otros';
      const alloc = Math.round(monto * ((pp.monto || 0) / base));
      walmartPorProv[key].total += alloc; walmartPorProv[key].n++;
      walmartPorProv[key].pedidos.push({ ...ped, montoProveedor: alloc });
    }
  }
  // HORECA por canal de venta: Grupo Mil Sabores vs Otros. Cada pedido trae su
  // punto de venta (marca/razón/sector) para filtrar.
  const horecaPedidos = shOk ? [...sh.bucket.cd_kairos_mall.pedidos, ...sh.bucket.ventas_cruzada.pedidos] : [];
  const chanTotal = (g) => horecaPedidos.filter(p => p.grupo === g).reduce((a, p) => a + (p.monto || 0), 0);
  const horeca = { total: cdNeto + cruzTotal, milSabores: chanTotal('mil_sabores'), otros: chanTotal('otros'), pedidos: horecaPedidos };
  // VENTA WEB por proveedor (vendor de Shopify): 4 secciones + Otros. El monto de
  // cada sección se prorratea del cobrado real del pedido según la participación
  // de cada proveedor en las líneas, así las secciones suman ≈ el total web.
  const webPedidos = shOk ? sh.bucket.retail.pedidos : [];
  const provKeys = [...CD_WEB_PROVEEDORES, 'Otros'];
  const webPorProv = {}; for (const k of provKeys) webPorProv[k] = { total: 0, n: 0, pedidos: [] };
  for (const ped of webPedidos) {
    const provs = (ped.porProveedor && ped.porProveedor.length) ? ped.porProveedor : [{ proveedor: 'Otros', monto: ped.cobrado }];
    const base = provs.reduce((a, x) => a + (x.monto || 0), 0) || 1;
    for (const pp of provs) {
      const key = webPorProv[pp.proveedor] ? pp.proveedor : 'Otros';
      const alloc = Math.round(ped.cobrado * ((pp.monto || 0) / base));
      webPorProv[key].total += alloc; webPorProv[key].n++;
      webPorProv[key].pedidos.push({ ...ped, montoProveedor: alloc });
    }
  }
  const ingresos = {
    cd_kairos: { shopify: shCd, neto: cdNeto, pedidos: shOk ? sh.bucket.cd_kairos_mall.pedidos : [] },
    ventas_cruzada: { shopify: shCruz, total: cruzTotal, pedidos: shOk ? sh.bucket.ventas_cruzada.pedidos : [] },
    horeca,
    hospitality: { garden, badass, antofagasta, total: hospitalityTotal },
    ventas_web: { cobrado: shWeb, n: shOk ? sh.bucket.retail.n : 0, pedidos: webPedidos, porProveedor: webPorProv, proveedores: provKeys, detalleEntrega: !!(cdOrdersTier && cdOrdersTier.key !== 'base'), origenDespacho: !!(cdOrdersTier && (cdOrdersTier.key === 'full' || cdOrdersTier.key === 'loc')) },
    retail,
    walmart: { total: retail, n: walmartPedidos.length, pedidos: walmartPedidos, porProveedor: walmartPorProv, proveedores: wmProvKeys },
  };
  // Carga manual histórica por Centro de Distribución (2025+, ver
  // estadoHistCdLoad): reemplaza HORECA/Retail/Hospitality del mes si hay una
  // entrada auditada para este CD. Venta Online NUNCA se toca acá — sigue
  // siempre en vivo desde Shopify (shWeb). 2026 y el resto de los meses/CD sin
  // entrada explícita siguen exactamente como antes.
  //
  // Estos totales se cargaron a mano como AGREGADO MENSUAL, sin detalle por día:
  // el número vale por el mes entero, no está fechado en un día puntual. Por eso
  // se aplican siempre que el rango elegido REPRESENTE ese mes — sea el mes
  // completo, un sub-rango dentro del mes (ej. 1–30 en un mes de 31 días) o un
  // rango que lo abarque por completo. Así el usuario no tiene que acertar el
  // último día exacto para que el mes aparezca. (Un rango que cruza el borde de
  // dos meses sin contener a este entero no lo aplica: ahí no hay forma de
  // trocear un total sin detalle diario.)
  let origenHistorico = null, historicoDetalle = null;
  const histMes = (estadoHistCdLoad().cd[CD_DEFAULT] || {})[month];
  const monthR = cdMonthRange(month);
  const rangoRepresentaElMes =
    (r.from >= monthR.from && r.to <= monthR.to) ||   // sub-rango dentro del mes (incluye el mes exacto)
    (r.from <= monthR.from && r.to >= monthR.to);     // rango que abarca el mes entero
  if (histMes && rangoRepresentaElMes) {
    ingresos.horeca = { total: histMes.horeca, milSabores: 0, otros: histMes.horeca, pedidos: [] };
    ingresos.hospitality = {
      garden: { litros: 0, valor: histMes.hospitalidadDetalle.vespucio, tabla: [], pedidos: [] },
      badass: { litros: 0, valor: histMes.hospitalidadDetalle.badass, tabla: [], pedidos: [] },
      // El histórico ya traía Antofagasta separado; antes se sumaba a Vespucio
      // porque no había dónde ponerlo.
      antofagasta: { litros: 0, valor: histMes.hospitalidadDetalle.antofagasta, tabla: [], pedidos: [] },
      total: histMes.hospitalidadTotal,
    };
    ingresos.retail = histMes.retail;
    ingresos.walmart = { total: histMes.retail, n: 0, pedidos: [], porProveedor: {}, proveedores: wmProvKeys };
    origenHistorico = histMes.origen || 'manual_historico_2025';
    historicoDetalle = histMes.hospitalidadDetalle;
  }
  const totalIngresos = ingresos.horeca.total + ingresos.hospitality.total + shWeb + ingresos.retail;
  // ¿El mes cae fuera de la ventana de 60 días de Shopify? Con solo read_orders,
  // los pedidos > 60 días vuelven vacíos (sin error) → total 0 aunque sí hubo ventas.
  const finMes = new Date((cdMonthRange(month).to) + 'T23:59:59Z').getTime();
  const fueraVentana60 = (Date.now() - finMes) > 60 * 86400000;
  const shopifyLimitado = shOk && totalIngresos === 0 && fueraVentana60;
  return {
    month, precios, periodo: per, ingresos, totalIngresos, porDia,
    rango: r, mesCompleto: (r.from === cdMonthRange(month).from && r.to === cdMonthRange(month).to),
    shopifyOk: shOk, shopifyError: sh.error || null, shopifyLimitado, fueraVentana60,
    origenHistorico, historicoDetalle,
    alertas: { codigosNuevos: shOk ? sh.codigosNuevos : [], sinMapear: shOk ? sh.sinMapear : [], sinCodigo: shOk ? sh.sinCodigo : 0 },
    excelRef: CD_EXCEL_REF[month] || null,
  };
}
// Lee un rango de fechas de los query params (from/to en YYYY-MM-DD), o null.
function estadoRangeFromReq(req){
  const d = /^\d{4}-\d{2}-\d{2}$/;
  const from = String(req.query.from || ''), to = String(req.query.to || '');
  return (d.test(from) && d.test(to) && from <= to) ? { from, to } : null;
}
app.get('/admin/estado/periodos', requireAdmin, (req, res) => { res.json({ periodos: Object.keys(estadoLoad().periodos).sort().reverse() }); });
app.get('/admin/estado', requireAdmin, async (req, res) => {
  const month = /^\d{4}-\d{2}$/.test(String(req.query.month)) ? String(req.query.month) : null;
  if (!month) return res.status(400).json({ error: 'Falta el mes (YYYY-MM).' });
  try { res.json(await estadoResolve(month, estadoRangeFromReq(req))); } catch (e) { res.status(500).json({ error: 'Error: ' + String(e.message || e).slice(0, 300) }); }
});
// ── Reporte: Venta Online (web) mes a mes ──────────────────────────────────
// Recorre cada mes desde `desde` (YYYY-MM, default 2025-01) hasta el mes actual
// y toma la MISMA "Venta Online" que la tarjeta de Ingreso por Venta
// (estadoResolve → ingresos.ventas_web.cobrado). Venta Online ya excluye
// mayoristas y HORECA (esos van a otros canales). Página HTML lista para leer.
function reporteMesesDesde(desde){
  const now = new Date(); const cur = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
  const out = []; let [y, m] = desde.split('-').map(Number);
  for (let i = 0; i < 120; i++) { const mm = y + '-' + String(m).padStart(2, '0'); out.push(mm); if (mm === cur) break; m++; if (m > 12) { m = 1; y++; } }
  return out;
}
app.get('/admin/reportes/ventas-online', requireAdmin, async (req, res) => {
  const desde = /^\d{4}-\d{2}$/.test(String(req.query.desde)) ? String(req.query.desde) : '2025-01';
  const meses = reporteMesesDesde(desde);
  const filaDe = async (mm) => {
    try { const e = await estadoResolve(mm); const vw = (e.ingresos && e.ingresos.ventas_web) || {}; return { mes: mm, cobrado: Math.round(Number(vw.cobrado) || 0), n: Number(vw.n) || 0, ok: !!e.shopifyOk }; }
    catch (err) { return { mes: mm, cobrado: 0, n: 0, ok: false, error: String(err.message || err).slice(0, 100) }; }
  };
  // Concurrencia acotada (4 meses a la vez) para no tardar tanto ni saturar Shopify.
  const filas = new Array(meses.length); let idx = 0;
  await Promise.all(Array.from({ length: 4 }, async () => { let i; while ((i = idx++) < meses.length) filas[i] = await filaDe(meses[i]); }));
  if (String(req.query.format) === 'json') return res.json({ desde, filas });
  const clp = (n) => '$' + (Math.round(Number(n) || 0)).toLocaleString('es-CL');
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const mLbl = (mm) => { const [y, mo] = mm.split('-'); const N = ['', 'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre']; return N[+mo] + ' ' + y; };
  const totCob = filas.reduce((a, f) => a + f.cobrado, 0), totN = filas.reduce((a, f) => a + f.n, 0);
  const porAnio = {}; for (const f of filas) { const y = f.mes.slice(0, 4); porAnio[y] = (porAnio[y] || 0) + f.cobrado; }
  const rows = filas.map(f => `<tr><td>${mLbl(f.mes)}</td><td class="n">${f.n}</td><td class="n">${clp(f.cobrado)}</td><td class="s">${f.error ? ('⚠ ' + esc(f.error)) : (f.ok ? '✓' : '—')}</td></tr>`).join('');
  const anioRows = Object.entries(porAnio).map(([y, v]) => `<tr><td><b>Total ${y}</b></td><td></td><td class="n"><b>${clp(v)}</b></td><td></td></tr>`).join('');
  res.set('Content-Type', 'text/html; charset=utf-8').send(`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Venta Online mes a mes</title>
<style>body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;color:#1c2230}h1{font-size:1.4rem}.sub{color:#667;margin:.2rem 0 1.2rem}table{border-collapse:collapse;width:100%;font-size:.95rem}th,td{padding:.5rem .7rem;border-bottom:1px solid #eceef2;text-align:left}th{background:#f6f7f9;font-size:.8rem;color:#556}td.n{text-align:right;font-variant-numeric:tabular-nums}td.s{text-align:center;color:#8a92a0}tfoot td{font-weight:800;background:#fff7e6;border-top:2px solid #e9c46a}.note{color:#667;font-size:.8rem;margin-top:1rem;line-height:1.5}.yr td{background:#f3f6ff}</style></head><body>
<h1>🌐 Venta Online · mes a mes</h1>
<div class="sub">Desde ${mLbl(desde)} · misma "Venta Online" que la sección Ingreso por Venta (web B2C, ya <b>sin mayoristas</b> ni HORECA).</div>
<table><thead><tr><th>Mes</th><th style="text-align:right">Pedidos web</th><th style="text-align:right">Venta Online</th><th style="text-align:center">Shopify</th></tr></thead>
<tbody>${rows}</tbody>
<tfoot><tr><td>TOTAL</td><td class="n">${totN}</td><td class="n">${clp(totCob)}</td><td></td></tr>${anioRows ? ('<tr class="yr"><td colspan="4" style="padding-top:.6rem"></td></tr>' + anioRows) : ''}</tfoot></table>
<div class="note">"Venta Online" = pedidos de la página que no son mayoristas, HORECA, Walmart ni transferencias a los restoranes. Es el total cobrado del pedido (con descuentos aplicados). Un "—" o ⚠ en Shopify indica que ese mes no se pudo traer (revisá permisos/ventana de Shopify). Para verlo en JSON agregá <code>?format=json</code> a la URL.</div>
</body></html>`);
});
