    const durH = (ev.inicio && ev.fin) ? (new Date(ev.fin) - new Date(ev.inicio)) / 3600000 : 0;
    const buenos = prodNum(ev.litrosBuenos);
    if (durH <= 0 || buenos <= 0) continue;
