    const scripts = [...html.matchAll(/<script\b[^>]*src=["']([^"']+)["']/gi)].map(m => m[1]).slice(0, 8);
    const esSPA = (/<div\s+id=["'](app|root|__nuxt|__next)["']/i.test(html) || (!/<form/i.test(html) && scripts.length > 0));
