let erpSyncRunning = false;
// Ejecuta una sincronización completa (login + /Receta/GetAll + /Lote/GetAll + merge
// que nunca pisa datos manuales). Reutilizada por el botón y por el auto-sync.
async function erpRunSync(origen){
  if (erpSyncRunning) return { ok: false, estado: 'Ya hay una sincronización en curso.', ultimaSync: null };
  erpSyncRunning = true;
  const d = prodLoad(); const cfg = d.config; const cr = erpCreds(cfg);
  let msg = '';
  try {
    if (!cr.usuario || !cr.clave) throw new Error('Falta usuario o clave del ERP (Config).');
    const login = await erpLogin(cfg);
    if (!login.ok) throw new Error(login.error + (login.stage ? ' [' + login.stage + ']' : ''));
    // Recetas (API JSON: POST /Receta/GetAll).
    const recRes = await erpApiGetAll(cr.base, '/Receta/GetAll', login.jar, '/Receta');
    const recetas = erpRecetasFromJson(recRes.data);
    if (recetas.length) d.recetas = prodMergeRecetas(d.recetas || [], recetas);
    // Lotes (API JSON: POST /Lote/GetAll).
    const loteRes = await erpApiGetAll(cr.base, '/Lote/GetAll', login.jar, '/Lote');
    const lotes = erpLotesFromJson(loteRes.data);
    if (!recetas.length && !lotes.length) throw new Error('Login OK pero la API no devolvió datos (Receta:' + recRes.status + ' /Lote:' + loteRes.status + ').');
    let nuevos = 0, act = 0;
    for (const rl of lotes) {
      if (!rl.numero && !rl.erpId) continue;
      if (rl.tanque && !d.tanques.find(t => t.id === rl.tanque)) d.tanques.push({ id: rl.tanque, capacidadL: /^F([1-9]|1[0-4])$/.test(rl.tanque) ? prodCapTanque(rl.tanque) : (rl.capacidad || 1000), estado: 'vacio', loteActualId: null, sede: 'vespucio', sucio: false });
      const ex = d.lotes.find(x => x.erpId === rl.erpId || x.codigo === rl.numero);
      const estadoZ = erpEstadoZorbo(rl.etapa, rl.estado);
      if (!ex) {
        d.lotes.push({ id: prodNewId('lote'), erpId: rl.erpId, origen: 'erp', codigo: rl.numero, producto: rl.descripcion, estilo: rl.descripcion, familia: '', color: '',
          tanqueId: rl.tanque || '', nBatches: rl.cantCocciones || 1, volumenEsperadoL: rl.litrosDisponibles, volumenRealL: 0, idReceta: rl.idReceta,
          fechaCoccion: rl.fechaCoccion, fechaFermInicio: (estadoZ !== 'coccion' ? rl.fechaCoccion : null), fechaMadInicio: null, fechaEnvasado: null,
          estado: estadoZ, etapaErp: rl.etapa, estadoErp: rl.estado,
          etapas: PROD_ETAPAS.map(nombre => ({ nombre, inicio: null, fin: null, editadoManual: false })), envasados: [] });
        nuevos++;
      } else {
        ex.erpId = rl.erpId; ex.idReceta = rl.idReceta; ex.etapaErp = rl.etapa; ex.estadoErp = rl.estado;
        if (rl.descripcion) { ex.producto = ex.producto || rl.descripcion; ex.estilo = ex.estilo || rl.descripcion; }
        if (rl.fechaCoccion) ex.fechaCoccion = rl.fechaCoccion;
        if (rl.tanque) ex.tanqueId = rl.tanque;
        if (rl.litrosDisponibles) ex.volumenEsperadoL = ex.volumenEsperadoL || rl.litrosDisponibles;
        const orden = { coccion: 0, fermentacion: 1, maduracion: 2, listo: 3, envasado: 4 };
        if ((orden[estadoZ] || 0) > (orden[ex.estado] || 0)) { ex.estado = estadoZ; if (estadoZ !== 'coccion' && !ex.fechaFermInicio) ex.fechaFermInicio = rl.fechaCoccion; }
        act++;
      }
    }
    prodSyncTanques(d);
    msg = 'OK · ' + recetas.length + ' recetas · lotes: ' + nuevos + ' nuevos, ' + act + ' actualizados' + (origen === 'auto' ? ' (auto)' : '');
  } catch (e) { msg = 'Error: ' + String(e.message || e).slice(0, 180); }
  cfg.erpLastSync = new Date().toISOString(); cfg.erpLastStatus = msg; prodSave(d);
  erpSyncRunning = false;
  return { ok: !/^Error|^Falta/.test(msg), ultimaSync: cfg.erpLastSync, estado: msg };
}
// Auto-sync en segundo plano: cada minuto revisa si toca sincronizar según
// erpAutoSyncMin (0 = desactivado). Corre en Railway (alcanza el ERP).
setInterval(async () => {
  try {
    const cfg = prodLoad().config; const cr = erpCreds(cfg);
    const cada = prodNum(cfg.erpAutoSyncMin);
    if (!cada || cada <= 0 || !cr.usuario || !cr.clave || erpSyncRunning) return;
    const last = cfg.erpLastSync ? new Date(cfg.erpLastSync).getTime() : 0;
    if (Date.now() - last >= cada * 60000) await erpRunSync('auto');
  } catch (e) { /* no romper el loop */ }
}, 60000).unref?.();
app.post('/admin/produccion/erp/sync', requireAdmin, async (req, res) => {
  const r = await erpRunSync('manual');
  res.json(r);
});
// Números del stock de GC. Barriles usan formato US (punto decimal: "480.00").
// Latas usan formato europeo (coma decimal, punto de miles: "1.711,787" = 1711.787).
const erpNumUS = (s) => { const n = parseFloat(String(s || '').replace(/[^\d.\-]/g, '')); return Number.isFinite(n) ? n : 0; };
const erpNumEU = (s) => { const n = parseFloat(String(s || '').replace(/[^\d.,\-]/g, '').replace(/\./g, '').replace(',', '.')); return Number.isFinite(n) ? n : 0; };
// Celdas <td> de una fila (texto limpio, sin tags).
const erpTds = (rowInner) => [...String(rowInner || '').matchAll(/<td\b[^>]*>([\s\S]*?)<\/td>/gi)].map(m => erpTxt(m[1]));
// Extrae el <tbody>/contenido de la 1ª tabla cuyo HTML matchea `firma`
// (RegExp o función predicado sobre el HTML interno de la tabla).
function erpTablaPorFirma(html, firma){
  const test = (typeof firma === 'function') ? firma : (h => firma.test(h));
  for (const m of String(html || '').matchAll(/<table\b[^>]*>([\s\S]*?)<\/table>/gi)) if (test(m[1])) return m[1];
  return '';
}
const erpB = (s) => ({ barriles: Math.round(erpNumUS(s && s.b)), litros: erpNumUS(s && s.l) });
// Stock desde Gestión Cervecera: la página /Producto/Stock viene renderizada en el
// servidor. Reproducimos la MISMA jerarquía que muestra GC:
//  · Barriles por producto → tamaño de barril → barril individual (código/lote/ubicación)
//  · Latas/envasado por producto → tipo de caja → lote (fecha de vencimiento)
//  · Barriles por depósito → producto
// Cada nivel trae {enStock, pedidos, disponible} con Cant. Barriles/Cajas + Litros.
// Barriles = formato US ("480.00"); latas = europeo ("1.711,787" = 1711.787).
async function erpStock(){
  const cfg = prodLoad().config; const { base } = erpCreds(cfg);
  const login = await erpLogin(cfg);
  if (!login.ok) return { ok: false, error: login.error + (login.stage ? ' [' + login.stage + ']' : '') };
  let html = '';
  try { const r = await erpGet(base + '/Producto/Stock', login.jar, base); html = await r.text(); }
  catch (e) { return { ok: false, error: 'No pude leer /Producto/Stock: ' + String(e.message).slice(0, 120) }; }
  if (/id=["']frmLogin["']|\/Home\/Login/i.test(html)) return { ok: false, error: 'La sesión del ERP no tomó al leer el stock.' };

  // ── Barriles por producto (tabla con filas data-idp / data-idps / data-idpss) ──
  const barriles = []; {
    const tbl = erpTablaPorFirma(html, /\bdata-idp=["']\d+["']/);
    let prod = null, size = null;
    for (const m of tbl.matchAll(/<tr\b([^>]*)>([\s\S]*?)<\/tr>/gi)) {
      const open = m[1] || '', td = erpTds(m[2]);
      const trio = (b, l) => ({ barriles: Math.round(erpNumUS(td[b])), litros: erpNumUS(td[l]) });
      if (/\bdata-idpss=/.test(open)) { // barril individual
        if (size) size.detalle.push({ codigo: (td[4] || '').replace(/^#/, ''), lote: td[5] || '', fecha: td[6] || '', litros: erpNumUS(td[7]), ubicacion: td[8] || '' });
      } else if (/\bdata-idps=/.test(open)) { // tamaño de barril
        size = { tamano: td[2] || '', enStock: trio(3, 7), pedidos: trio(9, 10), disponible: trio(11, 12), detalle: [] };
        if (prod) prod.tamanos.push(size);
      } else if (/\bdata-idp=/.test(open)) { // producto
        prod = { producto: td[1] || '', enStock: trio(3, 7), pedidos: trio(9, 10), disponible: trio(11, 12), tamanos: [] };
        if (prod.producto) barriles.push(prod); size = null;
      }
    }
  }
  // ── Latas / envasado por producto (data-idep="envs…" / data-ideps / data-idepss) ──
  const latas = []; {
    const tbl = erpTablaPorFirma(html, /\bdata-idep=["']envs\b/i);
    let prod = null, caja = null;
    for (const m of tbl.matchAll(/<tr\b([^>]*)>([\s\S]*?)<\/tr>/gi)) {
      const open = m[1] || '', td = erpTds(m[2]);
      const trio = (c, q, l) => ({ cajas: Math.round(erpNumEU(td[c])), cantidad: Math.round(erpNumEU(td[q])), litros: erpNumEU(td[l]) });
      if (/\bdata-idepss=/.test(open)) { // lote
        if (caja) caja.detalle.push({ lote: (td[4] || '').replace(/^#/, ''), fechaVenc: td[5] || '', cantidad: Math.round(erpNumEU(td[7])), litros: erpNumEU(td[8]) });
      } else if (/\bdata-ideps=/.test(open)) { // tipo de caja
        caja = { tipo: td[3] || '', enStock: trio(6, 7, 8), pedidos: trio(9, 10, 11), disponible: trio(12, 13, 14), detalle: [] };
        if (prod) prod.cajas.push(caja);
      } else if (/\bdata-idep=/.test(open)) { // producto + envase
        prod = { producto: td[1] || '', envase: td[2] || '', enStock: trio(6, 7, 8), pedidos: trio(9, 10, 11), disponible: trio(12, 13, 14), cajas: [] };
        if (prod.producto) latas.push(prod); caja = null;
      }
    }
  }
  // ── Barriles por depósito → producto → tamaño → barril (drill-down completo, como GC) ──
  // Filas: depósito=data-idep · producto=data-ideppr · tamaño=data-idepprs · barril=data-idepprss.
  // Columnas: Depósito[1] Cant.Barriles[2] Producto[3] Barriles[4] Código[5] Lote[6] Litros[7].
  const depositos = []; {
    const tbl = erpTablaPorFirma(html, h => /\bdata-idep=["']dep\b/i.test(h) && /Barriles/i.test(h) && !/Envase/i.test(h));
    let dep = null, prod = null, size = null;
    for (const m of tbl.matchAll(/<tr\b([^>]*)>([\s\S]*?)<\/tr>/gi)) {
      const open = m[1] || '', td = erpTds(m[2]);
      if (/\bdata-idepprss=/.test(open)) { // barril individual
        if (size) size.detalle.push({ codigo: (td[5] || '').replace(/^#/, ''), lote: td[6] || '', litros: erpNumUS(td[7]) });
      } else if (/\bdata-idepprs=/.test(open)) { // tamaño
        size = { tamano: td[4] || '', detalle: [] }; if (prod) prod.tamanos.push(size);
      } else if (/\bdata-ideppr=/.test(open)) { // producto
        prod = { producto: td[3] || '', barriles: Math.round(erpNumUS(td[4])), tamanos: [] }; if (dep) dep.productos.push(prod); size = null;
      } else if (/\bdata-idep=/.test(open)) { // depósito
        dep = { deposito: td[1] || '', barriles: Math.round(erpNumUS(td[2])), productos: [] }; if (dep.deposito) depositos.push(dep); prod = null; size = null;
      }
    }
  }
  // ── Latas/envases por depósito → envase/producto → caja → lote (drill-down completo). ──
  // Columnas (confirmadas por muestra): Depósito[1] Envase[2] Caja[3] Cant.Caja[4] Lote[5]
  // Cantidad[6] Litros[7] FechaVenc[8]. Se clasifica por en qué columna cae el texto:
  // depósito=[1] · envase/producto=[2] · caja=[3] · lote=[5].
  const depositosLatas = []; {
    const tbl = erpTablaPorFirma(html, h => /Dep[a-zñ&#;xX0-9]*sito/i.test(h) && /Envase/i.test(h) && /Fecha\s*Venc/i.test(h));
    let dep = null, env = null, caja = null;
    for (const m of tbl.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)) {
      if (!/<td\b/i.test(m[1])) continue;
      const td = erpTds(m[1]);
      const cant = Math.round(erpNumEU(td[6])), litros = erpNumEU(td[7]);
      const dName = (td[1] || '').trim(), eName = (td[2] || '').trim(), cName = (td[3] || '').trim(), lName = (td[5] || '').trim();
      if (dName) { if (/^total$/i.test(dName)) continue; dep = { deposito: dName, cantidad: cant, litros, items: [] }; depositosLatas.push(dep); env = null; caja = null; }
      else if (eName && dep) { env = { producto: eName, cantidad: cant, litros, cajas: [] }; dep.items.push(env); caja = null; }
      else if (cName && env) { caja = { caja: cName, cantidad: cant, litros, lotes: [] }; env.cajas.push(caja); }
      else if (lName && caja) { caja.lotes.push({ lote: lName.replace(/^#/, ''), fechaVenc: td[8] || '', cantidad: cant, litros }); }
    }
  }
  const sum = (arr, f) => arr.reduce((a, x) => a + (f(x) || 0), 0);
  return { ok: true, barriles, latas, depositos, depositosLatas,
    totales: {
      // En Stock (stock físico) vs Disponible (en stock − reservado por pedidos).
      barrilesStockUnid: sum(barriles, b => b.enStock.barriles), barrilesStockLitros: sum(barriles, b => b.enStock.litros),
      barrilesUnid: sum(barriles, b => b.disponible.barriles), barrilesLitros: sum(barriles, b => b.disponible.litros),
      latasStockUnid: sum(latas, l => l.enStock.cantidad), latasStockLitros: sum(latas, l => l.enStock.litros),
      latasUnid: sum(latas, l => l.disponible.cantidad), latasLitros: sum(latas, l => l.disponible.litros),
      depBarriles: sum(depositos, d => d.barriles),
      depLatasCantidad: sum(depositosLatas, d => d.cantidad), depLatasLitros: sum(depositosLatas, d => d.litros),
    }, generadoEn: new Date().toISOString() };
}
app.get('/admin/produccion/erp/stock', requireAdmin, async (_req, res) => {
  try { res.json(await erpStock()); } catch (e) { res.status(500).json({ ok: false, error: String(e.message || e).slice(0, 160) }); }
});

// ─────────────────────────────────────────────────────────────────────────────
// Pyxis / BiPyxis (ERP gastronómico de Grupo Mil Sabores) — integración
// Trae la data de nuestros compradores/clientes HORECA. Mismo patrón que Gestión
// Cervecera: login server-side desde Railway (que sí alcanza el ERP) + API JSON +
// credenciales por env. Diferencia: BiPyxis es una SPA moderna (login Email+Password),
// así que el login es JSON/token (no el cookie+MD5 de ASP.NET). El contrato exacto
// (endpoint de login, dónde viaja el token, endpoints de datos) se DESCUBRE con el
// diagnóstico — corre en Railway y reporta qué responde el ERP real. No se inventa nada.
//
// Credenciales (Railway env, NUNCA en el repo):
//   PYXIS_EMAIL, PYXIS_PASSWORD, PYXIS_API_BASE (default el dominio de producción)
// Opcionales (se setean una vez que el diagnóstico revela el contrato):
//   PYXIS_LOGIN_PATH (fuerza el endpoint de login), PYXIS_AUTOSYNC_MIN
// ─────────────────────────────────────────────────────────────────────────────
function pyxisCreds(){
  // web = frontend Angular (login page + bundles). api = backend REST (subdominio
  // api-pyxis + /api, descubierto en el bundle). Ambos overridables por env.
  const web = String(process.env.PYXIS_API_BASE || process.env.PYXIS_WEB_BASE || 'https://pyxis.grupomilsabores.cl').replace(/\/$/, '');
  let api = String(process.env.PYXIS_API_URL || '').replace(/\/$/, '');
  if (!api) api = web.replace(/^https?:\/\/(www\.)?/i, 'https://api-') + '/api';
  return {
    email: process.env.PYXIS_EMAIL || '',
    password: process.env.PYXIS_PASSWORD || '',
    web, api,
    loginPath: (process.env.PYXIS_LOGIN_PATH || '/auth/login').trim(),
  };
}
function pyxisCredsSafe(){ const c = pyxisCreds(); return { emailSet: !!c.email, passwordSet: !!c.password, web: c.web, api: c.api, loginPath: c.loginPath }; }
async function pyxisFetch(url, opts, jar, token){
  const headers = { 'User-Agent': ERP_UA, 'Accept': 'application/json, text/plain, */*', ...(opts.headers || {}) };
  const ck = erpCookieHeader(jar); if (ck) headers['Cookie'] = ck;
  if (token) headers['Authorization'] = 'Bearer ' + token;
  const r = await fetch(url, { ...opts, headers, redirect: 'manual' });
  erpSetCookies(jar, r);
  return r;
}
// Busca un token (JWT / sesión) en una respuesta JSON, probando los nombres más comunes
// y un nivel de anidación (data.token, result.access_token, etc.).
function pyxisPickToken(obj){
  if (!obj || typeof obj !== 'object') return null;
  const direct = ['token', 'access_token', 'accessToken', 'jwt', 'id_token', 'idToken', 'apiToken', 'api_token', 'sessionToken', 'authToken', 'bearer'];
  for (const k of direct) if (typeof obj[k] === 'string' && obj[k].length > 10) return obj[k];
  for (const wrap of ['body', 'data', 'result', 'user', 'payload', 'session', 'auth', 'response']) {
    const w = obj[wrap]; if (w && typeof w === 'object') { const t = pyxisPickToken(w); if (t) return t; }
  }
  return null;
}
// Endpoints de login candidatos (relativos al host de API). El real es /auth/login
// (descubierto en el bundle); el resto queda de fallback por si cambia.
const PYXIS_LOGIN_CANDIDATES = ['/auth/login', '/login', '/auth/signin', '/authenticate', '/users/login', '/user/login', '/session'];
// Un intento de login: POST JSON al host de API con varios alias de campo
// (email/usuario/correo/username, password/clave). No exponemos la clave; sí el body
// de respuesta (que no la trae). Origin/Referer apuntan al frontend (web).
async function pyxisLoginTry(api, web, path, email, password, jar){
  const url = api + path;
  const body = JSON.stringify({ email, password, usuario: email, correo: email, username: email, clave: password });
  let r, txt = '';
  try {
    r = await pyxisFetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest', 'Origin': web, 'Referer': web + '/login' }, body }, jar);
    txt = await r.text();
  } catch (e) { return { path, ok: false, status: 0, error: String(e.message).slice(0, 90) }; }
  let json = null; try { json = JSON.parse(txt); } catch {}
  const token = json ? pyxisPickToken(json) : null;
  const setCookie = (r.headers.getSetCookie && r.headers.getSetCookie().map(c => c.split(';')[0].split('=')[0])) || [];
  const gotSession = setCookie.some(n => /sess|token|auth|jwt|sid|connect|xsrf|laravel/i.test(n));
  const ok = r.status >= 200 && r.status < 300 && (!!token || gotSession);
  return { path, ok, status: r.status, hasToken: !!token, token, setCookie, isJson: !!json, snippet: txt.replace(/\s+/g, ' ').slice(0, 260) };
}
// Login real: POST /auth/login al host de API. Devuelve { ok, jar, token, endpoint }.
// El token (Bearer) se usa en las llamadas de datos.
async function pyxisLogin(){
  const { email, password, web, api, loginPath } = pyxisCreds();
  if (!email || !password) return { ok: false, jar: null, token: null, error: 'Faltan PYXIS_EMAIL / PYXIS_PASSWORD (Railway env).' };
  const jar = {};
  const cands = loginPath ? [loginPath, ...PYXIS_LOGIN_CANDIDATES.filter(p => p !== loginPath)] : PYXIS_LOGIN_CANDIDATES;
  let last = null;
  for (const p of cands) {
    const t = await pyxisLoginTry(api, web, p, email, password, jar);
    last = t;
    if (t.ok) return { ok: true, jar, token: t.token || null, endpoint: p, error: null };
  }
  return { ok: false, jar, token: null, endpoint: last && last.path, status: last && last.status, error: 'El login no entró. Revisá credenciales o el contrato con el diagnóstico.', debug: last && last.snippet };
}
// yyyy-m-d SIN zero-pad (así lo manda el dashboard: 2026-7-24).
function pyxisFechaHoy(){ const d = new Date(); return d.getUTCFullYear() + '-' + (d.getUTCMonth() + 1) + '-' + d.getUTCDate(); }
// BiPyxis es una SPA Angular: la URL base de la API y la ruta de login están COMPILADAS
// en el bundle main.*.js (sobreviven a la minificación como literales de string).
// Minamos el JS para descubrir el contrato real (host de API + rutas de auth/datos).
function pyxisMineBundle(js){
  const urls = [...new Set([...js.matchAll(/https?:\/\/[a-z0-9.\-]+(?::\d+)?(?:\/[A-Za-z0-9_\-./]*)?/gi)].map(m => m[0]))]
    .filter(u => !/\.(png|jpe?g|svg|gif|ico|woff2?|ttf|eot|css|map)(\?|$)/i.test(u))
    .filter(u => !/(w3\.org|googleapis|gstatic|schema\.org|angular\.(io|dev)|npmjs|github|jquery|bootstrap|cloudflare|jsdelivr|unpkg|fontawesome|sentry\.io|localhost)/i.test(u))
    .slice(0, 60);
  // Rutas de auth/login/token (literales de string cortos con esas palabras).
  const auth = [...new Set([...js.matchAll(/["'`]([A-Za-z0-9_\-./]{0,60}(?:login|logout|auth|authenticate|token|refresh|signin|sesion|session|usuario|user)[A-Za-z0-9_\-./]{0,60})["'`]/gi)].map(m => m[1]))]
    .filter(s => s.length >= 3 && s.length < 90 && !/\s/.test(s) && /[/a-z]/i.test(s)).slice(0, 50);
  // Cualquier literal que parezca ruta de API (contiene "/api" o empieza con path).
  const apiPaths = [...new Set([...js.matchAll(/["'`](\/?(?:api|v\d)\/[A-Za-z0-9_\-./{}:]{1,70})["'`]/gi)].map(m => m[1]))].slice(0, 60);
  // Endpoints vistos en la captura (ownpower / rangos por fecha).
  const captura = [...new Set([...js.matchAll(/["'`]([A-Za-z0-9_\-./?=&{}:]{0,50}(?:ownpower|ini=|\bend=|dashboard|venta|sale|cliente|comprador|customer)[A-Za-z0-9_\-./?=&{}:]{0,50})["'`]/gi)].map(m => m[1]))].filter(s => s.length < 90).slice(0, 50);
  // Contexto crudo alrededor de "ini=" y "ownpower": ahí queda literal cómo se CONSTRUYE
  // la URL de la llamada (ej. "venta/detalle/"+e+"?ini="+t). Es la pista definitiva.
  const iniCtx = pyxisMineCtx(js, 'ini=', 170, 40);
  // Fragmentos de path candidatos: literales tipo "algo/" (prefijos de recurso REST).
  const pathLits = [...new Set([...js.matchAll(/["'`]([a-z][a-z0-9\-]{1,28}(?:\/[a-z0-9\-]{1,28}){0,3}\/?)["'`]/gi)].map(m => m[1]))]
    .filter(s => /[a-z]/.test(s) && !/^(https?|www|assets|true|false|null|utf|application|json|text|image|charset|bearer|content|type)/i.test(s)).slice(0, 120);
  return { urls, auth, apiPaths, captura, iniCtx, pathLits };
}
// Extrae hasta 12 recortes de `js` alrededor de `needle` (para ver cómo se arma una URL).
function pyxisMineCtx(js, needle, before, after){
  const out = new Set(); let count = 0, from = 0;
  while (count < 12) {
    const i = js.indexOf(needle, from); if (i < 0) break;
    out.add(js.slice(Math.max(0, i - (before || 160)), Math.min(js.length, i + needle.length + (after || 40))).replace(/\s+/g, ' ').trim());
    from = i + needle.length; count++;
  }
  return [...out].slice(0, 10);
}
// De los contextos "ini=" saca prefijos de path candidatos: los literales de string que
// aparecen justo antes de la concatenación (ej. de `"venta/detalle/"+e+"?ini="` saca
// "venta/detalle/"). Devuelve prefijos únicos para probar {prefijo}{grupoId}?ini=&end=.
function pyxisPrefijosDeCtx(iniCtx){
  const pref = new Set();
  for (const ctx of (iniCtx || [])) {
    // todos los literales de string del recorte
    for (const m of ctx.matchAll(/["'`]([A-Za-z0-9_\-./]{1,40})["'`]/g)) {
      let s = m[1];
      if (/^https?:/i.test(s)) { const mm = /\/api\/(.+)$/i.exec(s); if (mm) s = mm[1]; else continue; }
      s = s.replace(/^\/+/, '');
      if (/[a-z]/i.test(s) && /\/$|[a-z\-]$/i.test(s) && !/ini=|end=|^\?|application|json|bearer|utf/i.test(s) && s.length >= 2 && s.length <= 40) pref.add(s.endsWith('/') ? s : s + '/');
    }
  }
  return [...pref].slice(0, 20);
}
// Diagnóstico: descubre el contrato real del ERP desde Railway. (1) estructura de /login
// (SPA? scripts? cookies?), (2) prueba los endpoints de login candidatos con las
// credenciales reales, (3) si alguno funciona, prueba endpoints de datos candidatos
// (incluidos los vistos en la captura: ownpower y 2?ini=&end=) y vuelca el JSON.
async function pyxisDiag(){
  const { email, password, web, api } = pyxisCreds();
  const base = web;
  const rep = { web, api, emailSet: !!email, passwordSet: !!password, loginPage: null, forms: [], loginProbe: [], dataProbe: [], winner: null };
  const jar = {};
  // 1. Página de login.
  let html = '';
  try {
    const r = await pyxisFetch(base + '/login', { method: 'GET' }, jar);
    html = await r.text();
    const scripts = [...html.matchAll(/<script\b[^>]*src=["']([^"']+)["']/gi)].map(m => m[1]).slice(0, 12);
    rep.loginPage = {
      status: r.status, titulo: (/<title[^>]*>([^<]*)<\/title>/i.exec(html) || [, ''])[1].trim().slice(0, 80),
      esSPA: /<div\s+id=["'](app|root|__nuxt|__next)["']/i.test(html) || (!/<form/i.test(html) && scripts.length > 0),
      tieneForm: /<form/i.test(html), tienePassword: /type=["']?password/i.test(html), scripts,
      setCookie: (r.headers.getSetCookie && r.headers.getSetCookie().map(c => c.split(';')[0].split('=')[0])) || [], len: html.length,
    };
  } catch (e) { rep.loginPage = { error: String(e.message).slice(0, 140) }; }
  rep.forms = [...html.matchAll(/<form\b[^>]*>[\s\S]*?<\/form>/gi)].map(f0 => { const f = f0[0]; return {
    action: (/\baction=["']([^"']*)["']/i.exec(f) || [, ''])[1], method: ((/\bmethod=["']([^"']*)["']/i.exec(f) || [, 'get'])[1]).toUpperCase(),
    tienePassword: /type=["']?password/i.test(f),
    inputs: [...f.matchAll(/<input\b[^>]*>/gi)].map(im => ({ name: (/\bname=["']([^"']+)["']/i.exec(im[0]) || [, ''])[1], type: ((/\btype=["']([^"']+)["']/i.exec(im[0]) || [, 'text'])[1]).toLowerCase() })).filter(x => x.name),
  }; });
  // 1b. Minar los bundles Angular para descubrir el host de API + rutas reales.
  rep.bundle = { fetched: [], urls: [], auth: [], apiPaths: [], captura: [], iniCtx: [], pathLits: [] };
  let ctxPrefijos = [];
  try {
    const srcs = (rep.loginPage && rep.loginPage.scripts || []).filter(s => /\.js(\?|$)/i.test(s) && !/\[/.test(s));
    const abs = srcs.map(s => (/^https?:\/\//i.test(s) ? s : base + (s.startsWith('/') ? s : '/' + s)));
    const mined = { urls: new Set(), auth: new Set(), apiPaths: new Set(), captura: new Set(), iniCtx: new Set(), pathLits: new Set() };
    await Promise.all(abs.map(async (u) => {
      try {
        const r = await pyxisFetch(u, { method: 'GET', headers: { Accept: '*/*' } }, {});
        let t = ''; try { t = await r.text(); } catch {}
        rep.bundle.fetched.push({ url: u.replace(base, ''), status: r.status, len: t.length });
        if (r.status === 200 && t.length > 100) { const m = pyxisMineBundle(t); for (const k of ['urls', 'auth', 'apiPaths', 'captura', 'iniCtx', 'pathLits']) (m[k] || []).forEach(x => mined[k].add(x)); }
      } catch (e) { rep.bundle.fetched.push({ url: u.replace(base, ''), status: 0, error: String(e.message).slice(0, 50) }); }
    }));
    rep.bundle.urls = [...mined.urls].slice(0, 60);
    rep.bundle.auth = [...mined.auth].slice(0, 50);
    rep.bundle.apiPaths = [...mined.apiPaths].slice(0, 60);
    rep.bundle.captura = [...mined.captura].slice(0, 50);
    rep.bundle.iniCtx = [...mined.iniCtx].slice(0, 12);
    rep.bundle.pathLits = [...mined.pathLits].slice(0, 120);
    ctxPrefijos = pyxisPrefijosDeCtx(rep.bundle.iniCtx);
    rep.bundle.ctxPrefijos = ctxPrefijos;
  } catch (e) { rep.bundle.error = String(e.message).slice(0, 120); }
  // 2. Probar endpoints de login (contra el host de API, secuencial, corta al 1° OK).
  if (email && password) {
    for (const p of PYXIS_LOGIN_CANDIDATES) {
      const t = await pyxisLoginTry(api, web, p, email, password, jar);
      rep.loginProbe.push({ path: t.path, ok: t.ok, status: t.status, hasToken: !!t.hasToken, isJson: !!t.isJson, setCookie: t.setCookie || [], token: t.token ? ('‹token ' + t.token.length + ' chars›') : null, snippet: t.snippet || t.error || '' });
      if (t.ok) break;
    }
    const w = rep.loginProbe.find(x => x.ok);
    rep.winner = w ? w.path : null;
    // 3. Con login OK, traer el bootstrap (auth/ownpower), parsearlo para exponer los
    //    grupos/locales a los que SÍ hay acceso, y probar el endpoint de ventas real
    //    contra esos ids con varios prefijos (el 2?ini=&end= de la captura).
    if (w) {
      const login = await pyxisLogin();
      rep.loginToken = !!login.token;
      if (login.ok) {
        const hoy = pyxisFechaHoy();
        const q = '?ini=' + hoy + '&end=' + hoy;
        const jar = { ...login.jar }, tok = login.token;
        const hit = async (p, method) => {
          const url = api + p;
          try {
            const r = await pyxisFetch(url, { method: method || 'GET', headers: { 'X-Requested-With': 'XMLHttpRequest', 'Accept': 'application/json, text/plain, */*', 'Referer': web + '/', 'Origin': web } }, jar, tok);
            const ct = r.headers.get('content-type') || ''; let t = ''; try { t = await r.text(); } catch {}
            const isJson = /json/i.test(ct) || /^\s*[[{]/.test(t);
            return { url: (method === 'POST' ? 'POST ' : '') + p, status: r.status, isJson, len: t.length, text: t };
          } catch (e) { return { url: p, status: 0, error: String(e.message).slice(0, 60) }; }
        };
        // Bootstrap: parsear grupos/locales.
        const op = await hit('/auth/ownpower');
        rep.dataProbe.push({ url: op.url, status: op.status, isJson: op.isJson, len: op.len, snippet: (op.text || '').replace(/\s+/g, ' ').slice(0, 3200), error: op.error });
        let grupos = [];
        try {
          const j = JSON.parse(op.text || '{}'); const b = j.body || j;
          const locKeys = ['locales', 'empresas', 'sucursales', 'tiendas', 'establecimientos', 'restaurantes', 'children', 'hijos'];
          grupos = (b.grupos || b.grupo || []).map(g => {
            const lk = locKeys.find(k => Array.isArray(g[k]));
            return { id: g.id, nombre: g.nombre, codigo: g.codigo, locales: lk ? g[lk].map(l => ({ id: l.id, nombre: l.nombre || l.name })) : undefined, keys: Object.keys(g) };
          });
          rep.ownpower = { bodyKeys: Object.keys(b), cmf: b.cmf ? Object.keys(b.cmf) : null, grupos };
        } catch (e) { rep.ownpower = { parseError: String(e.message).slice(0, 100) }; }
        // Endpoint de ventas (Detalle de Ventas): probar {prefijo}/{grupoId}?ini=&end=.
        // Prefijos: fijos + los derivados del contexto "ini=" del bundle (pista definitiva).
        const ids = (grupos.length ? grupos.map(g => g.id) : [1, 2]).filter(x => x != null).slice(0, 2);
        const fijos = ['', 'dashboard/', 'ventas/', 'venta/', 'venta/detalle/', 'detalle-ventas/', 'detalle-venta/', 'detalleventa/', 'sales/', 'grupo/', 'grupo/detalle-ventas/', 'reporte/detalle-ventas/', 'venta/grupo/', 'ventas/grupo/', 'ranking-sector/', 'ranking/'];
        const resources = [...new Set([...fijos, ...ctxPrefijos])];
        const urls = new Set();
        for (const id of ids) for (const rsc of resources) urls.add('/' + rsc + id + q);
        const results = await Promise.all([...urls].map(u => hit(u)));
        for (const r of results) rep.dataProbe.push({ url: r.url, status: r.status, isJson: r.isJson, len: r.len, snippet: (r.text || '').replace(/\s+/g, ' ').slice(0, 900), error: r.error });
        const good = x => (x.status >= 200 && x.status < 300 && x.isJson && x.len > 60) ? 1 : 0;
        rep.dataProbe.sort((a, b) => good(b) - good(a));
        rep.dataWinner = (rep.dataProbe.find(x => good(x) && !/ownpower/.test(x.url)) || {}).url || null;
      }
    }
  }
  return rep;
}
app.get('/admin/pyxis/estado', requireAdmin, (_req, res) => { res.json(pyxisCredsSafe()); });
app.post('/admin/pyxis/diag', requireAdmin, async (_req, res) => {
  try { res.json(await pyxisDiag()); }
  catch (e) { res.status(500).json({ error: String(e.message || e).slice(0, 200) }); }
});
// ── API real de Pyxis (contrato confirmado por captura) ──────────────────────
//   GET /api/ventas/{grupoId}              → árbol Detalle de Ventas (familia→sub→art)
//   GET /api/ventas/{grupoId}/data-filters → opciones Sector/Local/Marca
// Auth: Bearer <JWT del login>. Token cacheado hasta su expiración.
let pyxisTokCache = { token: null, exp: 0, jar: null };
async function pyxisAuth(){
  const now = Math.floor(Date.now() / 1000);
  if (pyxisTokCache.token && pyxisTokCache.exp - 60 > now) return pyxisTokCache;
  const login = await pyxisLogin();
  if (!login.ok || !login.token) throw new Error(login.error || 'Login a Pyxis falló.');
  let exp = now + 3600;
  try { const p = JSON.parse(Buffer.from(login.token.split('.')[1], 'base64').toString('utf8')); if (p.exp) exp = p.exp; } catch {}
  pyxisTokCache = { token: login.token, exp, jar: login.jar };
  return pyxisTokCache;
}
async function pyxisApiGet(path){
  const { api, web } = pyxisCreds();
  const a = await pyxisAuth();
  return pyxisFetch(api + path, { method: 'GET', headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest', 'Referer': web + '/', 'Origin': web } }, { ...a.jar }, a.token);
}
// GET JSON de la API (desenvuelve el envelope {statusCode, body}).
async function pyxisApiJson(path){
  const r = await pyxisApiGet(path);
  let t = ''; try { t = await r.text(); } catch {}
  let j = null; try { j = JSON.parse(t); } catch (e) { const err = new Error('Respuesta no-JSON de ' + path + ' (' + r.status + ')'); err.status = r.status; throw err; }
  return { status: r.status, len: t.length, body: (j && j.body !== undefined) ? j.body : j, raw: t };
}
// Esquema compacto de un JSON grande (para mapear campos sin volcar 15 MB).
function pyxisSketch(v, depth){
  depth = depth == null ? 5 : depth;
  if (v === null) return 'null';
  if (Array.isArray(v)) return { __array: v.length, of: (v.length && depth > 0) ? pyxisSketch(v[0], depth - 1) : '?' };
  if (typeof v === 'object') { const o = {}; for (const k of Object.keys(v).slice(0, 40)) o[k] = depth > 0 ? pyxisSketch(v[k], depth - 1) : typeof v[k]; return o; }
  if (typeof v === 'string') return 'str: ' + v.slice(0, 32);
  return typeof v;
}
// Busca (en profundidad) el primer nodo cuyo nombre/clave matchee rx (ej. /cerveza/i).
function pyxisFindNode(v, rx, depth){
  depth = depth == null ? 8 : depth; if (depth < 0 || v == null) return null;
  if (Array.isArray(v)) { for (const x of v) { const r = pyxisFindNode(x, rx, depth - 1); if (r) return r; } return null; }
  if (typeof v === 'object') {
    for (const nk of ['nombre', 'name', 'descripcion', 'familia', 'subfamilia', 'label', 'titulo', 'glosa']) if (typeof v[nk] === 'string' && rx.test(v[nk])) return v;
    for (const k of Object.keys(v)) { if (rx.test(k)) return v[k]; const r = pyxisFindNode(v[k], rx, depth - 1); if (r) return r; }
  }
  return null;
}
// Análisis: baja /ventas/{grupo} y devuelve familias distintas (con conteo y $), una
// muestra de las filas de Kairos y la lista de marcas — para mapear cómo aislar las
// cervezas sin inventar categorías.
app.post('/admin/pyxis/ventas-analisis', requireAdmin, async (req, res) => {
  try {
    const grupo = String((req.body && req.body.grupo) || 2).replace(/[^0-9]/g, '') || '2';
    const v = await pyxisApiJson('/ventas/' + grupo);
    const rows = Array.isArray(v.body && v.body.ventas) ? v.body.ventas : (Array.isArray(v.body) ? v.body : []);
    const num = x => { const n = Number(x); return Number.isFinite(n) ? n : 0; };
    const total3 = r => num(r.p1) + num(r.p2) + num(r.p3);
    const cant3 = r => num(r.q1) + num(r.q2) + num(r.q3);
    // Familias distintas con conteo de filas y monto total.
    const fam = {};
    for (const r of rows) { const f = (r.familia == null ? '(sin)' : String(r.familia)); const o = fam[f] || (fam[f] = { filas: 0, monto: 0 }); o.filas++; o.monto += total3(r); }
    const familias = Object.entries(fam).map(([nombre, o]) => ({ nombre, filas: o.filas, monto: Math.round(o.monto) })).sort((a, b) => b.monto - a.monto);
    // Muestra de filas de Kairos.
    const kairos = rows.filter(r => /kairos/i.test(r.nombreProducto || '')).slice(0, 20)
      .map(r => ({ familia: r.familia, producto: r.nombreProducto, marca: r.nombreMarca, local: r.nombreLocal, total: Math.round(total3(r)), cant: cant3(r) }));
    // Marcas y locales distintos.
    const marcas = [...new Set(rows.map(r => r.nombreMarca).filter(Boolean))].sort();
    const locales = [...new Set(rows.map(r => r.nombreLocal).filter(Boolean))].sort();
    const productosKairos = [...new Set(rows.filter(r => /kairos/i.test(r.nombreProducto || '')).map(r => r.nombreProducto))].sort();
    // Productos distintos dentro de "Con Alcohol" (para armar el clasificador de cervezas).
    const ca = {};
    for (const r of rows) { if (!/con\s*alcohol/i.test(String(r.familia || ''))) continue; const p = r.nombreProducto || '(sin)'; const o = ca[p] || (ca[p] = { total: 0, cant: 0 }); o.total += total3(r); o.cant += cant3(r); }
    const conAlcoholProductos = Object.entries(ca).map(([producto, o]) => ({ producto, total: Math.round(o.total), cant: o.cant })).sort((a, b) => b.total - a.total).slice(0, 300);
    res.json({ grupo, totalRows: rows.length, familias, kairosSample: kairos, productosKairos, conAlcoholCount: Object.keys(ca).length, conAlcoholProductos, marcasCount: marcas.length, marcas: marcas.slice(0, 60), localesCount: locales.length, sampleRow: rows[0] || null });
  } catch (e) { res.status(500).json({ error: String(e.message || e).slice(0, 200) }); }
});
app.post('/admin/pyxis/ventas-estructura', requireAdmin, async (req, res) => {
  try {
    const grupo = String((req.body && req.body.grupo) || 2).replace(/[^0-9]/g, '') || '2';
    const out = { grupo };
    // Árbol de ventas (grande).
    try {
      const v = await pyxisApiJson('/ventas/' + grupo);
      out.ventas = { status: v.status, len: v.len, sketch: pyxisSketch(v.body, 5) };
      const cerv = pyxisFindNode(v.body, /cerveza/i);
      const cs = cerv ? JSON.stringify(cerv) : '';
      out.ventas.cervezas = cerv ? (cs.length < 22000 ? cs : cs.slice(0, 9000) + '…‹truncado›') : '‹no se encontró un nodo "Cerveza"›';
    } catch (e) { out.ventas = { error: String(e.message).slice(0, 160) }; }
    // Filtros (Sector/Local/Marca).
    try {
      const f = await pyxisApiJson('/ventas/' + grupo + '/data-filters');
      out.filters = { status: f.status, len: f.len, sketch: pyxisSketch(f.body, 4), raw: (f.raw || '').slice(0, 4500) };
    } catch (e) { out.filters = { error: String(e.message).slice(0, 160) }; }
    res.json(out);
  } catch (e) { res.status(500).json({ error: String(e.message || e).slice(0, 200) }); }
});

// ─────────────────────────────────────────────────────────────────────────────
// Pyxis · Ventas HORECA de cervezas (Kairos vs competencia)
// /ventas/{grupo} = array plano {familia, nombreProducto, nombreMarca, nombreLocal,
//   p1..p3 ($ por mes), q1..q3 (unidades por mes)}. Filtramos "Con Alcohol",
//   clasificamos cuáles son CERVEZA (editable, por nombre) y separamos Kairos
//   (marcas propias) de la competencia. Todos los $ son REALES de Pyxis; la
//   clasificación cerveza/no-cerveza es por nombre, transparente y editable.
// ─────────────────────────────────────────────────────────────────────────────
const PYXIS_CERV_FILE = join(PROMPTS_EFFECTIVE_DIR, 'pyxis-cervezas.json');
const PYXIS_CERV_DEFAULT = {
  kairosBrands: ['kairos', 'firulais', 'banny', 'badass'],
  beerBrands: ['stella', 'corona', 'cusque', 'austral', 'heineken', 'quilmes', 'kross', 'asahi', 'sapporo', 'kunstmann', 'torobayo', 'osagui', 'lanus', 'pacifico'],
  strongKw: ['schop', 'schopp', 'chopp', 'chelada', 'michelada', '\\bcerveza\\b', 'lager', 'pilsen', 'garza', 'media pinta', 'beer taste', 'cerveza invitada', 'coleccion artistas', 'colección artistas'],
  weakKw: ['\\bpils\\b', 'golden ale', 'stout', 'neipa', 'weizen', 'red ale', 'pale ale', '\\bipa\\b'],
  exclude: ['sour', 'pisco', 'mojito', 'margarita', '\\bgin\\b', 'tonic', 'spritz', 'sangria', 'sangrona', 'negroni', 'martini', 'martin', 'whisky', 'whiskey', 'vodka', '\\bron\\b', 'tequila', 'fernet', 'aperol', 'ramaz', 'piscol', 'don julio', 'johnnie', 'jack daniels', 'macallan', 'jager', 'tanqueray', 'grey goose', 'hendrick', 'st germain', 'amaretto', 'rumchata', 'carajillo', 'clericot', 'vaina', 'tom collins', 'moscow', 'paloma', 'mezcal', '\\bsake\\b', 'daiquiri', 'daikiri', 'caipir', 'cosmopol', 'chilcano', 'algarrobina', 'borgo'],
  overrides: {},   // { "Nombre exacto del producto": "kairos" | "otra" | "no" }
  // Locales del grupo que son NUESTROS: adentro de ellos Kairos es la casa, así
  // que inflan la participación y tapan cómo vamos en el resto de GMS. Se
  // matchean por texto contenido en el nombre del local (sin acentos).
  // Se listan las variantes de escritura conocidas (Vespucio aparece abreviado
  // como "VSP" en Pyxis). Igual se pueden elegir a dedo desde el panel.
  localesPropios: ['garden vsp', 'garden vespucio', 'garden antofagasta', 'badass'],
  // En Pyxis un "local" es el RECINTO (Antofagasta, Kairos Vespucio) y adentro
  // conviven muchas MARCAS (cada restaurante del grupo). Nuestros locales no
  // siempre tienen local propio — en Antofagasta somos una marca dentro del
  // recinto — así que la identidad real es la marca. Match exacto: la lista de
  // marcas de Pyxis es cerrada y "KAIROS CD" no es un local que venda al público.
  marcasPropias: ['KAIROS', 'KAIROS BADASS'],
};
const pyxisNorm = (s) => String(s == null ? '' : s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
// ¿El local es de los nuestros? Match por TOKENS: el patrón calza si todas sus
// palabras están en el nombre del local, en cualquier orden y con lo que sea en
// el medio. Así "garden vsp" agarra "KAIROS GARDEN VSP", "Garden - VSP" o
// "Kairos Garden Plaza VSP" sin depender de cómo lo escriban en Pyxis.
function pyxisEsLocalPropio(nombreLocal, cfg){
  const n = pyxisNorm(nombreLocal); if (!n) return false;
  const palabras = new Set(n.split(' ').filter(Boolean));
  return (cfg.localesPropios || []).some(p => {
    const toks = pyxisNorm(p).split(' ').filter(Boolean);
    return toks.length > 0 && toks.every(t => palabras.has(t));
  });
}
// Marca propia: match EXACTO sobre el nombre normalizado. A diferencia de los
// locales, acá no se usan tokens: "KAIROS" por tokens también agarraría
// "KAIROS CD", que es el centro de distribución y no un local que venda cerveza
// al público — contarlo volvería a inflar la participación.
function pyxisEsMarcaPropia(nombreMarca, cfg){
  const n = pyxisNorm(nombreMarca); if (!n) return false;
  return (cfg.marcasPropias || []).some(m => pyxisNorm(m) === n);
}
// Una fila es de un local nuestro si lo es su recinto O su marca.
const pyxisFilaPropia = (local, marca, cfg) => pyxisEsLocalPropio(local, cfg) || pyxisEsMarcaPropia(marca, cfg);
// Nombre con el que se sigue cada local propio. Como en un mismo recinto puede
// haber más de una marca nuestra (y una marca nuestra puede estar en varios
// recintos), la identidad es marca + recinto: "KAIROS · Antofagasta".
const pyxisNombrePropio = (local, marca) => (marca && local) ? (marca + ' · ' + local) : (marca || local || '—');
// Alcance del análisis: todo el grupo, el grupo SIN nuestros locales (la lectura
// no sesgada) o solo nuestros locales.
const PYXIS_ALCANCES = ['todos', 'sin_propios', 'solo_propios'];
function pyxisCervCfgLoad(){ try { if (existsSync(PYXIS_CERV_FILE)) return { ...PYXIS_CERV_DEFAULT, ...JSON.parse(readFileSync(PYXIS_CERV_FILE, 'utf-8')) }; } catch (e) { console.warn('pyxis cerv cfg:', e.message); } return { ...PYXIS_CERV_DEFAULT, overrides: {} }; }
function pyxisCervCfgSave(o){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(PYXIS_CERV_FILE, JSON.stringify(o, null, 2)); }
// Clasifica un producto de "Con Alcohol": 'kairos' (marca propia), 'otra' (competencia)
// o null (no es cerveza). Overrides por nombre exacto tienen prioridad.
function pyxisClasificarCerveza(nombre, cfg){
  const n = String(nombre || '').toLowerCase().trim();
  const ov = cfg.overrides && cfg.overrides[String(nombre || '').trim()];
  if (ov === 'no') return null; if (ov === 'kairos') return 'kairos'; if (ov === 'otra') return 'otra';
  const any = arr => (arr || []).some(rx => { try { return new RegExp(rx).test(n); } catch { return n.includes(String(rx).toLowerCase()); } });
  const isKairos = any(cfg.kairosBrands);
  const strongBeer = isKairos || any(cfg.beerBrands) || any(cfg.strongKw);
  const excl = any(cfg.exclude);
  if (excl && !strongBeer) return null;
  if (strongBeer) return isKairos ? 'kairos' : 'otra';
  if (any(cfg.weakKw) && !excl) return 'otra';
  return null;
}
// Caché del array de ventas (15 MB, ~4 s en bajar): se refresca cada 30 min o con force.
const PYXIS_VENTAS_TTL_MS = 60 * 1000; // 1 min: cambiar filtros es instantáneo; el auto-refresh baja data fresca
let pyxisVentasCache = { grupo: null, rows: null, at: 0 };
async function pyxisVentasRows(grupo, force){
  const now = Date.now();
  if (!force && pyxisVentasCache.rows && pyxisVentasCache.grupo === grupo && (now - pyxisVentasCache.at) < PYXIS_VENTAS_TTL_MS) return pyxisVentasCache.rows;
  const v = await pyxisApiJson('/ventas/' + grupo);
  const rows = Array.isArray(v.body && v.body.ventas) ? v.body.ventas : (Array.isArray(v.body) ? v.body : []);
  pyxisVentasCache = { grupo, rows, at: now };
  return rows;
}
const PYXIS_MESES = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
// Los 3 períodos p1/p2/p3 son los últimos 3 meses (p3 = mes actual).
function pyxisMesesLabels(){ const d = new Date(); const out = []; for (let i = 2; i >= 0; i--) { const dd = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() - i, 1)); out.push(PYXIS_MESES[dd.getUTCMonth()] + ' ' + dd.getUTCFullYear()); } return out; }
// Los mismos 3 períodos como clave estable "AAAA-MM", para indexar la historia.
function pyxisMesesKeys(){ const d = new Date(); const out = []; for (let i = 2; i >= 0; i--) { const dd = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() - i, 1)); out.push(dd.getUTCFullYear() + '-' + String(dd.getUTCMonth() + 1).padStart(2, '0')); } return out; }
const pyxisMesLabel = (key) => { const [y, m] = String(key || '').split('-'); const i = Number(m) - 1; return (PYXIS_MESES[i] || '?') + ' ' + y; };
async function pyxisCervezasResumen(grupo, opts){
  opts = opts || {};
  const rows = await pyxisVentasRows(grupo, opts.force);
  const cfg = pyxisCervCfgLoad();
  const num = x => { const n = Number(x); return Number.isFinite(n) ? n : 0; };
  const norm = s => String(s == null ? '' : s).trim();
  const fS = norm(opts.sector), fL = norm(opts.local), fM = norm(opts.marca);
  const alcance = PYXIS_ALCANCES.includes(String(opts.alcance || '')) ? String(opts.alcance) : 'todos';
  const prod = new Map();      // nombre → { tipo, m:[3], q:[3], total, cant, locales:Map }
  const localTot = new Map();  // local → { kairos, otras, kairosM[3], otrasM[3], propio }
  const sinClas = new Map();   // productos "Con Alcohol" no clasificados como cerveza
  const optS = new Set(), optL = new Set(), optM = new Set(); // opciones de filtro (de filas cerveza)
  // Corte propios / resto de GMS: se agrega SIEMPRE con los mismos filtros de
  // sector/marca pero ignorando el alcance, para poder mostrar los tres bloques
  // comparados aunque estés viendo uno solo.
  const grupoVacio = () => ({ kairos: 0, otras: 0, kairosM: [0, 0, 0], otrasM: [0, 0, 0] });
  const porGrupo = { total: grupoVacio(), propios: grupoVacio(), resto: grupoVacio() };
  const propiosDetalle = new Map(); // local propio → grupoVacio()
  for (const r of rows) {
    if (!/con\s*alcohol/i.test(String(r.familia || ''))) continue;
    const nombre = norm(r.nombreProducto); if (!nombre) continue;
    const tipo = pyxisClasificarCerveza(nombre, cfg);
    // Opciones de filtro: de TODAS las filas cerveza (para poder cambiar la selección).
    if (tipo) { if (r.nombreSector) optS.add(norm(r.nombreSector)); if (r.nombreLocal) optL.add(norm(r.nombreLocal)); if (r.nombreMarca) optM.add(norm(r.nombreMarca)); }
    // Filtro por dimensión (Sector / Local / Marca) para la agregación.
    if (fS && norm(r.nombreSector) !== fS) continue;
    if (fL && norm(r.nombreLocal) !== fL) continue;
    if (fM && norm(r.nombreMarca) !== fM) continue;
    const m = [num(r.p1), num(r.p2), num(r.p3)]; const q = [num(r.q1), num(r.q2), num(r.q3)];
    const tot = m[0] + m[1] + m[2], can = q[0] + q[1] + q[2];
    if (!tipo) { const s = sinClas.get(nombre) || { total: 0 }; s.total += tot; sinClas.set(nombre, s); continue; }
    const loc = norm(r.nombreLocal) || '—';
    const mkt = norm(r.nombreMarca);
    const propio = pyxisFilaPropia(loc, mkt, cfg);
    // Comparativa propios vs resto: se llena antes de aplicar el alcance.
    const campo = tipo === 'kairos' ? 'kairos' : 'otras';
    for (const g of [porGrupo.total, propio ? porGrupo.propios : porGrupo.resto]) {
      g[campo] += tot;
      for (let i = 0; i < 3; i++) g[campo + 'M'][i] += m[i];
    }
    // Cada local propio por separado, sin importar el alcance elegido: es la
    // comparación que se sigue mes a mes (Vespucio vs Antofagasta vs Badass).
    if (propio) {
      const clave = pyxisNombrePropio(loc, mkt);
      let dp = propiosDetalle.get(clave);
      if (!dp) { dp = grupoVacio(); propiosDetalle.set(clave, dp); }
      dp[campo] += tot;
      for (let i = 0; i < 3; i++) dp[campo + 'M'][i] += m[i];
    }
    if (alcance === 'sin_propios' && propio) continue;
    if (alcance === 'solo_propios' && !propio) continue;
    let p = prod.get(nombre);
    if (!p) { p = { nombre, tipo, m: [0, 0, 0], q: [0, 0, 0], total: 0, cant: 0, locales: new Map() }; prod.set(nombre, p); }
    for (let i = 0; i < 3; i++) { p.m[i] += m[i]; p.q[i] += q[i]; } p.total += tot; p.cant += can;
    p.locales.set(loc, (p.locales.get(loc) || 0) + tot);
    let lt = localTot.get(loc);
    if (!lt) { lt = { kairos: 0, otras: 0, kairosM: [0, 0, 0], otrasM: [0, 0, 0], propio }; localTot.set(loc, lt); }
    lt[campo] += tot;
    for (let i = 0; i < 3; i++) lt[campo + 'M'][i] += m[i];
  }
  const arr = [...prod.values()].map(p => ({ nombre: p.nombre, tipo: p.tipo, m: p.m.map(Math.round), q: p.q, total: Math.round(p.total), cant: p.cant, topLocales: [...p.locales.entries()].sort((a, b) => b[1] - a[1]).slice(0, 3).map(([l, v]) => ({ local: l, total: Math.round(v) })) }));
  const kairos = arr.filter(p => p.tipo === 'kairos').sort((a, b) => b.total - a.total);
  const otras = arr.filter(p => p.tipo === 'otra').sort((a, b) => b.total - a.total);
  const sum = a => a.reduce((s, p) => s + p.total, 0), sumC = a => a.reduce((s, p) => s + p.cant, 0);
  const kTot = sum(kairos), oTot = sum(otras), cTot = kTot + oTot;
  const localesTop = [...localTot.entries()].map(([local, v]) => ({ local, propio: !!v.propio, kairos: Math.round(v.kairos), otras: Math.round(v.otras), total: Math.round(v.kairos + v.otras) })).sort((a, b) => b.kairos - a.kairos);
  // Bloque comparado + serie por mes de cada bloque. El share por mes es lo que
  // se guarda en la historia: es la métrica que se sigue en el tiempo.
  const cerrarGrupo = (g) => {
    const cerv = g.kairos + g.otras;
    return {
      kairos: Math.round(g.kairos), otras: Math.round(g.otras), cervezas: Math.round(cerv),
      shareKairos: cerv ? Math.round(g.kairos / cerv * 1000) / 10 : 0,
      porMes: [0, 1, 2].map(i => {
        const c = g.kairosM[i] + g.otrasM[i];
        return { kairos: Math.round(g.kairosM[i]), otras: Math.round(g.otrasM[i]), cervezas: Math.round(c), shareKairos: c ? Math.round(g.kairosM[i] / c * 1000) / 10 : 0 };
      }),
    };
  };
  return {
    grupo, meses: pyxisMesesLabels(), mesesKeys: pyxisMesesKeys(), generadoEn: new Date().toISOString(),
    filtros: { sector: fS, local: fL, marca: fM }, alcance, alcances: PYXIS_ALCANCES,
    opciones: { sectores: [...optS].sort(), locales: [...optL].sort(), marcas: [...optM].sort() },
    totales: { kairos: kTot, otras: oTot, cervezas: cTot, shareKairos: cTot ? Math.round(kTot / cTot * 1000) / 10 : 0, kairosCant: sumC(kairos), otrasCant: sumC(otras), nKairos: kairos.length, nOtras: otras.length },
    porGrupo: { total: cerrarGrupo(porGrupo.total), propios: cerrarGrupo(porGrupo.propios), resto: cerrarGrupo(porGrupo.resto) },
    propiosDetalle: [...propiosDetalle.entries()].map(([local, g]) => ({ local, ...cerrarGrupo(g) })).sort((a, b) => b.cervezas - a.cervezas),
    localesPropios: cfg.localesPropios || [], marcasPropias: cfg.marcasPropias || [],
    // Locales y marcas del grupo con la marca de si hoy cuentan como propios:
    // así se pueden tildar a dedo desde el panel. La lista de MARCAS es la que
    // importa cuando compartimos recinto con otros restaurantes del grupo.
    localesTodos: [...optL].sort().map(nombre => ({ nombre, propio: pyxisEsLocalPropio(nombre, cfg) })),
    marcasTodas: [...optM].sort().map(nombre => ({ nombre, propio: pyxisEsMarcaPropia(nombre, cfg) })),
    kairos, otras, localesTop: localesTop.slice(0, 15),
    sinClasificar: [...sinClas.entries()].map(([nombre, v]) => ({ nombre, total: Math.round(v.total) })).sort((a, b) => b.total - a.total).slice(0, 50),
  };
}
// ── Historia mes a mes de la participación de Kairos en GMS ──
// Pyxis solo expone los últimos 3 meses (p1/p2/p3), así que la serie larga hay
// que ir guardándola: cada lectura SIN filtros graba esos 3 meses. El mes en
// curso se pisa en cada pasada (va incompleto hasta que cierra) y los meses
// viejos quedan congelados aunque Pyxis ya no los devuelva.
// Junto a la serie viven los HITOS (máquinas shoperas, Osagui, beer tour…), que
// son los que permiten leer un salto de participación contra lo que se hizo.
const PYXIS_CERV_HIST_FILE = join(PROMPTS_EFFECTIVE_DIR, 'pyxis-cervezas-historia.json');
// Versión del CORTE con el que se calculó cada mes guardado.
//  1 = propios detectados solo por local (no veía Kairos Antofagasta, que es una
//      marca dentro del recinto "Antofagasta") y el detalle se guardaba con el
//      nombre del recinto.
//  2 = propios por marca + recinto, con la clave "MARCA · Recinto".
// Los meses en v1 tienen el split propios/resto mal y las claves del detalle en
// otro formato: si se mezclan con los nuevos, el mismo local aparece dos veces
// con nombres distintos. Se les limpia el corte y queda solo el total, que sí
// es correcto (no depende de qué se considere propio).
const PYXIS_HIST_V = 2;
function pyxisHistNormalizar(h){
  let cambio = false;
  for (const [key, m] of Object.entries(h.meses || {})) {
    if (Number(m && m.v) >= PYXIS_HIST_V) continue;
    h.meses[key] = { mes: key, actualizadoEn: m && m.actualizadoEn, v: PYXIS_HIST_V, total: (m && m.total) || null, propios: null, resto: null, locales: {} };
    cambio = true;
  }
  return cambio;
}
function pyxisHistLoad(){
  try {
    if (existsSync(PYXIS_CERV_HIST_FILE)) {
      const p = JSON.parse(readFileSync(PYXIS_CERV_HIST_FILE, 'utf-8'));
      const h = { version: 1, meses: p.meses && typeof p.meses === 'object' ? p.meses : {}, hitos: Array.isArray(p.hitos) ? p.hitos : [] };
      if (pyxisHistNormalizar(h)) pyxisHistSave(h);
      return h;
    }
  }
  catch (e) { console.warn('pyxis cerv historia:', e.message); }
  return { version: 1, meses: {}, hitos: [] };
}
function pyxisHistSave(h){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(PYXIS_CERV_HIST_FILE, JSON.stringify(h, null, 2)); }
// Graba los 3 meses del resumen. Solo se llama con el resumen SIN filtros: si no,
// la serie mezclaría recortes distintos y dejaría de ser comparable mes a mes.
function pyxisHistGuardar(d){
  if (!d || !Array.isArray(d.mesesKeys)) return false;
  const h = pyxisHistLoad();
  const foto = (g, i) => ({ kairos: g.porMes[i].kairos, otras: g.porMes[i].otras, cervezas: g.porMes[i].cervezas, shareKairos: g.porMes[i].shareKairos });
  let cambio = false;
  d.mesesKeys.forEach((key, i) => {
    const reg = {
      mes: key, actualizadoEn: new Date().toISOString(), v: PYXIS_HIST_V,
      total: foto(d.porGrupo.total, i), propios: foto(d.porGrupo.propios, i), resto: foto(d.porGrupo.resto, i),
      locales: Object.fromEntries((d.propiosDetalle || []).map(p => [p.local, foto(p, i)])),
    };
    const ant = h.meses[key];
    // Un mes sin venta (Pyxis todavía no lo cargó) no pisa un mes ya guardado.
    if (!reg.total.cervezas && ant) return;
    const igual = ant && JSON.stringify({ ...ant, actualizadoEn: 0 }) === JSON.stringify({ ...reg, actualizadoEn: 0 });
    if (igual) return;
    h.meses[key] = reg; cambio = true;
  });
  if (cambio) pyxisHistSave(h);
  return cambio;
}
function pyxisHistSerie(){
  const h = pyxisHistLoad();
  const meses = Object.keys(h.meses).sort().map(k => ({ ...h.meses[k], mes: k, label: pyxisMesLabel(k) }));
  const hitos = h.hitos.slice().sort((a, b) => String(a.mes).localeCompare(String(b.mes)));
  // Locales propios que aparecen en algún mes, para armar las columnas.
  const locales = [...new Set(meses.flatMap(m => Object.keys(m.locales || {})))].sort();
  return { meses, hitos, locales };
}
function pyxisCervOpts(req){ const g = req.query || req.body || {}; return { sector: g.sector, local: g.local, marca: g.marca, alcance: g.alcance }; }
app.get('/admin/pyxis/cervezas', requireAdmin, async (req, res) => {
  try {
    const grupo = String(req.query.grupo || 2).replace(/[^0-9]/g, '') || '2';
    const d = await pyxisCervezasResumen(grupo, { ...pyxisCervOpts(req), force: req.query.force === '1' });
    // La historia se alimenta sola, pero solo con la vista completa del grupo.
    if (!d.filtros.sector && !d.filtros.local && !d.filtros.marca) { try { pyxisHistGuardar(d); } catch (e) { console.warn('pyxis hist:', e.message); } }
    res.json({ ...d, historia: pyxisHistSerie() });
  }
  catch (e) { res.status(500).json({ error: String(e.message || e).slice(0, 200) }); }
});
app.get('/admin/pyxis/cervezas/historia', requireAdmin, (_req, res) => res.json(pyxisHistSerie()));
// Hitos: qué se hizo y cuándo, para poder atribuir los saltos de participación.
app.post('/admin/pyxis/cervezas/hitos', requireAdmin, (req, res) => {
  const b = req.body || {};
  const mes = String(b.mes || '').trim();
  if (!/^\d{4}-\d{2}$/.test(mes)) return res.status(400).json({ error: 'Mes inválido (formato AAAA-MM).' });
  const titulo = String(b.titulo || '').trim().slice(0, 120);
  if (!titulo) return res.status(400).json({ error: 'Falta el título del hito.' });
  const h = pyxisHistLoad();
  h.hitos.push({ id: randomUUID(), mes, titulo, local: String(b.local || '').trim().slice(0, 120), nota: String(b.nota || '').trim().slice(0, 400) });
  pyxisHistSave(h);
  res.json(pyxisHistSerie());
});
app.delete('/admin/pyxis/cervezas/hitos/:id', requireAdmin, (req, res) => {
  const h = pyxisHistLoad();
  const id = String(req.params.id);
  const n = h.hitos.length;
  h.hitos = h.hitos.filter(x => x.id !== id);
  if (h.hitos.length !== n) pyxisHistSave(h);
  res.json(pyxisHistSerie());
});
