app.post('/admin/pyxis/cervezas/resumen/generar', requireAdmin, async (req, res) => {
  try {
    const grupo = String((req.body && req.body.grupo) || 2).replace(/[^0-9]/g, '') || '2';
    const b = req.body || {};
    const d = await pyxisCervezasResumen(grupo, { sector: b.sector, local: b.local, marca: b.marca });
    const fmt = n => '$' + Math.round(Number(n) || 0).toLocaleString('es-CL');
    const top = a => (a.slice(0, 10).map(p => `  · ${p.nombre}: ${fmt(p.total)} (${p.cant} u)`).join('\n') || '  (sin datos)');
    const filtroTxt = [d.filtros.sector && ('sector ' + d.filtros.sector), d.filtros.local && ('local ' + d.filtros.local), d.filtros.marca && ('marca ' + d.filtros.marca)].filter(Boolean).join(', ');
    const datos = [
      `Período (últimos 3 meses): ${d.meses.join(', ')}. Grupo HORECA ${grupo}.${filtroTxt ? ' FILTRO ACTIVO: ' + filtroTxt + '.' : ''}`,
      `TOTAL cervezas: ${fmt(d.totales.cervezas)}.`,
      `Kairos (marcas propias): ${fmt(d.totales.kairos)} = ${d.totales.shareKairos}% del total, ${d.totales.kairosCant} unidades, ${d.totales.nKairos} productos.`,
      `Otras cervezas (competencia): ${fmt(d.totales.otras)} = ${Math.round((100 - d.totales.shareKairos) * 10) / 10}%, ${d.totales.otrasCant} unidades, ${d.totales.nOtras} productos.`,
      ``,
      `LECTURA SIN SESGO — el grupo incluye locales NUESTROS (${(d.localesPropios || []).join(', ') || 'ninguno configurado'}), donde Kairos es la cerveza de la casa:`,
      `  · Resto de GMS (sin nuestros locales): ${fmt(d.porGrupo.resto.cervezas)} de cerveza, Kairos ${fmt(d.porGrupo.resto.kairos)} = ${d.porGrupo.resto.shareKairos}%. Esta es la participación real ganada afuera.`,
      `  · Locales propios: ${fmt(d.porGrupo.propios.cervezas)} de cerveza, Kairos ${fmt(d.porGrupo.propios.kairos)} = ${d.porGrupo.propios.shareKairos}%.`,
      ...(d.propiosDetalle || []).map(p => `      · ${p.local}: Kairos ${p.shareKairos}% (${fmt(p.kairos)} de ${fmt(p.cervezas)})`),
      ...(() => {
        // Serie mes a mes con los hitos, para que pueda hablar de evolución sin inventarla.
        const H = pyxisHistSerie();
        if (!H.meses.length) return [];
        const hitosPorMes = {}; H.hitos.forEach(h => { (hitosPorMes[h.mes] = hitosPorMes[h.mes] || []).push(h.titulo + (h.local ? ' (' + h.local + ')' : '')); });
        return ['', 'EVOLUCIÓN mes a mes de la participación de Kairos (guardada, incluye meses fuera del período de arriba):',
          ...H.meses.map(m => `  · ${m.label}: resto de GMS ${m.resto.shareKairos}% · total GMS ${m.total.shareKairos}% · propios ${m.propios.shareKairos}%${hitosPorMes[m.mes] ? ' — HITOS ese mes: ' + hitosPorMes[m.mes].join('; ') : ''}`)];
      })(),
      ``, `Top cervezas Kairos:`, top(d.kairos),
      ``, `Top cervezas competencia:`, top(d.otras),
      ``, `Locales por venta Kairos (Kairos $ / otras $):`,
      (d.localesTop.slice(0, 12).map(l => `  · ${l.local}: Kairos ${fmt(l.kairos)} / otras ${fmt(l.otras)}`).join('\n') || '  (sin datos)'),
    ].join('\n');
    const sys = 'Sos analista comercial de Kairos (cervecería artesanal). Analizás las ventas de cervezas en los locales HORECA de Grupo Mil Sabores. Escribe en español chileno neutro (tuteo), claro y accionable, en 2 o 3 párrafos breves. Cubre: cómo venden las cervezas Kairos vs la competencia (participación), qué productos Kairos lideran, en qué locales pegan más y dónde hay oportunidad (locales donde la competencia domina y Kairos casi no vende). IMPORTANTE: el grupo incluye locales propios de Kairos, donde la cerveza de la casa es Kairos; la participación que importa para medir cómo vamos afuera es la del RESTO de GMS, así que usá esa como cifra principal y mencioná la total solo como contexto. Si hay serie mes a mes, comentá la tendencia; si hay hitos marcados en un mes, podés señalar que coinciden en el tiempo con un cambio, pero NO afirmes que lo causaron. REGLA ABSOLUTA: usá ÚNICAMENTE los números que te paso abajo; NO inventes ni estimes NINGÚN número ni causa; si falta un dato, omitilo.';
    const msg = await client.messages.create({ model: 'claude-sonnet-4-6', max_tokens: 900, system: sys, messages: [{ role: 'user', content: 'Cifras reales (de Pyxis):\n' + datos }] });
    const texto = (msg.content || []).filter(c => c.type === 'text').map(c => c.text).join('').trim();
    const out = { texto, generadoEn: new Date().toISOString(), grupo, meses: d.meses };
    pyxisCervResumenSave(out); res.json(out);
  } catch (e) { res.status(500).json({ error: 'No se pudo generar el resumen: ' + String(e.message || e).slice(0, 200) }); }
});

// ─────────────────────────────────────────────────────────────────────────────
// FASE 4 · Sell Out Hospitality (Kairos Garden / Kairos Badass), vía Pyxis.
// La API de Pyxis entrega la misma planilla de ventas por LOCAL con un campo
// `familia` (categoría) por fila — NO viene pre-separada en Comida/Barra, hay
// que armarla. Como no hay forma de adivinar sin inventar (los nombres reales
// de `nombreLocal`/`familia` los define Pyxis, no nosotros), el mapeo queda
// 100% configurable desde el panel: qué locales son Hospitality y qué familia
// cuenta como Comida vs Barra. Sin configurar, honestamente "Sin datos" (no
// hay locales/familias por defecto adivinados).
// ─────────────────────────────────────────────────────────────────────────────
const PYXIS_HOSP_FILE = join(PROMPTS_EFFECTIVE_DIR, 'pyxis-hospitality.json');
function pyxisHospCfgLoad(){
  try {
    if (existsSync(PYXIS_HOSP_FILE)) {
      const p = JSON.parse(readFileSync(PYXIS_HOSP_FILE, 'utf-8'));
      return {
        locales: Array.isArray(p.locales) ? p.locales : [],
        // En Pyxis el "local" es el RECINTO y adentro conviven las marcas de
        // cada restaurante del grupo. Kairos Antofagasta no tiene local propio:
        // es la marca KAIROS dentro del recinto "Antofagasta". Sin poder elegir
        // por marca, o se deja afuera o se arrastra todo el recinto ajeno.
        marcas: Array.isArray(p.marcas) ? p.marcas : [],
        familiaComida: Array.isArray(p.familiaComida) ? p.familiaComida : [],
        familiaBarra: Array.isArray(p.familiaBarra) ? p.familiaBarra : [],
      };
    }
  } catch (e) { console.warn('pyxis hosp cfg:', e.message); }
  return { locales: [], marcas: [], familiaComida: [], familiaBarra: [] };
}
function pyxisHospCfgSave(o){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(PYXIS_HOSP_FILE, JSON.stringify(o, null, 2)); }

async function pyxisHospitalidadResumen(grupo, opts){
  opts = opts || {};
  const rows = await pyxisVentasRows(grupo, opts.force);
  const cfg = pyxisHospCfgLoad();
  const num = x => { const n = Number(x); return Number.isFinite(n) ? n : 0; };
  const norm = s => String(s == null ? '' : s).trim();
  // Opciones de configuración: TODOS los locales/familias reales que trae
  // Pyxis para este grupo (para que la config se llene eligiendo de una
  // lista real, nunca escribiendo a mano un nombre adivinado).
  const localesDisponibles = [...new Set(rows.map(r => norm(r.nombreLocal)).filter(Boolean))].sort();
  const marcasDisponibles = [...new Set(rows.map(r => norm(r.nombreMarca)).filter(Boolean))].sort();
  const familiasDisponibles = [...new Set(rows.map(r => norm(r.familia)).filter(Boolean))].sort();

  if (!cfg.locales.length && !cfg.marcas.length) {
    return {
      available: false,
      reason: 'Sin datos: no hay locales ni marcas de Hospitality configurados todavía. Elegí en ⚙️ qué es Kairos Garden/Badass — normalmente la MARCA, porque compartimos recinto con el resto del grupo.',
      config: cfg, localesDisponibles, marcasDisponibles, familiasDisponibles,
    };
  }
  const localesSet = new Set(cfg.locales.map(norm));
  const marcasSet = new Set((cfg.marcas || []).map(norm));
  const comidaSet = new Set(cfg.familiaComida.map(norm));
  const barraSet = new Set(cfg.familiaBarra.map(norm));

  const prodByTipo = { comida: new Map(), barra: new Map() }; // nombre → {total, cant, local}
  const porLocal = new Map(); // local → {comida, barra}
  const sinClasificar = new Map(); // familia no mapeada → {total, filas}
  let totalComida = 0, totalBarra = 0, cantComida = 0, cantBarra = 0;
  // Desglose por mes calendario (p1=hace 2 meses, p2=mes pasado, p3=mes
  // actual — mismo índice que pyxisMesesLabels()/pyxisCervezasResumen). Se
  // suma acá, aditivo, para que el HOME de Comercial pueda leer "mes actual"
  // y "mes pasado" reales sin volver a bajar/clasificar la planilla de Pyxis.
  const mensualComida = [0, 0, 0], mensualBarra = [0, 0, 0];

  for (const r of rows) {
    const local = norm(r.nombreLocal);
    const marca = norm(r.nombreMarca);
    // Es nuestro si lo es el recinto entero O la marca dentro del recinto.
    if (!localesSet.has(local) && !marcasSet.has(marca)) continue;
    const fam = norm(r.familia);
    const tipo = comidaSet.has(fam) ? 'comida' : (barraSet.has(fam) ? 'barra' : null);
    const meses3 = [num(r.p1), num(r.p2), num(r.p3)];
    const total = meses3[0] + meses3[1] + meses3[2];
    const cant = num(r.q1) + num(r.q2) + num(r.q3);
    if (!tipo) {
      const s = sinClasificar.get(fam) || { total: 0, filas: 0 };
      s.total += total; s.filas++; sinClasificar.set(fam, s);
      continue;
    }
    const nombre = norm(r.nombreProducto) || '(sin nombre)';
    const key = nombre;
    const m = prodByTipo[tipo];
    const p = m.get(key) || { nombre, total: 0, cant: 0 };
    p.total += total; p.cant += cant; m.set(key, p);
    // Se identifica por marca + recinto: una marca nuestra puede estar en
    // varios recintos y un recinto puede tener más de una marca nuestra.
    const claveLocal = pyxisNombrePropio(local, marca);
    const lt = porLocal.get(claveLocal) || { comida: 0, barra: 0 };
    lt[tipo] += total; porLocal.set(claveLocal, lt);
    const mensualArr = tipo === 'comida' ? mensualComida : mensualBarra;
    for (let i = 0; i < 3; i++) mensualArr[i] += meses3[i];
    if (tipo === 'comida') { totalComida += total; cantComida += cant; }
    else { totalBarra += total; cantBarra += cant; }
  }

  const topOf = (m) => [...m.values()].map(p => ({ nombre: p.nombre, total: Math.round(p.total), cant: p.cant }))
    .sort((a, b) => b.total - a.total).slice(0, 10);

  return {
    available: true,
    grupo, meses: pyxisMesesLabels(), generadoEn: new Date().toISOString(),
    config: cfg, localesDisponibles, marcasDisponibles, familiasDisponibles,
    totales: {
      comida: Math.round(totalComida), barra: Math.round(totalBarra), cantComida, cantBarra, total: Math.round(totalComida + totalBarra),
      mensual: { comida: mensualComida.map(Math.round), barra: mensualBarra.map(Math.round) },
    },
    topComida: topOf(prodByTipo.comida), topBarra: topOf(prodByTipo.barra),
    porLocal: [...porLocal.entries()].map(([local, v]) => ({ local, comida: Math.round(v.comida), barra: Math.round(v.barra) })),
    sinClasificar: [...sinClasificar.entries()].map(([familia, v]) => ({ familia, total: Math.round(v.total), filas: v.filas })).sort((a, b) => b.total - a.total),
  };
}
