// ─────────────────────────────────────────────────────────────────────────────
// Pyxis · Documentos (facturas de compra de los locales HORECA)
// Sirve para ver a qué precio COMPRAN los locales las bebidas/licores de la
// competencia (ron, whisky, gin, cerveza…) y tener un precio de referencia.
// Los precios de la factura vienen SIN IVA ni ILA → calculamos el precio con
// impuestos: precio × (1 + IVA 0,19 + ILA según tipo de bebida).
// Endpoint (confirmado por captura):
//   GET /api/documentos/{grupo}?local=&page=&pick=&src=&ini=&end=
// ─────────────────────────────────────────────────────────────────────────────
const PYXIS_IVA = 0.19;
// ILA (Impuesto a las Bebidas Alcohólicas, Chile) por tipo. Editable si cambia la ley.
const PYXIS_ILA = { cerveza: 0.205, vino: 0.205, destilado: 0.31, analcoholico: 0.10, ninguno: 0 };
function pyxisTipoBebida(desc){
  const n = String(desc || '').toLowerCase();
  if (/(ron\b|whisk|\bgin\b|ginebra|vodka|vodk\b|pisco\b|tequil|tequi\b|aguardiente|licor|cognac|coñac|brandy|bacardi|absolut|jack\s*daniel|johnnie|chivas|jager|fernet|aperol|amaretto|grappa|singani|mezcal|cointreau|baileys|campari|vermut|vermouth|destilad|havana|flor\s*de\s*caña|barcel|capel|mistral|alto\s*del\s*carmen|tanqueray|beefeater|jose\s*cuervo|don\s*julio)/.test(n)) return 'destilado';
  if (/(vino|carmen|cabernet|merlot|sauvignon|syrah|carmenere|chardonnay|espumante|champ|malbec|pinot|moscato|\brose\b|sangiovese|tempranillo|reserva|gran\s*reserva|toro\s*de\s*piedra|casillero|santa\s*rita|concha\s*y\s*toro|requingua)/.test(n)) return 'vino';
  if (/(cerveza|lager|\bipa\b|schop|pilsen|stout|\bale\b|kunstmann|heineken|corona|stella|cusque|austral|quilmes|kross|becker|escudo|cristal|royal|sapporo|asahi|paulaner|erdinger)/.test(n)) return 'cerveza';
  if (/(bebida|gaseosa|jugo|agua\b|energetica|nectar|coca|sprite|fanta|schweppes|red\s*bull|monster|pepsi|canada\s*dry)/.test(n)) return 'analcoholico';
  return 'ninguno';
}
function pyxisPrecioConImp(precioSinImp, tipo){ const ila = PYXIS_ILA[tipo] != null ? PYXIS_ILA[tipo] : 0; return Math.round(Number(precioSinImp || 0) * (1 + PYXIS_IVA + ila) * 100) / 100; }
// Rango del mes en curso, sin zero-pad (formato de Pyxis: 2026-7-1).
function pyxisMesRango(){ const d = new Date(); const y = d.getUTCFullYear(), m = d.getUTCMonth() + 1; return { ini: y + '-' + m + '-1', end: y + '-' + m + '-' + d.getUTCDate() }; }
app.post('/admin/pyxis/documentos-diag', requireAdmin, async (req, res) => {
  try {
    const grupo = String((req.body && req.body.grupo) || 2).replace(/[^0-9]/g, '') || '2';
    const b = req.body || {}; const r0 = pyxisMesRango();
    const local = String(b.local || '244').replace(/[^0-9]/g, '') || '244';
    const ini = String(b.ini || r0.ini).replace(/[^0-9\-]/g, ''); const end = String(b.end || r0.end).replace(/[^0-9\-]/g, '');
    const out = { grupo, local, ini, end, probes: [] };
    const hit = async (path) => {
      try {
        const r = await pyxisApiGet(path); const ct = r.headers.get('content-type') || ''; let t = ''; try { t = await r.text(); } catch {}
        const isJson = /json/i.test(ct) || /^\s*[[{]/.test(t);
        let sketch = null; if (isJson) { try { const j = JSON.parse(t); sketch = pyxisSketch(j.body !== undefined ? j.body : j, 5); } catch {} }
        return { path, status: r.status, ct: ct.slice(0, 40), isJson, len: t.length, sketch, snippet: t.replace(/\s+/g, ' ').slice(0, 1800) };
      } catch (e) { return { path, error: String(e.message).slice(0, 90) }; }
    };
    out.probes.push(await hit(`/documentos/${grupo}?local=${local}&page=1&pick=15&ini=${ini}&end=${end}`));
    for (const p of [`/documentos/${grupo}/locales`, `/documentos/${grupo}/data-filters`, `/documentos/${grupo}/filters`, `/locales/${grupo}`, `/documentos/${grupo}`]) out.probes.push(await hit(p));
    // Parseo del array de documentos: encontrar la clave y un documento de ejemplo.
    try {
      const j = await pyxisApiJson(`/documentos/${grupo}?local=${local}&page=1&pick=15&ini=${ini}&end=${end}`);
      const b = j.body || {};
      out.bodyKeys = Object.keys(b);
      let docsKey = null, docs = null;
      for (const [k, v] of Object.entries(b)) { if (k === 'premises') continue; if (Array.isArray(v) && v.length && typeof v[0] === 'object') { docsKey = k; docs = v; break; } }
      out.lista = { docsKey, count: docs ? docs.length : 0, sampleDoc: docs ? docs[0] : null, camposDoc: docs && docs[0] ? Object.keys(docs[0]) : [], pagination: b.paginationData || null, premisesCount: Array.isArray(b.premises) ? b.premises.length : 0 };
    } catch (e) { out.lista = { error: String(e.message).slice(0, 100) }; }
    res.json(out);
  } catch (e) { res.status(500).json({ error: String(e.message || e).slice(0, 200) }); }
});
// tipoDte (SII): 33 Factura, 34 Factura exenta, 61 Nota de crédito, 56 Nota de débito.
function pyxisTipoDte(t){ const m = { 33: 'Factura', 34: 'Factura exenta', 39: 'Boleta', 46: 'Factura de compra', 52: 'Guía de despacho', 56: 'Nota de débito', 61: 'Nota de crédito' }; return m[t] || ('DTE ' + t); }
// Lista de documentos (facturas de compra) de un local, filtrable a Bebidas/Licores.
async function pyxisDocumentosLista(grupo, q){
  q = q || {}; const r0 = pyxisMesRango();
  const local = String(q.local || '').replace(/[^0-9]/g, '');
  const ini = String(q.ini || r0.ini).replace(/[^0-9\-]/g, ''); const end = String(q.end || r0.end).replace(/[^0-9\-]/g, '');
  const page = Math.max(1, parseInt(q.page) || 1); const pick = Math.min(300, Math.max(1, parseInt(q.pick) || 100));
  const src = String(q.src || '').trim().slice(0, 60);
  const dz = s => String(s).replace(/-0(\d)/g, '-$1'); // 2026-07-01 → 2026-7-1 (formato Pyxis)
  let path = '/documentos/' + grupo + '?local=' + local + '&page=' + page + '&pick=' + pick + '&ini=' + dz(ini) + '&end=' + dz(end);
  if (src) path += '&src=' + encodeURIComponent(src);
  const j = await pyxisApiJson(path); const b = j.body || {};
  const locales = (b.premises || []).map(p => ({ id: p.id, nombre: p.nombreLocal })).sort((a, c) => String(a.nombre).localeCompare(String(c.nombre)));
  let data = (b.paginationData && b.paginationData.data) || [];
  const fam = String(q.familia || 'bl');
  if (fam === 'bl') data = data.filter(d => /bebida|licor/i.test(String(d.nombreCuenta || '')));
  else if (fam && fam !== 'todos') data = data.filter(d => new RegExp(fam, 'i').test(String(d.nombreCuenta || '')));
  const docs = data.map(d => ({ folio: d.folio, proveedor: d.nombreProveedor, rut: d.rutProveedor, fecha: d.fechaFactura, tipo: pyxisTipoDte(d.tipoDte), tipoDte: d.tipoDte, familia: d.nombreCuenta, categoria: d.nombreCategoria, total: d.total, usuario: String(d.userIdte || '').trim() }));
  const pg = b.paginationData || {};
  return { grupo, local, ini, end, src, familia: fam, locales, docs, pagination: { total: pg.total, totalPages: pg.totalPages, currentPage: pg.currentPage, pick: pg.pick, remains: pg.remains } };
}
app.get('/admin/pyxis/documentos', requireAdmin, async (req, res) => {
  try { const grupo = String(req.query.grupo || 2).replace(/[^0-9]/g, '') || '2'; res.json(await pyxisDocumentosLista(grupo, req.query)); }
  catch (e) { res.status(500).json({ error: String(e.message || e).slice(0, 200) }); }
});
// Baja el PDF de la factura desde Pyxis (con el Bearer). Devuelve un Buffer.
async function pyxisFacturaPdf(grupo, local, folio, rut){
  const { api, web } = pyxisCreds(); const a = await pyxisAuth();
  const url = api + '/documentos/pdf/grupo/' + grupo + '/local/' + local + '/folio/' + folio + '/rut/' + encodeURIComponent(rut);
  const r = await pyxisFetch(url, { method: 'GET', headers: { 'Accept': 'application/pdf', 'Referer': web + '/', 'Origin': web } }, { ...a.jar }, a.token);
  if (r.status !== 200) throw new Error('La factura respondió ' + r.status + '.');
  return Buffer.from(await r.arrayBuffer());
}
// Analiza una factura: baja el PDF, se lo pasa a Claude para extraer las líneas, y
// calcula el precio con IVA + ILA por producto. Cachea por folio (no re-analiza).
const PYXIS_FACT_FILE = join(PROMPTS_EFFECTIVE_DIR, 'pyxis-facturas.json');
function pyxisFactLoad(){ try { if (existsSync(PYXIS_FACT_FILE)) return JSON.parse(readFileSync(PYXIS_FACT_FILE, 'utf-8')); } catch (e) { console.warn('pyxis fact:', e.message); } return {}; }
function pyxisFactSave(o){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(PYXIS_FACT_FILE, JSON.stringify(o, null, 2)); }
// Determina el tipo de bebida por el nombre; si no matchea, usa la familia del
// documento (Licores→destilado, Vinos→vino, Cerveza→cerveza, Bebidas→analcohólico).
function pyxisFactLineaImp(l, familiaDoc){
  let tipo = pyxisTipoBebida(l.descripcion);
  if (tipo === 'ninguno') { const f = String(familiaDoc || '').toLowerCase();
    if (/licor|destil/.test(f)) tipo = 'destilado';
    else if (/vino/.test(f)) tipo = 'vino';
    else if (/cerveza/.test(f)) tipo = 'cerveza';
    else if (/bebida/.test(f)) tipo = 'analcoholico';
  }
  const ila = PYXIS_ILA[tipo] != null ? PYXIS_ILA[tipo] : 0;
  return { ...l, tipo, ilaPct: Math.round(ila * 1000) / 10, impPct: Math.round((PYXIS_IVA + ila) * 1000) / 10, precioConImp: tipo === 'ninguno' ? 0 : pyxisPrecioConImp(l.precioUnit, tipo) };
}
// Baja el PDF, se lo pasa a Claude y CACHEA la extracción CRUDA (sin impuestos, para
// recalcular el ILA si cambia la clasificación). Devuelve {proveedor, fecha, lineas:[…]}.
async function pyxisFacturaRaw(grupo, local, folio, rut, force){
  const cache = pyxisFactLoad(); const key = grupo + '_' + local + '_' + folio + '_' + rut;
  if (!force && cache[key] && cache[key].lineas) return cache[key];
  const pdf = await pyxisFacturaPdf(grupo, local, folio, rut);
  const sys = 'Sos un extractor de datos de facturas chilenas (SII). Te paso una factura de COMPRA en PDF. Devolvé SOLO un JSON válido, sin texto ni markdown alrededor, con esta forma exacta: {"proveedor":"","rut":"","folio":0,"fecha":"YYYY-MM-DD","neto":0,"iva":0,"total":0,"lineas":[{"codigo":"","descripcion":"","cantidad":0,"precioUnit":0,"descuento":0,"valor":0}]}. Reglas: montos ENTEROS en pesos chilenos, sin puntos ni símbolos; precioUnit y valor son los que figuran en la factura (SIN IVA ni ILA); en descripcion transcribí el nombre COMPLETO del producto tal como aparece; extraé TODAS las líneas de detalle en orden; si un campo no aparece, poné 0 o cadena vacía. No inventes valores: transcribí exactamente lo que dice el PDF.';
  const msg = await client.messages.create({ model: 'claude-sonnet-4-6', max_tokens: 3000, system: sys, messages: [{ role: 'user', content: [{ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: pdf.toString('base64') } }, { type: 'text', text: 'Extraé esta factura al JSON pedido.' }] }] });
  const txt = (msg.content || []).filter(c => c.type === 'text').map(c => c.text).join('').trim();
  let data; try { data = JSON.parse(txt.replace(/^```(?:json)?\s*|\s*```$/g, '')); } catch (e) { throw new Error('No pude leer la factura (la IA no devolvió JSON válido).'); }
  const out = { grupo, local, folio: data.folio || Number(folio) || folio, rut: data.rut || rut, proveedor: data.proveedor || '', fecha: data.fecha || '', neto: data.neto || 0, iva: data.iva || 0, total: data.total || 0, lineas: (data.lineas || []).map(l => ({ codigo: l.codigo || '', descripcion: l.descripcion || '', cantidad: Number(l.cantidad) || 0, precioUnit: Number(l.precioUnit) || 0, descuento: Number(l.descuento) || 0, valor: Number(l.valor) || 0 })), analizadoEn: new Date().toISOString() };
  cache[key] = out; pyxisFactSave(cache);
  return out;
}
// Añade tipo de bebida + precio con IVA+ILA a cada línea (usando la familia del doc).
function pyxisFacturaConImp(raw, familia){ return { ...raw, familia: familia || '', lineas: (raw.lineas || []).map(l => pyxisFactLineaImp(l, familia)) }; }
app.post('/admin/pyxis/documentos/factura', requireAdmin, async (req, res) => {
  try {
    const b = req.body || {}; const grupo = String(b.grupo || 2).replace(/[^0-9]/g, '') || '2';
    const local = String(b.local || '').replace(/[^0-9]/g, ''); const folio = String(b.folio || '').replace(/[^0-9]/g, ''); const rut = String(b.rut || '').replace(/[^0-9kK.\-]/g, '');
    if (!local || !folio || !rut) return res.status(400).json({ error: 'Faltan local, folio o RUT.' });
    const raw = await pyxisFacturaRaw(grupo, local, folio, rut, !!b.force);
    res.json(pyxisFacturaConImp(raw, b.familia || ''));
  } catch (e) { res.status(500).json({ error: String(e.message || e).slice(0, 200) }); }
});
// Precio de referencia: analiza las facturas visibles y agrega por producto el precio
// de compra (sin imp) y el precio con IVA + ILA — para fijar precio de venta.
app.post('/admin/pyxis/documentos/referencia', requireAdmin, async (req, res) => {
  try {
    const b = req.body || {}; const grupo = String(b.grupo || 2).replace(/[^0-9]/g, '') || '2';
    const lista = await pyxisDocumentosLista(grupo, b);
    const facturas = lista.docs.filter(d => d.tipoDte === 33 || d.tipoDte === 34).slice(0, 20); // solo facturas, cap 20
    const prod = new Map(); const errores = [];
    for (const d of facturas) {
      try {
        const raw = await pyxisFacturaRaw(grupo, lista.local, String(d.folio), d.rut, false);
        const f = pyxisFacturaConImp(raw, d.familia);
        for (const l of f.lineas) {
          if (l.tipo === 'ninguno') continue; // solo bebidas/licores/cervezas/vinos
          const kk = String(l.descripcion || '').trim().toLowerCase(); if (!kk) continue;
          let p = prod.get(kk);
          if (!p) { p = { descripcion: l.descripcion, tipo: l.tipo, impPct: l.impPct, precios: [], preciosImp: [], veces: 0, unidades: 0, proveedores: new Set() }; prod.set(kk, p); }
          if (l.precioUnit > 0) { p.precios.push(l.precioUnit); p.preciosImp.push(l.precioConImp); }
          p.veces++; p.unidades += Number(l.cantidad) || 0; if (f.proveedor) p.proveedores.add(f.proveedor);
        }
      } catch (e) { errores.push({ folio: d.folio, error: String(e.message).slice(0, 80) }); }
    }
    const prom = a => a.length ? Math.round(a.reduce((s, x) => s + x, 0) / a.length) : 0;
    const items = [...prod.values()].map(p => ({ descripcion: p.descripcion, tipo: p.tipo, impPct: p.impPct, veces: p.veces, unidades: p.unidades, proveedores: [...p.proveedores].slice(0, 3), precioMin: p.precios.length ? Math.min(...p.precios) : 0, precioMax: p.precios.length ? Math.max(...p.precios) : 0, precioProm: prom(p.precios), precioConImpProm: prom(p.preciosImp) })).sort((a, c) => c.precioConImpProm - a.precioConImpProm);
    res.json({ grupo, local: lista.local, ini: lista.ini, end: lista.end, facturasAnalizadas: facturas.length, items, errores });
  } catch (e) { res.status(500).json({ error: String(e.message || e).slice(0, 200) }); }
});

// Crear lote (cocción). Ocupa el tanque destino recién al cerrar la cocción.
app.post('/admin/produccion/lote', requireAdmin, (req, res) => {
  const b = req.body || {}; const d = prodLoad();
  const codigo = prodStr(b.codigo, 40);
  if (!codigo) return res.status(400).json({ error: 'Ingresá el código del lote.' });
  const tanqueId = prodStr(b.tanqueId, 10);
  const tanque = d.tanques.find(t => t.id === tanqueId);
  if (tanqueId && !tanque) return res.status(400).json({ error: 'Tanque inválido.' });
  // D · enlace con receta: si se elige una, pre-rellena estilo/producto/volumen esperado.
  const recetaId = prodStr(b.recetaId, 40);
  const receta = recetaId ? (d.recetas || []).find(r => r.id === recetaId) : null;
  const lote = {
    id: prodNewId('lote'), codigo, recetaId: receta ? receta.id : '',
    producto: prodStr(b.producto, 80) || (receta ? receta.nombre : ''), estilo: prodStr(b.estilo, 60) || (receta ? receta.estilo : ''), familia: prodStr(b.familia, 40),
    tanqueId: tanqueId || '', nBatches: Math.max(1, Math.min(3, prodNum(b.nBatches) || 1)),
    volumenEsperadoL: prodNum(b.volumenEsperadoL) || (receta ? prodNum(receta.litros) : 0), volumenRealL: 0,
    fechaCoccion: prodTs(b.fechaCoccion) || new Date().toISOString(), fechaFermInicio: null, fechaMadInicio: null, fechaEnvasado: null,
    estado: 'coccion', viabilidadLevaduraPct: null,
    etapas: PROD_ETAPAS.map(nombre => ({ nombre, inicio: null, fin: null, editadoManual: false })),
    envasados: [], notas: prodStr(b.notas, 300),
  };
  d.lotes.push(lote); prodSave(d); res.json({ ok: true, lote });
});
// Actualizar lote (etapas, fechas, estado, volumen, notas). El front manda el lote completo.
app.put('/admin/produccion/lote/:id', requireAdmin, (req, res) => {
  const d = prodLoad(); const idx = d.lotes.findIndex(l => l.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Lote no encontrado.' });
  const cur = d.lotes[idx]; const b = req.body || {};
  const merged = { ...cur };
  ['codigo', 'producto', 'estilo', 'familia', 'notas'].forEach(k => { if (b[k] != null) merged[k] = prodStr(b[k], 80); });
  if (b.recetaId != null) merged.recetaId = prodStr(b.recetaId, 40);
  if (b.tanqueId != null) merged.tanqueId = prodStr(b.tanqueId, 10);
  if (b.nBatches != null) merged.nBatches = Math.max(1, Math.min(3, prodNum(b.nBatches)));
  if (b.volumenEsperadoL != null) merged.volumenEsperadoL = prodNum(b.volumenEsperadoL);
  if (b.volumenRealL != null) merged.volumenRealL = prodNum(b.volumenRealL);
  ['fechaCoccion', 'fechaFermInicio', 'fechaMadInicio', 'fechaEnvasado'].forEach(k => { if (b[k] !== undefined) merged[k] = prodTs(b[k]); });
  if (b.estado != null) merged.estado = prodStr(b.estado, 20);
  if (b.viabilidadLevaduraPct != null) merged.viabilidadLevaduraPct = prodNum(b.viabilidadLevaduraPct);
  if (Array.isArray(b.etapas)) merged.etapas = b.etapas.map((e, i) => ({ nombre: prodStr(e.nombre, 40) || (PROD_ETAPAS[i] || 'Etapa'), inicio: prodTs(e.inicio), fin: prodTs(e.fin), editadoManual: !!e.editadoManual }));
  if (Array.isArray(b.envasados)) merged.envasados = b.envasados.map(ev => {
    // Compat: líneas viejas traían `canal` barril|lata → mapear a formato.
    const formato = PROD_FORMATOS.includes(ev.formato) ? ev.formato : (ev.canal === 'lata' ? 'lata' : 'barril20');
    return {
      id: ev.id || prodNewId('env'), formato, inicio: prodTs(ev.inicio), fin: prodTs(ev.fin),
      litrosBuenos: prodNum(ev.litrosBuenos), litrosRechazados: prodNum(ev.litrosRechazados), unidades: prodNum(ev.unidades),
      latasNivelBajo: prodNum(ev.latasNivelBajo), mermaTapas: prodNum(ev.mermaTapas), editadoManual: !!ev.editadoManual,
    };
  });
  // C · Validación: la suma envasada (buenos + rechazados de todas las líneas) no
  // puede superar el volumen del lote. El resto queda en el tanque (envasado parcial).
  {
    const base = prodVolumenBase(merged);
    const sum = (merged.envasados || []).reduce((a, ev) => a + prodNum(ev.litrosBuenos) + prodNum(ev.litrosRechazados), 0);
    if (base > 0 && sum > base + 0.5) return res.status(400).json({ error: `Los litros envasados (${Math.round(sum)} L) superan el volumen del lote (${Math.round(base)} L). Ajustá las líneas.` });
  }
  d.lotes[idx] = merged;
  // El tanque queda "Sucio" recién al CERRAR el envasado (vaciado → fechaEnvasado).
  // Mientras se envasa de a poco sigue "Ocupado" (queda cerveza adentro).
  if (merged.fechaEnvasado && !cur.fechaEnvasado && merged.tanqueId) { const t = d.tanques.find(x => x.id === merged.tanqueId); if (t) t.sucio = true; }
  prodSyncTanques(d);
  prodSave(d); res.json({ ok: true, lote: merged });
});
app.delete('/admin/produccion/lote/:id', requireAdmin, (req, res) => {
  const d = prodLoad(); const n = d.lotes.length; d.lotes = d.lotes.filter(l => l.id !== req.params.id);
  if (d.lotes.length === n) return res.status(404).json({ error: 'Lote no encontrado.' });
  prodSyncTanques(d); prodSave(d); res.json({ ok: true });
});
// Recalcula qué tanque ocupa cada lote: ocupado si el lote está en ferm/mad/listo
// (no envasado). Un lote envasado deja el tanque "sucio" hasta que se registre su CIP.
function prodSyncTanques(d){
  d.tanques.forEach(t => { t.loteActualId = null; });
  for (const l of d.lotes) {
    if (!l.tanqueId) continue;
    const t = d.tanques.find(x => x.id === l.tanqueId); if (!t) continue;
    // Un lote ocupa el tanque en ferm/mad/listo, y también mientras se envasa de a
    // poco (estado 'envasado' sin cierre): queda cerveza adentro hasta vaciarse.
    const drenado = l.fechaEnvasado != null; // envasado cerrado = tanque vaciado
    const ocupa = ['fermentacion', 'maduracion', 'listo'].includes(l.estado) || (l.estado === 'envasado' && !drenado);
    if (ocupa && !t.loteActualId) t.loteActualId = l.id;
  }
  // El flag t.sucio es persistente: se prende al cerrar el envasado y se apaga con el CIP.
  d.tanques.forEach(t => { t.estado = t.loteActualId ? 'ocupado' : (t.sucio ? 'sucio' : 'vacio'); });
}
