function normalizeTitle(s){
  return String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^\w]+/g,' ').trim();
}

app.post('/admin/tutoriales/seed', requireAdmin, (_req, res) => {
  try {
    const all = loadTutorials();
    const existingTitles = new Set(all.map(t => normalizeTitle(t.title)));
    let added = 0;
    for (const t of DEFAULT_TUTORIALS) {
      if (existingTitles.has(normalizeTitle(t.title))) continue;
      all.push({
        id: randomUUID(),
        title: t.title,
        videoUrl: '',
        keywords: t.keywords,
        description: t.description,
        scope: t.scope,
        createdAt: new Date().toISOString(),
        seeded: true,
      });
      added++;
    }
    saveTutorials(all);
    res.json({ ok: true, added, total: all.length });
  } catch (e) {
    res.status(500).json({ error: 'Error sembrando: ' + e.message });
  }
});

// ─── Analítica (dashboard interno) ──────────────────────────────────────────
// Lee logs/conversations.json + cache Shopify y devuelve métricas para el tab
// "Analítica" del panel. Todo calculado on-the-fly — el dataset es chico.

function rangeFor(rangeId){
  const now = Date.now();
  const dayStart = new Date(); dayStart.setHours(0,0,0,0);
  if (rangeId === 'today') return { id:'today', label:'hoy',                 from: dayStart.getTime(), to: now };
  if (rangeId === '7d')    return { id:'7d',    label:'últimos 7 días',      from: now - 7*86400e3,  to: now };
  if (rangeId === '30d')   return { id:'30d',   label:'últimos 30 días',     from: now - 30*86400e3, to: now };
  if (rangeId === '90d')   return { id:'90d',   label:'últimos 90 días',     from: now - 90*86400e3, to: now };
  if (rangeId === 'year')  return { id:'year',  label:'último año',          from: now - 365*86400e3, to: now };
  return                          { id:'all',   label:'todo el histórico',   from: 0, to: now };
}

const ANALYTICS_TOPICS = [
  { id:'asado',     label:'asado / parrilla',   rx: /\b(asado|parrilla|parril|costill|carnes?)\b/i },
  { id:'regalo',    label:'regalo',             rx: /\b(regalo|present|cumple|aniversario)\b/i },
  { id:'verano',    label:'verano / patio',     rx: /\b(verano|piscina|playa|patio|terraza)\b/i },
  { id:'previa',    label:'previa / carrete',   rx: /\b(previa|carrete|juntad?a|reuni[oó]n)\b/i },
  { id:'sin_alc',   label:'sin alcohol',        rx: /sin\s+alcoh|0[\s.]*0|cero\s+alcoh/i },
  { id:'precio',    label:'precio',             rx: /\b(precio|cu[aá]nto\s+(cuesta|sale|vale|es)|valor|barat[oa]|car[oa])\b/i },
  { id:'pack',      label:'packs / cajas',      rx: /\b(pack|6[\s-]*pack|12[\s-]*pack|24[\s-]*pack|caja|cajas)\b/i },
  { id:'maridaje',  label:'maridaje / con qué', rx: /\b(marida|acompa[ñn]|combina|va\s+bien|que\s+tomar\s+con)/i },
  { id:'envio',     label:'envío / despacho',   rx: /\b(env[ií]o|despacho|domicilio|retir[oa]|llega(r|me|n)?)\b/i },
  { id:'recomenda', label:'recomendación',      rx: /\b(recomien|recomenda|sugier|sugerencia|qu[eé]\s+me\s+recomienda)/i },
  { id:'cerveza',   label:'cervezas en general',rx: /\b(cerveza|cheve|chela|chelita|chop|schop)\b/i },
  { id:'chelada',   label:'cheladas',           rx: /\b(chelada|cheladas)\b/i },
  { id:'gin',       label:'gin / cócteles',     rx: /\b(gin|tonic|c[oó]ctel|coctel|mojito|negroni|c[ií]tric)\b/i },
  { id:'whisky',    label:'whisky',             rx: /\b(whisk(e)?y|whisky|bourbon)\b/i },
  { id:'mayorista', label:'mayorista / B2B',    rx: /\b(mayorista|por\s+volumen|por\s+mayor|botiller[ií]a|restaurant?e|bar\s+|local|barril)\b/i },
];

app.get('/admin/analytics', requireAdmin, async (req, res) => {
  try {
    const r = rangeFor(String(req.query.range || '30d'));
    const all = Array.isArray(readLog(CONV_LOG)) ? readLog(CONV_LOG) : [];

    const tOf = c => new Date(c.endTime || c.startTime || 0).getTime();
    const subset = all.filter(c => {
      const t = tOf(c);
      return t >= r.from && t <= r.to;
    });

    // Globales (no afectados por rango — sirven para los chips de cabecera)
    const now = Date.now();
    const startOfToday = new Date(); startOfToday.setHours(0,0,0,0);
    const counts = {
      all:    all.length,
      today:  all.filter(c => tOf(c) >= startOfToday.getTime()).length,
      last7:  all.filter(c => now - tOf(c) <= 7*86400e3).length,
      last30: all.filter(c => now - tOf(c) <= 30*86400e3).length,
    };

    const withIntent   = subset.filter(c => c.purchaseIntent).length;
    const withProducts = subset.filter(c => Array.isArray(c.recommendedProducts) && c.recommendedProducts.length).length;
    const b2c = subset.filter(c => !c.isB2B).length;
    const b2b = subset.filter(c =>  c.isB2B).length;
    const intentRate = subset.length ? Math.round(withIntent / subset.length * 1000) / 10 : 0;
    const totalMessages = subset.reduce((s,c) => s + (Array.isArray(c.messages) ? c.messages.length : 0), 0);
    const avgMessages = subset.length ? Math.round(totalMessages / subset.length * 10) / 10 : 0;
    const totalDuration = subset.reduce((s,c) => s + (Number(c.duration) || 0), 0);
    const avgDuration = subset.length ? Math.round(totalDuration / subset.length) : 0;

    // Distribución por marca: recomputo topBrand desde los mensajes para que
    // las conversaciones viejas (con topBrand mal calculado) queden bien.
    // 5 buckets posibles: las 3 marcas + "Mixto" (varias marcas con peso
    // parejo) + "Sin marca" (ninguna marca mencionada).
    const brandCounts = { 'Kairos Brewing':0, 'Firulais':0, 'Banny':0, 'Mixto':0, 'Sin marca':0 };
    for (const c of subset) {
      const b = effectiveTopBrand(c);
      if (b === 'Mixto')                      brandCounts['Mixto']++;
      else if (b && brandCounts[b] != null)   brandCounts[b]++;
      else                                    brandCounts['Sin marca']++;
    }
    const brandTotal = Object.values(brandCounts).reduce((a,b)=>a+b,0);
    const brandDistribution = Object.entries(brandCounts)
      .map(([brand,count]) => ({ brand, count, pct: brandTotal ? Math.round(count/brandTotal*1000)/10 : 0 }))
      .filter(b => b.count > 0)
      .sort((a,b) => b.count - a.count);
    // "Marca top" para el stat card: solo si una de las 3 marcas reales
    // domina; si es Mixto o Sin marca el ganador, lo mostramos como tal.
    const topBrand = brandDistribution[0]?.count ? brandDistribution[0].brand : '—';

    // Distribución por origen (from)
    const fromMap = {};
    for (const c of subset) {
      const k = c.from || 'zorbot';
      fromMap[k] = (fromMap[k] || 0) + 1;
    }
    const fromDistribution = Object.entries(fromMap)
      .map(([from,count]) => ({ from, count }))
      .sort((a,b) => b.count - a.count);

    // Serie diaria: cubre todo el rango con días vacíos = 0
    const days = Math.min(120, Math.max(1, Math.ceil((r.to - r.from) / 86400e3)));
    const byDayMap = new Map();
    for (let i = days - 1; i >= 0; i--) {
      const d = new Date(r.to - i * 86400e3);
      d.setHours(0,0,0,0);
      byDayMap.set(d.toISOString().slice(0,10), { date: d.toISOString().slice(0,10), total: 0, withIntent: 0 });
    }
    for (const c of subset) {
      const t = new Date(tOf(c));
      if (!isFinite(t)) continue;
      const key = t.toISOString().slice(0,10);
      if (!byDayMap.has(key)) byDayMap.set(key, { date: key, total: 0, withIntent: 0 });
      const e = byDayMap.get(key);
      e.total++;
      if (c.purchaseIntent) e.withIntent++;
    }
    const byDay = [...byDayMap.values()].sort((a,b) => a.date.localeCompare(b.date));

    // Top productos recomendados por Zorbot
    const prodCounts = new Map();
    for (const c of subset) {
      for (const p of (c.recommendedProducts || [])) {
        if (!p) continue;
        prodCounts.set(p, (prodCounts.get(p) || 0) + 1);
      }
    }
    const topProducts = [...prodCounts.entries()]
      .map(([name,count]) => ({ name, count }))
      .sort((a,b) => b.count - a.count)
      .slice(0, 10);

    // Distribución por hora / día de la semana (en el rango)
    const hourly  = Array.from({length:24}, (_,h) => ({ hour: h,  count: 0 }));
    const weekday = Array.from({length:7},  (_,d) => ({ day:  d,  count: 0 }));
    for (const c of subset) {
      const t = new Date(c.startTime || c.endTime || 0);
      if (!isFinite(t)) continue;
      hourly[t.getHours()].count++;
      weekday[t.getDay()].count++;
    }

    // Topics: matchea regex sobre primer mensaje del usuario
    const topicMap = ANALYTICS_TOPICS.map(t => ({ ...t, count: 0, samples: [] }));
    for (const c of subset) {
      const firstUser = (c.messages || []).find(m => m.role === 'user');
      const txt = String(firstUser?.content || '');
      if (!txt) continue;
      for (const t of topicMap) {
        if (t.rx.test(txt)) {
          t.count++;
          if (t.samples.length < 3) t.samples.push(txt.replace(/\s+/g,' ').trim().slice(0,140));
        }
      }
    }
    const topics = topicMap
      .filter(t => t.count > 0)
      .map(({ id, label, count, samples }) => ({ id, label, count, samples }))
      .sort((a,b) => b.count - a.count);

    // Oportunidades: productos preguntados por usuarios pero poco recomendados
    let underutilized = [];
    try {
      const cache = await loadProductsCache(false);
      if (Array.isArray(cache)) {
        const products = cache
          .map(p => ({ id: String(p.id), title: String(p.title || '').trim() }))
          .filter(p => p.title.length > 3);
        const askMap = new Map();
        for (const c of subset) {
          for (const m of (c.messages || [])) {
            if (m.role !== 'user') continue;
            const txt = String(m.content || '').toLowerCase();
            if (!txt) continue;
            for (const p of products) {
              const needle = p.title.toLowerCase();
              if (needle.length > 3 && txt.includes(needle)) {
                askMap.set(p.title, (askMap.get(p.title) || 0) + 1);
              }
            }
          }
        }
        underutilized = [...askMap.entries()]
          .map(([name, asked]) => {
            const rec = prodCounts.get(name) || 0;
            return { name, asked, recommended: rec, gap: asked - rec };
          })
          .filter(x => x.asked >= 2 && x.gap >= 1)
          .sort((a,b) => b.gap - a.gap)
          .slice(0, 8);
      }
    } catch (e) { /* opcional, ignorar */ }

    res.json({
      range: r,
      counts,
      totals: {
        conversations: subset.length,
        withIntent, withProducts, b2c, b2b,
        intentRate, avgMessages, avgDuration, topBrand,
      },
      byDay,
      topProducts,
      brandDistribution,
      fromDistribution,
      hourly, weekday,
      topics,
      underutilized,
    });
  } catch (e) {
    res.status(500).json({ error: 'Error generando analítica: ' + e.message });
  }
});

// ─── Analítica de VENTAS mayoristas (Shopify orders) ────────────────────────
// SOLO productos con tag MAYORISTA. Requiere read_orders.
const isMayoristaLine = (li) => (li.tags || []).map(t => String(t).toUpperCase()).includes('MAYORISTA');

// Diagnóstico: qué scopes tiene REALMENTE el token actual de Shopify.
app.get('/admin/shopify/scopes', requireAdmin, async (_req, res) => {
  if (!process.env.SHOPIFY_ADMIN_TOKEN || !process.env.SHOPIFY_STORE_DOMAIN) {
    return res.json({ ok:false, reason:'Falta SHOPIFY_ADMIN_TOKEN o SHOPIFY_STORE_DOMAIN.' });
  }
  try {
    const r = await shopifyAdminFetch('/oauth/access_scopes.json');
    const granted = (r.access_scopes || []).map(s => s.handle);
    res.json({
      ok: true,
      shop: process.env.SHOPIFY_STORE_DOMAIN,
      granted,
      hasReadOrders:    granted.includes('read_orders'),
      hasReadCustomers: granted.includes('read_customers'),
    });
  } catch (e) {
    res.json({ ok:false, reason: String(e.message || e).slice(0, 300) });
  }
});

// Crecimiento mes vs mes anterior por producto. Guarda las DOS métricas (plata y
// litros) y el desglose por canal, para poder leer "subió Golden, ¿pero por fuera
// de nuestros propios locales?". Devuelve TODOS los productos, no un top: el
// buscador y el filtro de canal viven en el front, así se puede ir a buscar uno
// puntual que no entraría en un top 10. El % lo calcula el front según la métrica
// y el canal elegidos. Función pura para poder correrla con datos de prueba.
const ANALYTICS_GROWTH_CANALES = ['horeca', 'retail', 'hospitality', 'sin_canal'];
function analyticsCrecimientoPorProducto(orders, { thisM, thisY, prevM, prevY, extras, notes, estiloPorCodigo, litrosDeLinea }){
  const celda = () => ({ curPlata: 0, prevPlata: 0, curLitros: 0, prevLitros: 0 });
  const porProducto = new Map(); // title → { name, skuCode, estilo, total, canales }
  for (const o of orders) {
    const d = new Date(o.createdAt);
    const inCur  = d.getMonth()===thisM && d.getFullYear()===thisY;
    const inPrev = d.getMonth()===prevM && d.getFullYear()===prevY;
    if (!inCur && !inPrev) continue;
    for (const li of (o.lineItems||[]).filter(isMayoristaLine)) {
      if (!porProducto.has(li.title)) {
        const ex = li.productId ? extras.items[String(li.productId)] : null;
        porProducto.set(li.title, {
          name: li.title, skuCode: ex?.skuCode || null, estilo: sellinEstiloDeProducto(ex, estiloPorCodigo),
          total: celda(), canales: Object.fromEntries(ANALYTICS_GROWTH_CANALES.map(c => [c, celda()])),
        });
      }
      const g = porProducto.get(li.title);
      const canal = canalDeCliente(o.customerId, notes) || canalDeProductoSellin(li.productId, extras) || 'sin_canal';
      const litros = litrosDeLinea(li) || 0;
      for (const cel of [g.total, g.canales[canal]]) {
        if (inCur) { cel.curPlata += li.amount; cel.curLitros += litros; }
        else { cel.prevPlata += li.amount; cel.prevLitros += litros; }
      }
    }
  }
  const redondear = (c) => ({
    curPlata: Math.round(c.curPlata), prevPlata: Math.round(c.prevPlata),
    curLitros: Math.round(c.curLitros * 10) / 10, prevLitros: Math.round(c.prevLitros * 10) / 10,
  });
  return [...porProducto.values()]
    .map(g => ({ ...g, total: redondear(g.total), canales: Object.fromEntries(ANALYTICS_GROWTH_CANALES.map(c => [c, redondear(g.canales[c])])) }))
    .filter(g => g.total.curPlata || g.total.prevPlata || g.total.curLitros || g.total.prevLitros)
    .sort((a,b)=> (b.total.curPlata - b.total.prevPlata) - (a.total.curPlata - a.total.prevPlata));
}
app.get('/admin/analytics/sales', requireAdmin, async (req, res) => {  const r = rangeFor(String(req.query.range || '30d'));
  const result = await loadOrders(String(req.query.refresh || '') === '1');
  if (!result.available) {
    return res.json({ available: false, reason: result.reason, range: r });
  }
  try {
    const orders = result.orders.filter(o => {
      const t = new Date(o.createdAt).getTime();
      return t >= r.from && t <= r.to;
    });

    // Atribución de canal y conversión a litros: MISMAS funciones que Sell In
    // (canalDeCliente/canalDeProductoSellin, sellinFormatoLabel/skuFormatoLitros),
    // no un cálculo paralelo.
    const extras = loadProductExtras();
    const notes = loadCustomerNotes();
    const dicc = skuDiccLoad();
    const estiloPorCodigo = new Map((dicc.estilos || []).map(e => [String(e.codigo), e.nombre]));
    const litrosDeLinea = (li) => {
      const label = sellinFormatoLabel(li, extras);
      const lu = label != null ? skuFormatoLitros(label) : null;
      return lu != null ? Math.round(lu * li.qty * 1000) / 1000 : null; // null = formato sin equivalencia
    };

    // Solo líneas de productos mayoristas
    const moneyByProduct = new Map();   // title → $
    // Volumen por producto: litros despachados, que es la unidad con la que se
    // repone. Las unidades se siguen contando aparte para poder decir qué parte
    // del volumen no se pudo convertir (formatos sin litros cargados).
    const volByProduct = new Map();     // title → { litros, unidades, sinDatoQty }
    let mayoOrderCount = 0, mayoRevenue = 0, volSinDatoQty = 0, volUnidades = 0;
    const comboCounts = new Map();      // "A|||B" → veces
    const dayOfMonth = {};              // 1..31 → { sum, count(días distintos) }
    const heat = Array.from({length:7}, () => Array(24).fill(0)); // [weekday][hour] = $
    const seenDates = {};               // para contar días distintos por day-of-month

    for (const o of orders) {
      const mayoLines = (o.lineItems || []).filter(isMayoristaLine);
      if (!mayoLines.length) continue;
      mayoOrderCount++;
      let orderMayoTotal = 0;
      const titlesInOrder = new Set();
      for (const li of mayoLines) {
        moneyByProduct.set(li.title, (moneyByProduct.get(li.title) || 0) + li.amount);
        const litros = litrosDeLinea(li);
        if (!volByProduct.has(li.title)) volByProduct.set(li.title, { litros: 0, unidades: 0, sinDatoQty: 0 });
        const v = volByProduct.get(li.title);
        v.litros += litros || 0; v.unidades += li.qty;
        if (litros == null) { v.sinDatoQty += li.qty; volSinDatoQty += li.qty; }
        volUnidades += li.qty;
        orderMayoTotal += li.amount;
        titlesInOrder.add(li.title);
      }
      mayoRevenue += orderMayoTotal;

      // combinaciones (pares distintos dentro de la orden)
      const titles = [...titlesInOrder].sort();
      for (let i = 0; i < titles.length; i++)
        for (let j = i+1; j < titles.length; j++)
          comboCounts.set(`${titles[i]}|||${titles[j]}`, (comboCounts.get(`${titles[i]}|||${titles[j]}`) || 0) + 1);

      // day-of-month + heatmap
      const d = new Date(o.createdAt);
      const dom = d.getDate();
      const dateKey = d.toISOString().slice(0,10);
      if (!dayOfMonth[dom]) dayOfMonth[dom] = { sum: 0, dates: new Set() };
      dayOfMonth[dom].sum += orderMayoTotal;
      dayOfMonth[dom].dates.add(dateKey);
      heat[d.getDay()][d.getHours()] += orderMayoTotal;
    }

    const topMoney = [...moneyByProduct.entries()].map(([name, v]) => ({ name, value: Math.round(v) }))
      .sort((a,b)=>b.value-a.value).slice(0,10);
    // Top por LITROS despachados (no por cantidad de unidades: un barril de 30 L
    // y una lata de 0,47 L cuentan una unidad cada uno y no son comparables).
    const topLitros = [...volByProduct.entries()]
      .map(([name, v]) => ({ name, value: Math.round(v.litros * 10) / 10, unidades: v.unidades, sinDatoQty: v.sinDatoQty }))
      .filter(x => x.value > 0)
      .sort((a,b)=>b.value-a.value).slice(0,10);
    const avgTicket = mayoOrderCount ? Math.round(mayoRevenue / mayoOrderCount) : 0;
    const combos = [...comboCounts.entries()].map(([k, v]) => {
      const [a,b] = k.split('|||'); return { a, b, count: v };
    }).sort((x,y)=>y.count-x.count).slice(0,10);

    // Top 5 días del mes por venta promedio
    const bestDays = Object.entries(dayOfMonth).map(([dom, o]) => ({
      day: Number(dom), avg: Math.round(o.sum / o.dates.size), total: Math.round(o.sum),
    })).sort((a,b)=>b.avg-a.avg).slice(0,5);

    // Mes vs mes anterior por producto (usa TODO el cache, no el rango)
    const now = new Date();
    const thisM = now.getMonth(), thisY = now.getFullYear();
    const prevDate = new Date(thisY, thisM-1, 1);
    const prevM = prevDate.getMonth(), prevY = prevDate.getFullYear();
    const growth = analyticsCrecimientoPorProducto(result.orders, {
      thisM, thisY, prevM, prevY, extras, notes, estiloPorCodigo, litrosDeLinea,
    });

    res.json({
      available: true, range: r,
      summary: { orders: mayoOrderCount, revenue: Math.round(mayoRevenue), avgTicket },
      topMoney, topLitros, combos, bestDays, heat,
      topLitrosMeta: {
        unidades: volUnidades, sinDatoQty: volSinDatoQty,
        cobertura: volUnidades > 0 ? Math.round((1 - volSinDatoQty / volUnidades) * 100) : null,
      },
      growth: { thisMonthLabel: monthLabel(thisM), prevMonthLabel: monthLabel(prevM), canales: ANALYTICS_GROWTH_CANALES, items: growth },
    });
  } catch (e) {
    res.status(500).json({ error: 'Error en analítica de ventas: ' + e.message });
  }
});

// ─── FASE 4: Sell In (K-BROS → canales) ─────────────────────────────────────
// SELL IN = lo que K-BROS le vende A los canales (Horeca/Retail/Hospitality).
// Reutiliza EXACTAMENTE la misma fuente que /admin/analytics/sales (venta
// mayorista de Shopify vía isMayoristaLine) — no crea un segundo cálculo
// paralelo. La diferencia es el CORTE: acá se agrupa por productId→skuCode
// (nunca por nombre de fantasía) y se atribuye canal por cliente/producto.
const canalDeCliente = (customerId, notes) => {
  const chans = customerId ? notes[customerId]?.channels : null;
  return (Array.isArray(chans) && chans.length) ? chans[0] : null;
};
const canalDeProductoSellin = (productId, extras) => {
  const ex = productId ? extras.items[String(productId)] : null;
  const chans = (Array.isArray(ex?.channels) ? ex.channels : []).filter(c => SELLIN_CANALES.includes(c));
  return chans.length === 1 ? chans[0] : null;
};
// Etiqueta de formato de la línea comprada: matchea el SKU de la variante
// (subCodigo, Fase 3) contra variantesSku del producto — es matcheo por
// código, no por texto. Si el producto es previo a Fase 3 (sin variantesSku),
// usa el nombre de la variante como mejor esfuerzo (nunca inventa litros).
function sellinFormatoLabel(li, extras){
  const ex = li.productId ? extras.items[String(li.productId)] : null;
  const variantesSku = Array.isArray(ex?.variantesSku) ? ex.variantesSku : [];
  if (li.variantSku) {
    const m = variantesSku.find(v => v.subCodigo === li.variantSku);
    if (m) return m.formatoLabel;
  }
  if (li.variantTitle) {
    const parts = String(li.variantTitle).split('·').map(s => s.trim()).filter(Boolean);
    return parts.length ? parts[parts.length - 1] : li.variantTitle;
  }
  return null;
}
const SELLIN_MARCAS = ['todas', 'kairos', 'firulais', 'banny'];
// Nombre de estilo del diccionario de SKU (Golden, Pils, Apa…) para un producto.
// Es el corte con el que se lee la rotación por canal: "qué estilo se movió".
// Sale del estiloCodigo asignado en la ficha; si no está asignado, null (no se
// adivina desde el título — para eso está el mapeo del diccionario).
function sellinEstiloDeProducto(ex, estiloPorCodigo){
  const cod = ex && ex.estiloCodigo;
  return cod ? (estiloPorCodigo.get(String(cod)) || null) : null;
}
// Agregación de Sell In. Función pura sobre las órdenes ya filtradas por fecha:
// mismo cálculo que antes vivía dentro de la ruta, extraído para poder correrlo
// con datos de prueba sin depender de Shopify.
function sellinAgregar(orders, { marca, extras, notes, customBrands, estiloPorCodigo }){
  // Ancla de reconciliación: MISMO total que /admin/analytics/sales para el
  // mismo rango (todas las marcas, todas las líneas mayoristas) — sirve
  // para el QA "Sell In debe cuadrar con la fuente mayorista existente".
  let checkRevenue = 0, checkOrders = 0;
  for (const o of orders) {
    const mayoLines = (o.lineItems || []).filter(isMayoristaLine);
    if (!mayoLines.length) continue;
    checkOrders++;
    for (const li of mayoLines) checkRevenue += li.amount;
  }

  const canalVacio = () => ({ plata: 0, litros: 0, unidades: 0, litrosSinDatoQty: 0, lineas: 0 });
  const porCanal = { horeca: canalVacio(), retail: canalVacio(), hospitality: canalVacio(), sin_canal: canalVacio() };
  const byCliente = new Map();  // customerId → { id, name, plata, litros, canal }
  const byProducto = new Map(); // productId  → { id, skuCode, title, plata, litros, canal, marca }
  // Volumen por SKU DENTRO de cada canal: el corte que responde "qué estilo está
  // rotando y qué falta potenciar". Se abre por producto Y formato, porque el
  // pedido que se repone es de un formato concreto (barril 30L ≠ lata).
  const bySku = new Map();      // canal|productId|formato → fila
  let filtPlata = 0, filtLitros = 0, filtLitrosSinDatoQty = 0, filtUnidades = 0;

  for (const o of orders) {
    const mayoLines = (o.lineItems || []).filter(isMayoristaLine);
    if (!mayoLines.length) continue;
    const custName = [o.customerFirstName, o.customerLastName].filter(Boolean).join(' ').trim()
      || o.shippingAddress?.company || o.customerEmail || '(cliente sin nombre)';
    for (const li of mayoLines) {
      const brandKey = brandFromProduct({ vendor: li.vendor, title: li.title, tags: li.tags }, customBrands);
      if (marca !== 'todas' && brandKey !== marca) continue;

      const canal = canalDeCliente(o.customerId, notes) || canalDeProductoSellin(li.productId, extras) || 'sin_canal';
      const label = sellinFormatoLabel(li, extras);
      const litrosUnidad = label != null ? skuFormatoLitros(label) : null;
      const litrosLinea = litrosUnidad != null ? Math.round(litrosUnidad * li.qty * 1000) / 1000 : 0;
      if (litrosUnidad == null) filtLitrosSinDatoQty += li.qty;

      filtPlata += li.amount; filtLitros += litrosLinea; filtUnidades += li.qty;

      const pc = porCanal[canal] || porCanal.sin_canal;
      pc.plata += li.amount; pc.litros += litrosLinea; pc.unidades += li.qty; pc.lineas++;
      if (litrosUnidad == null) pc.litrosSinDatoQty += li.qty;

      const cid = o.customerId || ('sin-id:' + custName);
      if (!byCliente.has(cid)) byCliente.set(cid, { id: o.customerId, name: custName, plata: 0, litros: 0, canal });
      const bc = byCliente.get(cid);
      bc.plata += li.amount; bc.litros += litrosLinea;

      const pid = li.productId || ('sin-id:' + li.title);
      const ex = li.productId ? extras.items[String(li.productId)] : null;
      if (!byProducto.has(pid)) byProducto.set(pid, {
        id: li.productId, skuCode: ex?.skuCode || null, title: li.title, plata: 0, litros: 0, canal, marca: brandKey,
      });
      const bp = byProducto.get(pid);
      bp.plata += li.amount; bp.litros += litrosLinea;

      const sKey = canal + '|' + pid + '|' + (label || '');
      if (!bySku.has(sKey)) bySku.set(sKey, {
        canal, id: li.productId, skuCode: ex?.skuCode || null, variantSku: li.variantSku || null,
        title: li.title, estilo: sellinEstiloDeProducto(ex, estiloPorCodigo), formato: label,
        marca: brandKey, plata: 0, litros: 0, unidades: 0, sinFormato: litrosUnidad == null,
      });
      const bs = bySku.get(sKey);
      bs.plata += li.amount; bs.litros += litrosLinea; bs.unidades += li.qty;
    }
  }

  for (const s of bySku.values()) {
    const pc = porCanal[s.canal] || porCanal.sin_canal;
    (pc.skus || (pc.skus = [])).push({ ...s, plata: Math.round(s.plata), litros: Math.round(s.litros * 1000) / 1000 });
  }
  for (const k of Object.keys(porCanal)) {
    porCanal[k].plata = Math.round(porCanal[k].plata);
    porCanal[k].litros = Math.round(porCanal[k].litros * 1000) / 1000;
    porCanal[k].available = porCanal[k].lineas > 0;
    // Por litros primero (es el volumen que se repone); la plata desempata, y
    // así los formatos sin conversión a litros quedan ordenados entre ellos.
    porCanal[k].skus = (porCanal[k].skus || []).sort((a, b) => (b.litros - a.litros) || (b.plata - a.plata));
  }
  porCanal.retail.reason = porCanal.retail.available ? null
    : 'Sin datos: ningún cliente/producto mayorista de Shopify tiene canal Retail asignado en este período. Si Retail se abastece por otra vía (ej. Walmart, no facturado por Shopify), cárgalo en el Importador de Retail (Sell Out).';
  porCanal.horeca.reason = porCanal.horeca.available ? null : 'Sin datos en este período.';
  porCanal.hospitality.reason = porCanal.hospitality.available ? null : 'Sin datos en este período.';
  porCanal.sin_canal.reason = porCanal.sin_canal.available ? 'Ventas mayoristas sin canal asignado al cliente ni al producto — asigná el canal para que salgan de este cajón.' : null;

  const topClientes = [...byCliente.values()]
    .map(x => ({ ...x, plata: Math.round(x.plata), litros: Math.round(x.litros * 1000) / 1000 }))
    .sort((a, b) => b.plata - a.plata).slice(0, 10);
  const topProductos = [...byProducto.values()]
    .map(x => ({ ...x, plata: Math.round(x.plata), litros: Math.round(x.litros * 1000) / 1000 }))
    .sort((a, b) => b.plata - a.plata).slice(0, 10);

  return {
    marca, marcas: SELLIN_MARCAS,
    summary: {
      revenue: Math.round(filtPlata),
      litros: Math.round(filtLitros * 1000) / 1000,
      unidades: filtUnidades,
      litrosSinDatoQty: filtLitrosSinDatoQty,
      litrosCobertura: filtUnidades > 0 ? Math.round((1 - filtLitrosSinDatoQty / filtUnidades) * 1000) / 1000 : null,
    },
    checkTotalMayorista: { revenue: Math.round(checkRevenue), orders: checkOrders },
    porCanal,
    topClientes, topProductos,
  };
}
app.get('/admin/sellin', requireAdmin, async (req, res) => {
  const r = rangeFor(String(req.query.range || '30d'));
  const marca = SELLIN_MARCAS.includes(String(req.query.marca || 'todas')) ? String(req.query.marca || 'todas') : 'todas';
  const result = await loadOrders(String(req.query.refresh || '') === '1');
  if (!result.available) return res.json({ available: false, reason: result.reason, range: r });
  try {
    const orders = result.orders.filter(o => {
      const t = new Date(o.createdAt).getTime();
      return t >= r.from && t <= r.to;
    });
    const dicc = skuDiccLoad();
    const estiloPorCodigo = new Map((dicc.estilos || []).map(e => [String(e.codigo), e.nombre]));
    const agg = sellinAgregar(orders, {
      marca, extras: loadProductExtras(), notes: loadCustomerNotes(),
      customBrands: getCustomBrands(), estiloPorCodigo,
    });
    res.json({ available: true, range: r, ...agg });
  } catch (e) {
    res.status(500).json({ error: 'Error en Sell In: ' + e.message });
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// FASE 4 · Importador flexible de RETAIL (Sell Out)
// Retail Link no factura por Shopify y el formato del archivo varía por
// retailer. Flujo: subir CSV → mapear columnas → previsualizar → confirmar.
// El mapeo se guarda como plantilla reutilizable por retailer. Solo CSV por
// ahora (XLSX requeriría una librería con vulnerabilidades sin parche
// conocido — se evaluará más adelante); mientras tanto exportar el Excel del
// retailer como CSV es un paso trivial. El match producto↔SKU-código es
// mejor esfuerzo por nombre normalizado; lo que no matchea queda marcado
// "sin mapear", nunca se descarta en silencio.
// ─────────────────────────────────────────────────────────────────────────────
const RETAIL_VENTAS_FILE = join(PROMPTS_EFFECTIVE_DIR, 'retail-ventas.json');
const RETAIL_TEMPLATES_FILE = join(PROMPTS_EFFECTIVE_DIR, 'retail-templates.json');
function loadRetailVentas(){
  try { if (existsSync(RETAIL_VENTAS_FILE)) { const p = JSON.parse(readFileSync(RETAIL_VENTAS_FILE, 'utf-8')); return { version: 1, uploads: Array.isArray(p.uploads) ? p.uploads : [] }; } }
  catch (e) { console.warn('retail ventas load:', e.message); }
  return { version: 1, uploads: [] };
}
function saveRetailVentas(d){ writeFileSync(RETAIL_VENTAS_FILE, JSON.stringify(d, null, 2)); }
function loadRetailTemplates(){
  try { if (existsSync(RETAIL_TEMPLATES_FILE)) { const p = JSON.parse(readFileSync(RETAIL_TEMPLATES_FILE, 'utf-8')); return { version: 1, templates: Array.isArray(p.templates) ? p.templates : [] }; } }
  catch (e) { console.warn('retail templates load:', e.message); }
  return { version: 1, templates: [] };
}
function saveRetailTemplates(d){ writeFileSync(RETAIL_TEMPLATES_FILE, JSON.stringify(d, null, 2)); }

// Parser CSV nativo (sin dependencias): detecta delimitador (,/;/tab), soporta
// campos entre comillas con comas/saltos de línea internos y comillas escapadas ("").
function csvParse(text){
  const raw = String(text || '').replace(/^﻿/, '');
  const rowsRaw = [];
  let cur = [], field = '', inQ = false;
  let delim = null;
  const headerLine = raw.slice(0, raw.search(/\r\n|\r|\n/) === -1 ? raw.length : raw.search(/\r\n|\r|\n/));
  const counts = { ',': (headerLine.match(/,/g) || []).length, ';': (headerLine.match(/;/g) || []).length, '\t': (headerLine.match(/\t/g) || []).length };
  delim = Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0];
  if (!delim || counts[delim] === 0) delim = ',';
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i];
    if (inQ) {
      if (c === '"') { if (raw[i + 1] === '"') { field += '"'; i++; } else inQ = false; }
      else field += c;
    } else if (c === '"') inQ = true;
    else if (c === delim) { cur.push(field.trim()); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && raw[i + 1] === '\n') i++;
      cur.push(field.trim()); field = '';
      if (cur.length > 1 || cur[0] !== '') rowsRaw.push(cur);
      cur = [];
    } else field += c;
  }
  if (field !== '' || cur.length) { cur.push(field.trim()); if (cur.length > 1 || cur[0] !== '') rowsRaw.push(cur); }
  if (!rowsRaw.length) return { headers: [], rows: [], delim };
  const headers = rowsRaw[0];
  const rows = rowsRaw.slice(1);
  return { headers, rows, delim };
}
function retailParseNumero(s){
  let t = String(s == null ? '' : s).trim();
  if (!t) return null;
  t = t.replace(/[^\d.,-]/g, '');
  if (!t) return null;
  const hasComma = t.includes(','), hasDot = t.includes('.');
  if (hasComma && hasDot) t = t.lastIndexOf(',') > t.lastIndexOf('.') ? t.replace(/\./g, '').replace(',', '.') : t.replace(/,/g, '');
  else if (hasComma) t = t.replace(',', '.');
  const n = Number(t);
  return Number.isFinite(n) ? n : null;
}
function retailParseFecha(s){
  const t = String(s || '').trim();
  if (!t) return null;
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).toISOString();
  m = t.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);
  if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1])).toISOString();
  const d = new Date(t);
  return isNaN(d.getTime()) ? null : d.toISOString();
}
// Índice del catálogo (título normalizado + SKU-código) para matchear filas
// del archivo de Retail. Usa el catálogo real de Shopify + carta interna —
// nunca inventa un match, solo lo marca cuando hay coincidencia clara.
async function retailCatalogIndex(){
  const all = (await loadProductsCache(false)) || [];
  const extras = loadProductExtras();
  const customBrands = getCustomBrands();
  const byTitle = new Map(), byCode = new Map();
  for (const p of all) {
    const ex = extras.items[String(p.id)];
    if (!ex || !ex.skuCode) continue;
    const entry = { skuCode: ex.skuCode, marca: brandFromProduct(p, customBrands), title: p.title };
    byTitle.set(cdNorm(p.title), entry);
    byCode.set(ex.skuCode.toLowerCase(), entry);
    for (const v of (Array.isArray(ex.variantesSku) ? ex.variantesSku : [])) {
      byTitle.set(cdNorm(p.title + ' ' + v.formatoLabel), entry);
    }
  }
  const menu = loadSkuMenu();
  for (const it of Object.values(menu.items || {})) {
    if (it.skuCode && it.titulo) byTitle.set(cdNorm(it.titulo), { skuCode: it.skuCode, marca: it.marca || null, title: it.titulo });
  }
  return { byTitle, byCode };
}
function retailMatchSku(nombreProducto, idx){
  const n = cdNorm(nombreProducto);
  if (!n) return null;
  if (idx.byTitle.has(n)) return idx.byTitle.get(n);
  const codeGuess = String(nombreProducto || '').trim().toLowerCase();
  if (idx.byCode.has(codeGuess)) return idx.byCode.get(codeGuess);
  const candidates = [...idx.byTitle.entries()].filter(([k]) => k && (k.includes(n) || n.includes(k)));
  return candidates.length === 1 ? candidates[0][1] : null;
}
const RETAIL_CAMPOS = ['producto', 'unidades', 'plata', 'fecha', 'local'];
const retailSlug = (s) => String(s || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');

// Sube el CSV y devuelve encabezados + muestra, para mapear columnas antes
// de confirmar. No persiste nada todavía.
app.post('/admin/retail/preview', requireAdmin, (req, res) => {
  const { csvText, retailer } = req.body || {};
  if (!csvText || typeof csvText !== 'string') return res.status(400).json({ error: 'Falta el archivo (csvText).' });
  if (csvText.length > 8_000_000) return res.status(413).json({ error: 'Archivo demasiado grande (máx ~8MB en CSV).' });
  const { headers, rows, delim } = csvParse(csvText);
  if (!headers.length) return res.status(400).json({ error: 'No se pudo leer el CSV (¿está vacío?).' });
  const sample = rows.slice(0, 10).map(r => headers.reduce((o, h, i) => { o[h] = r[i] ?? ''; return o; }, {}));
  const tpl = retailer ? loadRetailTemplates().templates.find(t => t.retailerSlug === retailSlug(retailer)) : null;
  res.json({ headers, rowCount: rows.length, delim, sample, suggestedMapping: tpl ? tpl.mapping : null });
});

app.get('/admin/retail/templates', requireAdmin, (req, res) => {
  res.json({ templates: loadRetailTemplates().templates, campos: RETAIL_CAMPOS });
});

// Confirma la importación: parsea TODO el archivo con el mapeo elegido,
// matchea cada fila contra el catálogo (SKU-código) y persiste. Si el
// retailer ya tiene plantilla y no se manda mapping, la reutiliza.
app.post('/admin/retail/import', requireAdmin, async (req, res) => {
  const b = req.body || {};
  const retailer = String(b.retailer || '').trim().slice(0, 80);
  if (!retailer) return res.status(400).json({ error: 'Falta el nombre del retailer.' });
  if (!b.csvText || typeof b.csvText !== 'string') return res.status(400).json({ error: 'Falta el archivo (csvText).' });
  const retailerSlug = retailSlug(retailer);
  const templates = loadRetailTemplates();
  const existingTpl = templates.templates.find(t => t.retailerSlug === retailerSlug);
  const mapping = (b.mapping && typeof b.mapping === 'object') ? b.mapping : (existingTpl ? existingTpl.mapping : null);
  if (!mapping || !mapping.producto || !mapping.unidades || !mapping.plata) {
    return res.status(400).json({ error: 'Falta mapear al menos producto, unidades y plata.' });
  }
  const { headers, rows: rawRows } = csvParse(b.csvText);
  if (!headers.length) return res.status(400).json({ error: 'No se pudo leer el CSV.' });
  for (const campo of ['producto', 'unidades', 'plata']) {
    if (!headers.includes(mapping[campo])) return res.status(400).json({ error: `La columna mapeada para "${campo}" no existe en el archivo.` });
  }
  try {
    const idx = await retailCatalogIndex();
    const rows = [];
    let sinMapearCount = 0, plataTotal = 0, unidadesTotal = 0;
    for (const r of rawRows) {
      const obj = headers.reduce((o, h, i) => { o[h] = r[i] ?? ''; return o; }, {});
      const producto = String(obj[mapping.producto] || '').trim();
      const unidades = retailParseNumero(obj[mapping.unidades]);
      const plata = retailParseNumero(obj[mapping.plata]);
      if (!producto && unidades == null && plata == null) continue; // fila vacía
      const fecha = mapping.fecha ? retailParseFecha(obj[mapping.fecha]) : null;
      const local = mapping.local ? String(obj[mapping.local] || '').trim() || null : null;
      const match = retailMatchSku(producto, idx);
      if (!match) sinMapearCount++;
      plataTotal += plata || 0; unidadesTotal += unidades || 0;
      rows.push({
        producto, unidades: unidades ?? 0, plata: plata ?? 0, fecha, local,
        skuCode: match ? match.skuCode : null, marca: match ? match.marca : null,
        matched: !!match,
      });
    }
    const now = new Date().toISOString();
    const upload = {
      id: 'ru_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
      retailer, retailerSlug, filename: String(b.filename || '').slice(0, 200) || 'archivo.csv',
      uploadedAt: now, mapping,
      totals: { filas: rows.length, plata: Math.round(plataTotal), unidades: unidadesTotal, sinMapear: sinMapearCount, matched: rows.length - sinMapearCount },
      rows,
    };
    const store = loadRetailVentas();
    store.uploads.push(upload);
    saveRetailVentas(store);
    if (b.saveTemplate !== false) {
      if (existingTpl) { existingTpl.mapping = mapping; existingTpl.updatedAt = now; }
      else templates.templates.push({ id: 'rt_' + Date.now().toString(36), retailer, retailerSlug, mapping, createdAt: now, updatedAt: now });
      saveRetailTemplates(templates);
    }
    res.json({
      ok: true, uploadId: upload.id, totals: upload.totals,
      sinMapear: rows.filter(r => !r.matched).map(r => r.producto).filter((v, i, a) => a.indexOf(v) === i).slice(0, 200),
    });
  } catch (e) {
    res.status(500).json({ error: 'Error importando: ' + e.message });
  }
});

app.get('/admin/retail/uploads', requireAdmin, (req, res) => {
  const store = loadRetailVentas();
  res.json({ uploads: store.uploads.map(u => ({ id: u.id, retailer: u.retailer, filename: u.filename, uploadedAt: u.uploadedAt, totals: u.totals })) });
});
app.delete('/admin/retail/uploads/:id', requireAdmin, (req, res) => {
  const store = loadRetailVentas();
  const before = store.uploads.length;
  store.uploads = store.uploads.filter(u => u.id !== String(req.params.id));
  if (store.uploads.length === before) return res.status(404).json({ error: 'Carga no encontrada.' });
  saveRetailVentas(store);
  res.json({ ok: true });
});

// Sell Out de Retail agregado desde TODAS las cargas — usado por /admin/sellout.
// Si nunca se cargó un archivo, "Sin datos" honesto (nunca $0 inventado).
function retailSelloutAgregado(range, marca){
  const store = loadRetailVentas();
  if (!store.uploads.length) return { available: false, reason: 'Sin datos: todavía no se ha cargado ningún archivo de Retail. Usá el Importador de Retail.' };
  const byProducto = new Map(); let plata = 0, unidades = 0, sinFecha = 0, filas = 0;
  for (const u of store.uploads) {
    for (const row of u.rows) {
      if (marca && marca !== 'todas' && row.marca !== marca) continue;
      if (row.fecha) {
        const t = new Date(row.fecha).getTime();
        if (!(t >= range.from && t <= range.to)) continue;
      } else {
        sinFecha++; // sin fecha en el archivo: se incluye igual (mejor esfuerzo), pero se cuenta aparte para transparencia
      }
      filas++; plata += row.plata; unidades += row.unidades;
      const key = row.skuCode || ('sin-mapear:' + row.producto);
      const p = byProducto.get(key) || { skuCode: row.skuCode, nombre: row.producto, plata: 0, unidades: 0, matched: row.matched };
      p.plata += row.plata; p.unidades += row.unidades; byProducto.set(key, p);
    }
  }
  if (!filas) return { available: false, reason: 'Sin datos: no hay filas de Retail dentro de este período/marca.' };
  const top = [...byProducto.values()].map(p => ({ ...p, plata: Math.round(p.plata) })).sort((a, b) => b.plata - a.plata).slice(0, 10);
  return { available: true, plata: Math.round(plata), unidades, filas, sinFecha, top };
}

// ─── FASE 4: Sell Out (canales → consumidor final) ──────────────────────────
// SELL OUT = lo que los canales le venden AL CONSUMIDOR FINAL. Compone 4
// fuentes reales, cada una con su propia granularidad — no las mezcla en un
// número inventado: HORECA y Hospitality vienen de Pyxis (período fijo de los
// últimos 3 meses que entrega esa API, no el filtro de rango de Shopify);
// Online y Retail sí respetan el filtro de rango. El filtro de marca aplica
// a Online y Retail (datos propios, cruzados por SKU-código); HORECA/
// Hospitality quedan con todas las marcas K-BROS juntas porque el
// clasificador de Pyxis ya vigente (pyxisCervezasResumen) agrupa Kairos
// Brewing/Firulais/Banny en un solo balde "kairos" — separarlas requeriría
// una reclasificación de Pyxis fuera del alcance de esta fase.
app.get('/admin/sellout', requireAdmin, async (req, res) => {
  const r = rangeFor(String(req.query.range || '30d'));
  const marca = SELLIN_MARCAS.includes(String(req.query.marca || 'todas')) ? String(req.query.marca || 'todas') : 'todas';
  const grupoPyxis = String(req.query.grupo || 2).replace(/[^0-9]/g, '') || '2';

  const onlineResult = await loadOrders(false);
  let online;
  if (!onlineResult.available) {
    online = { available: false, reason: onlineResult.reason };
  } else {
    const extras = loadProductExtras();
    const customBrands = getCustomBrands();
    const orders = onlineResult.orders.filter(o => { const t = new Date(o.createdAt).getTime(); return t >= r.from && t <= r.to; });
    const byProducto = new Map();
    let plata = 0, unidades = 0;
    for (const o of orders) {
      for (const li of (o.lineItems || [])) {
        if (isMayoristaLine(li)) continue;
        const brandKey = brandFromProduct({ vendor: li.vendor, title: li.title, tags: li.tags }, customBrands);
        if (marca !== 'todas' && brandKey !== marca) continue;
        plata += li.amount; unidades += li.qty;
        const pid = li.productId || ('sin-id:' + li.title);
        const ex = li.productId ? extras.items[String(li.productId)] : null;
        const p = byProducto.get(pid) || { id: li.productId, skuCode: ex?.skuCode || null, title: li.title, plata: 0, unidades: 0, marca: brandKey };
        p.plata += li.amount; p.unidades += li.qty; byProducto.set(pid, p);
      }
    }
    const top = [...byProducto.values()].map(p => ({ ...p, plata: Math.round(p.plata) })).sort((a, b) => b.plata - a.plata).slice(0, 10);
    online = { available: true, plata: Math.round(plata), unidades, top };
  }

  let horeca;
  try {
    const d = await pyxisCervezasResumen(grupoPyxis, {});
    horeca = {
      available: true, periodoPyxis: d.meses,
      plata: d.totales.kairos, unidades: d.totales.kairosCant,
      top: d.kairos.slice(0, 10).map(p => ({ nombre: p.nombre, plata: p.total, unidades: p.cant })),
    };
  } catch (e) { horeca = { available: false, reason: 'Pyxis no disponible: ' + String(e.message || e).slice(0, 160) }; }

  let hospitality;
  try {
    const h = await pyxisHospitalidadResumen(grupoPyxis, {});
    const topNorm = (arr) => (arr || []).map(p => ({ nombre: p.nombre, plata: p.total, unidades: p.cant }));
    hospitality = !h.available ? h : {
      available: true, periodoPyxis: h.meses,
      comida: { plata: h.totales.comida, unidades: h.totales.cantComida, top: topNorm(h.topComida) },
      barra:  { plata: h.totales.barra,  unidades: h.totales.cantBarra,  top: topNorm(h.topBarra) },
      porLocal: h.porLocal, sinClasificar: h.sinClasificar,
    };
  } catch (e) { hospitality = { available: false, reason: 'Pyxis no disponible: ' + String(e.message || e).slice(0, 160) }; }

  const retail = retailSelloutAgregado(r, marca);

  res.json({ available: true, range: r, marca, marcas: SELLIN_MARCAS, online, horeca, hospitality, retail });
});

// ─────────────────────────────────────────────────────────────────────────────
// Forecast Comercial (Herramientas) — grilla CANAL × MARCA de proyección de
// venta, con meta configurable (+15% default) por celda. Reutiliza las MISMAS
// fuentes que Sell In/Out (loadOrders, isMayoristaLine, brandFromProduct,
// sellinFormatoLabel/skuFormatoLitros, retail-ventas.json, pyxisHospitalidadResumen)
// — nunca las vuelve a calcular en paralelo. El "número base sugerido" es
// siempre un dato REAL (mismo mes año pasado, o si no hay, promedio de los
// últimos 3 meses); si no hay ninguna de las dos fuentes, queda vacío — nunca
// se inventa ni se estima.
// ─────────────────────────────────────────────────────────────────────────────
const FC_GRID = {
  horeca:      { label: 'Horeca',       cols: ['kairos', 'firulais', 'banny'] },
  retail:      { label: 'Retail',       cols: ['kairos', 'firulais', 'banny'] },
  online:      { label: 'Venta Online', cols: ['kairos', 'firulais', 'banny'] },
  hospitality: { label: 'Hospitality',  cols: ['garden_vespucio', 'garden_antofagasta', 'badass_parque_arauco'] },
};
const FC_COL_LABELS = {
  kairos: 'Kairos Brewing', firulais: 'Firulais', banny: 'Banny',
  garden_vespucio: 'Kairos Garden Vespucio', garden_antofagasta: 'Kairos Garden Antofagasta',
  badass_parque_arauco: 'Kairos Badass Parque Arauco',
};
const FC_META_PCT_DEFAULT = 15;
const FORECAST_COMERCIAL_FILE = join(PROMPTS_EFFECTIVE_DIR, 'forecast-comercial.json');
function fcLoad(){
  try {
    if (existsSync(FORECAST_COMERCIAL_FILE)) {
      const p = JSON.parse(readFileSync(FORECAST_COMERCIAL_FILE, 'utf-8'));
      return { version: 1, meses: (p.meses && typeof p.meses === 'object') ? p.meses : {} };
    }
  } catch (e) { console.warn('forecast comercial load:', e.message); }
  return { version: 1, meses: {} };
}
function fcSave(d){ writeFileSync(FORECAST_COMERCIAL_FILE, JSON.stringify(d, null, 2)); }
function fcCellKey(canal, col){ return canal + '::' + col; }
// 'YYYY-MM' menos n meses → 'YYYY-MM'.
function fcMonthAgo(monthStr, n){
  const [y, m] = monthStr.split('-').map(Number);
  const d = new Date(Date.UTC(y, m - 1 - n, 1));
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}`;
}

// Construye TODA la grilla de sugerencias para un mes, cargando cada fuente
// real una sola vez (no una llamada por celda).
async function fcSugeridoGrid(monthStr){
  const anoPasadoStr = fcMonthAgo(monthStr, 12);
  const mesesPrevios = [1, 2, 3].map(n => fcMonthAgo(monthStr, n));

  const ordersResult = await loadOrders(false);
  const extras = loadProductExtras();
  const customBrands = getCustomBrands();
  const retailStore = loadRetailVentas();
  let hospResumen = null;
  try { hospResumen = await pyxisHospitalidadResumen('2', {}); } catch { hospResumen = null; }

  // Venta Online (Shopify B2C, no-mayorista) para un mes calendario exacto y
  // una marca — misma lógica de matching que Sell In (variantSku → variantesSku
  // → skuFormatoLitros), sin recalcularla distinto.
  const onlineMes = (marca, ms) => {
    if (!ordersResult.available) return null;
    const [y, m] = ms.split('-').map(Number);
    const from = Date.UTC(y, m - 1, 1), to = Date.UTC(y, m, 1);
    let plata = 0, litros = 0, found = false;
    for (const o of ordersResult.orders) {
      const t = new Date(o.createdAt).getTime();
      if (t < from || t >= to) continue;
      for (const li of (o.lineItems || [])) {
        if (isMayoristaLine(li)) continue;
        const brandKey = brandFromProduct({ vendor: li.vendor, title: li.title, tags: li.tags }, customBrands);
        if (brandKey !== marca) continue;
        found = true; plata += li.amount;
        const label = sellinFormatoLabel(li, extras);
        const lu = label != null ? skuFormatoLitros(label) : null;
        if (lu != null) litros += lu * li.qty;
      }
    }
    return found ? { plata: Math.round(plata), litros: Math.round(litros * 1000) / 1000 } : null;
  };
  // Retail (filas del importador CSV, Fase 4) para un mes exacto y marca —
  // mismo store, sin volver a parsear archivos. Sin litros: el CSV no trae
  // formato/volumen por fila.
  const retailMes = (marca, ms) => {
    if (!retailStore.uploads.length) return null;
    let plata = 0, found = false;
    for (const u of retailStore.uploads) for (const row of u.rows) {
      if (row.marca !== marca || !row.fecha || String(row.fecha).slice(0, 7) !== ms) continue;
      found = true; plata += row.plata;
    }
    return found ? { plata: Math.round(plata), litros: null } : null;
  };
  // Hospitality: Pyxis solo entrega los últimos 3 meses corridos (nunca un mes
  // específico de hace un año), y agrupa por LOCAL real de Pyxis — matcheamos
  // por nombre (mismo criterio ya aceptado para clasificar cervezas/locales en
  // Fase 4) contra los 3 locales canónicos del negocio.
  const hospLocalMatch = (col) => {
    if (!hospResumen || !hospResumen.available) return null;
    const rx = { garden_vespucio: /vespucio/i, garden_antofagasta: /antofagasta/i, badass_parque_arauco: /badass|parque\s*arauco/i }[col];
    return rx ? hospResumen.porLocal.find(l => rx.test(l.local)) : null;
  };

  const out = {};
  for (const [canal, def] of Object.entries(FC_GRID)) {
    for (const col of def.cols) {
      const key = fcCellKey(canal, col);
      let celda = { plata: { valor: null, origen: null }, litros: { valor: null, origen: null } };
      if (canal === 'online' || canal === 'retail') {
        const fn = canal === 'online' ? onlineMes : retailMes;
        const yearAgo = fn(col, anoPasadoStr);
        if (yearAgo && (yearAgo.plata || yearAgo.litros)) {
          celda = {
            plata: { valor: yearAgo.plata, origen: 'mismo_mes_ano_pasado' },
            litros: { valor: yearAgo.litros, origen: yearAgo.litros != null ? 'mismo_mes_ano_pasado' : null },
          };
        } else {
          const vals = mesesPrevios.map(m => fn(col, m)).filter(Boolean);
          if (vals.length) {
            const plata = Math.round(vals.reduce((s, v) => s + v.plata, 0) / vals.length);
            const litrosVals = vals.filter(v => v.litros != null);
            const litros = litrosVals.length ? Math.round(litrosVals.reduce((s, v) => s + v.litros, 0) / litrosVals.length * 1000) / 1000 : null;
            celda = { plata: { valor: plata, origen: 'promedio_3m' }, litros: { valor: litros, origen: litros != null ? 'promedio_3m' : null } };
          }
        }
      } else if (canal === 'hospitality') {
        const match = hospLocalMatch(col);
        if (match) celda = { plata: { valor: Math.round((match.comida + match.barra) / 3), origen: 'promedio_3m' }, litros: { valor: null, origen: null } };
      }
      // canal === 'horeca': Pyxis clasifica "kairos" como un solo balde (todas
      // las marcas K-BROS juntas, ver Fase 4) — no hay forma real de separar
      // Kairos Brewing/Firulais/Banny ahí sin inventar un reparto. Queda
      // "Sin datos" a propósito; el equipo carga el número a mano si lo tiene.
      out[key] = celda;
    }
  }
  return out;
}

app.get('/admin/forecast-comercial/meta', requireAdmin, (req, res) => {
  res.json({ canales: FC_GRID, colLabels: FC_COL_LABELS, metaPctDefault: FC_META_PCT_DEFAULT });
});

// Núcleo del cálculo, factorizado para que el HOME (Cuadro 2) pueda leer el
// mismo resultado exacto sin recalcularlo aparte ("misma fuente, no cálculo
// paralelo" — QA explícito del pedido).
async function fcMonthCompute(month){
  const store = fcLoad();
  const guardado = store.meses[month] || { celdas: {} };
  const sugeridoGrid = await fcSugeridoGrid(month);
  const celdas = {};
  let totPlataProy = 0, totPlataMeta = 0, totLitrosProy = 0, totLitrosMeta = 0;
  const porCanal = {};
  for (const [canal, def] of Object.entries(FC_GRID)) {
    porCanal[canal] = { plataProyectado: 0, plataMeta: 0, litrosProyectado: 0, litrosMeta: 0 };
    for (const col of def.cols) {
      const key = fcCellKey(canal, col);
      const g = guardado.celdas[key] || null;
      const sug = sugeridoGrid[key] || { plata: { valor: null, origen: null }, litros: { valor: null, origen: null } };
      const metaPct = (g && Number.isFinite(g.metaPct)) ? g.metaPct : FC_META_PCT_DEFAULT;
      const plataValor = (g && g.plataValor != null) ? g.plataValor : sug.plata.valor;
      const litrosValor = (g && g.litrosValor != null) ? g.litrosValor : sug.litros.valor;
      const plataTocado = !!(g && g.plataValor != null);
      const litrosTocado = !!(g && g.litrosValor != null);
      const plataMeta = plataValor != null ? Math.round(plataValor * (1 + metaPct / 100)) : null;
      const litrosMeta = litrosValor != null ? Math.round(litrosValor * (1 + metaPct / 100) * 1000) / 1000 : null;
      celdas[key] = {
        plata: { valor: plataValor, sugerido: sug.plata.valor, sugeridoOrigen: sug.plata.origen, tocado: plataTocado, meta: plataMeta },
        litros: { valor: litrosValor, sugerido: sug.litros.valor, sugeridoOrigen: sug.litros.origen, tocado: litrosTocado, meta: litrosMeta },
        metaPct,
      };
      if (plataValor != null) { totPlataProy += plataValor; porCanal[canal].plataProyectado += plataValor; }
      if (plataMeta != null) { totPlataMeta += plataMeta; porCanal[canal].plataMeta += plataMeta; }
      if (litrosValor != null) { totLitrosProy += litrosValor; porCanal[canal].litrosProyectado += litrosValor; }
      if (litrosMeta != null) { totLitrosMeta += litrosMeta; porCanal[canal].litrosMeta += litrosMeta; }
    }
  }
  return {
    month, canales: FC_GRID, colLabels: FC_COL_LABELS, celdas,
    totales: {
      plataProyectado: Math.round(totPlataProy), plataMeta: Math.round(totPlataMeta),
      litrosProyectado: Math.round(totLitrosProy * 1000) / 1000, litrosMeta: Math.round(totLitrosMeta * 1000) / 1000,
    },
    porCanal,
    guardadoEn: guardado.guardadoEn || null,
  };
}

app.get('/admin/forecast-comercial/:month', requireAdmin, async (req, res) => {
  const month = String(req.params.month);
  if (!/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'Mes inválido (usar YYYY-MM).' });
  try {
    res.json(await fcMonthCompute(month));
  } catch (e) {
    res.status(500).json({ error: 'Error calculando Forecast Comercial: ' + e.message });
  }
});

app.put('/admin/forecast-comercial/:month', requireAdmin, (req, res) => {
  const month = String(req.params.month);
  if (!/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'Mes inválido (usar YYYY-MM).' });
  const b = req.body || {};
  const celdasIn = (b.celdas && typeof b.celdas === 'object') ? b.celdas : {};
  const validKeys = new Set();
  for (const [canal, def] of Object.entries(FC_GRID)) for (const col of def.cols) validKeys.add(fcCellKey(canal, col));
  const store = fcLoad();
  const celdasOut = {};
  for (const [key, val] of Object.entries(celdasIn)) {
    if (!validKeys.has(key) || !val || typeof val !== 'object') continue;
    const plataValor = val.plataValor != null && Number.isFinite(Number(val.plataValor)) ? Number(val.plataValor) : null;
    const litrosValor = val.litrosValor != null && Number.isFinite(Number(val.litrosValor)) ? Number(val.litrosValor) : null;
    const metaPct = Number.isFinite(Number(val.metaPct)) ? Math.max(0, Math.min(500, Number(val.metaPct))) : FC_META_PCT_DEFAULT;
    celdasOut[key] = { plataValor, litrosValor, metaPct };
  }
  store.meses[month] = { celdas: celdasOut, guardadoEn: new Date().toISOString() };
  fcSave(store);
  res.json({ ok: true, month });
});

// ─────────────────────────────────────────────────────────────────────────────
// HOME de área Comercial — filtro de período (Mes actual · Mes pasado ·
// Últimos 30 días · Rango personalizado, mismo mecanismo ya usado por el
// dashboard general), Cuadro 1 (comparativa 3 meses por canal), Cuadro 2
// (lee Forecast Comercial — MISMA fuente, no la recalcula) y Cuadro 3 (top
// por producto, cruzado por SKU-código). Prohibido inventar cifras: donde no
// hay fuente real, "Sin datos" (null), nunca cero.
// ─────────────────────────────────────────────────────────────────────────────
// Copia deliberada de dashResolvePeriodo() (mismo criterio exacto de
// "Mes actual/Mes pasado/30d/Rango personalizado") — mismo patrón de
// duplicación ya usado en el resto del archivo entre módulos de área.
function comercialResolvePeriodo(tipo, fromQ, toQ){
  const pad2 = (n) => String(n).padStart(2, '0');
  const ymd = (d) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
  const monthOf = (s) => s.slice(0, 7);
  const today = new Date();
  if (tipo === 'mes_pasado') {
    const d = new Date(today.getFullYear(), today.getMonth() - 1, 1);
    const month = `${d.getFullYear()}-${pad2(d.getMonth() + 1)}`;
    return { tipo, month, rango: null, label: 'Mes pasado' };
  }
  if (tipo === '30d') {
    const to = new Date(today), from = new Date(today); from.setDate(from.getDate() - 29);
    const toS = ymd(to), fromS = ymd(from);
    return { tipo, month: monthOf(toS), rango: { from: fromS, to: toS }, label: 'Últimos 30 días' };
  }
  if (tipo === 'custom') {
    const d = /^\d{4}-\d{2}-\d{2}$/;
    if (!d.test(fromQ || '') || !d.test(toQ || '') || fromQ > toQ) return null;
    return { tipo, month: monthOf(toQ), rango: { from: fromQ, to: toQ }, label: 'Rango personalizado' };
  }
  const month = `${today.getFullYear()}-${pad2(today.getMonth() + 1)}`;
  return { tipo: 'mes_actual', month, rango: null, label: 'Mes actual' };
}
function comercialPeriodoRangoTs(periodo){
  if (periodo.rango) {
    return { from: new Date(periodo.rango.from + 'T00:00:00').getTime(), to: new Date(periodo.rango.to + 'T23:59:59.999').getTime() };
  }
  const [y, m] = periodo.month.split('-').map(Number);
  return { from: new Date(y, m - 1, 1).getTime(), to: new Date(y, m, 1).getTime() };
}

// Cuadro 1: ventas comparativas por canal — mes actual / mes pasado / mismo
// mes año pasado. Reutiliza loadOrders (Online), retail-ventas.json (Retail),
// pyxisCervezasResumen/pyxisHospitalidadResumen (Horeca/Hospitality) — las
// mismas fuentes de Sell In/Out, nunca un cálculo paralelo.
async function comercialCuadro1(){
  const today = new Date();
  const monthActual = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;
  const monthPasado = fcMonthAgo(monthActual, 1);
  const monthAnoPasado = fcMonthAgo(monthActual, 12);
  // Los 4 canales salen del MISMO Ingreso por Venta de K-BROS (estadoResolve),
  // no de Pyxis: es el dato interno auditado (Horeca, Venta Online, Retail,
  // Hospitality) que usa el Estado de Resultado — así "año pasado" también aplica.
  const canalesDeMes = async (ms) => {
    try {
      const e = await estadoResolve(ms); const i = e.ingresos;
      // Horeca del total ya resuelto (i.horeca.total), NO de cd_kairos.neto +
      // ventas_cruzada.total: en los meses históricos de 2025 esos dos campos
      // quedan en 0 (vienen de Shopify, que no alcanza tan atrás) y el total
      // real del mes vive en i.horeca.total. Para meses en vivo son iguales.
      const hist = (estadoHistCdLoad().cd[CD_DEFAULT] || {})[ms];
      // Venta Online histórica: Shopify no llega a 2025 (devuelve 0), así que si
      // el mes es histórico y en vivo da 0, se usa el valor de Venta Online
      // auditado al cargar el mes (ventaOnlineRef). Para meses en vivo manda
      // siempre lo real de Shopify.
      const online = (i.ventas_web.cobrado || 0) || ((hist && hist.ventaOnlineRef) || 0);
      return {
        horeca: (i.horeca && i.horeca.total) || 0,
        online,
        retail: (i.retail != null ? i.retail : 0),
        hospitality: (i.hospitality && i.hospitality.total) || 0,
        ok: !!e.shopifyOk,
      };
    } catch { return null; }
  };
  const [a, p, y] = await Promise.all([canalesDeMes(monthActual), canalesDeMes(monthPasado), canalesDeMes(monthAnoPasado)]);
  // Muestra el valor si el mes se pudo resolver (aunque sea 0). null solo si no
  // se pudo calcular (ej. Shopify caído al pedir el mes).
  const cel = (obj, k) => (obj && obj[k] != null) ? { plata: Math.round(obj[k]), litros: null } : null;
  return {
    monthActual, monthPasado, monthAnoPasado,
    canales: {
      horeca:      { label: 'Horeca',       mesActual: cel(a, 'horeca'),      mesPasado: cel(p, 'horeca'),      mismoMesAnoPasado: cel(y, 'horeca') },
      retail:      { label: 'Retail',       mesActual: cel(a, 'retail'),      mesPasado: cel(p, 'retail'),      mismoMesAnoPasado: cel(y, 'retail') },
      online:      { label: 'Venta Online', mesActual: cel(a, 'online'),      mesPasado: cel(p, 'online'),      mismoMesAnoPasado: cel(y, 'online') },
      hospitality: { label: 'Hospitality',  mesActual: cel(a, 'hospitality'), mesPasado: cel(p, 'hospitality'), mismoMesAnoPasado: cel(y, 'hospitality') },
    },
    notas: {
      fuente: 'Datos del Ingreso por Venta de K-BROS (mismo que el Estado de Resultado).',
    },
  };
}

// Cuadro 2: proyección vs real. LEE fcMonthCompute() (misma fuente que la
// herramienta Forecast Comercial) + Cuadro 1 (mismo cálculo de "vendido a la
// fecha" que ya usa Sell In/Out) — no recalcula nada aparte.
async function comercialCuadro2(periodo){
  const fc = await fcMonthCompute(periodo.month);
  const today = new Date();
  const monthActualReal = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;
  const esMesActual = periodo.month === monthActualReal;
  let vendidoAHoy = null, diaHoy = null, diasDelMes = null;
  if (esMesActual) {
    const cuadro1 = await comercialCuadro1();
    const c = cuadro1.canales;
    const conDato = ['horeca', 'retail', 'online', 'hospitality'].filter(k => c[k].mesActual != null);
    vendidoAHoy = conDato.length ? conDato.reduce((s, k) => s + c[k].mesActual.plata, 0) : null;
    diaHoy = today.getDate();
    diasDelMes = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
  }
  const pctMeta = (vendidoAHoy != null && fc.totales.plataMeta) ? Math.round(vendidoAHoy / fc.totales.plataMeta * 1000) / 10 : null;
  return {
    month: periodo.month, esMesActual,
    proyectado: fc.totales.plataProyectado || null,
    meta: fc.totales.plataMeta || null,
    vendidoAHoy, diaHoy, diasDelMes, pctMeta,
    porCanal: fc.porCanal,
  };
}

// Cuadro 3: top por producto. Reutiliza EXACTAMENTE las mismas funciones de
// atribución de canal/marca que Sell In/Out (canalDeCliente,
// canalDeProductoSellin, brandFromProduct, isMayoristaLine) y el mismo
// matcheo de variante por SKU-código (sellinFormatoLabel/variantesSku) — solo
// agrega, además del nivel padre ya existente en Sell In, un segundo nivel
// por variante (subCodigo) para el toggle "Por formato".
//
// Modelo de medición del diccionario de SKU: litros SOLO tiene sentido para
// CD Kairos (comercialización/distribución). Esta función trabaja
// exclusivamente sobre loadOrders() (órdenes Shopify de CD Kairos) — nunca
// mezcla ítems de Ruta Menú (CD-restaurante, medidos en unidades) en este
// mismo total. Por eso el filtro de marca en el frontend excluye a
// propósito Kairos Garden/Badass: no tienen SKU-código de Shopify ni litros,
// y sumarlos acá violaría esa separación.
async function comercialTopProductos(fromTs, toTs, canales, marcaFiltro){
  const result = await loadOrders(false);
  if (!result.available) return { available: false, reason: result.reason };
  const extras = loadProductExtras();
  const customBrands = getCustomBrands();
  const notes = loadCustomerNotes();
  const want = (c) => !canales || canales.includes(c);

  const amplio = new Map();
  const porFormato = new Map();
  const orders = result.orders.filter(o => { const t = new Date(o.createdAt).getTime(); return t >= fromTs && t < toTs; });
  for (const o of orders) {
    for (const li of (o.lineItems || [])) {
      const mayorista = isMayoristaLine(li);
      const canal = mayorista ? (canalDeCliente(o.customerId, notes) || canalDeProductoSellin(li.productId, extras) || 'sin_canal') : 'online';
      if (canal === 'sin_canal' || !want(canal)) continue;
      const brandKey = brandFromProduct({ vendor: li.vendor, title: li.title, tags: li.tags }, customBrands);
      if (marcaFiltro && marcaFiltro !== 'todas' && brandKey !== marcaFiltro) continue;

      const pid = li.productId || ('sin-id:' + li.title);
      const ex = li.productId ? extras.items[String(li.productId)] : null;
      const skuCode = ex?.skuCode || null;

      const a = amplio.get(pid) || { id: li.productId, skuCode, title: li.title, marca: brandKey, plata: 0, unidades: 0 };
      a.plata += li.amount; a.unidades += li.qty; amplio.set(pid, a);

      const variantesSku = Array.isArray(ex?.variantesSku) ? ex.variantesSku : [];
      const match = li.variantSku ? variantesSku.find(v => v.subCodigo === li.variantSku) : null;
      const formatoLabel = match ? match.formatoLabel : (li.variantTitle || 'Sin formato');
      const subKey = pid + '::' + (li.variantSku || formatoLabel);
      const f = porFormato.get(subKey) || { id: li.productId, skuCode, subCodigo: li.variantSku || null, formatoLabel, title: li.title, marca: brandKey, plata: 0, unidades: 0 };
      f.plata += li.amount; f.unidades += li.qty; porFormato.set(subKey, f);
    }
  }
  return {
    available: true,
    amplio: [...amplio.values()].map(p => ({ ...p, plata: Math.round(p.plata) })),
    porFormato: [...porFormato.values()].map(p => ({ ...p, plata: Math.round(p.plata) })),
  };
}

const COMERCIAL_CANALES_VALIDOS = ['horeca', 'retail', 'hospitality', 'online'];
app.get('/admin/comercial/top-productos', requireAdmin, async (req, res) => {
  try {
    const periodo = comercialResolvePeriodo(String(req.query.period || 'mes_actual'), String(req.query.from || ''), String(req.query.to || ''));
    if (!periodo) return res.status(400).json({ error: 'Rango de fechas inválido.' });
    const { from, to } = comercialPeriodoRangoTs(periodo);
    const canalParam = String(req.query.canal || 'todas');
    const canales = canalParam === 'todas' ? null : canalParam.split(',').filter(c => COMERCIAL_CANALES_VALIDOS.includes(c));
    const marca = String(req.query.marca || 'todas');
    const modo = req.query.modo === 'formato' ? 'formato' : 'amplio';
    const orden = req.query.orden === 'unidades' ? 'unidades' : 'plata';
    const d = await comercialTopProductos(from, to, canales, marca);
    if (!d.available) return res.json({ available: false, reason: d.reason, periodo });
    const rows = (modo === 'formato' ? d.porFormato : d.amplio).sort((a, b) => b[orden] - a[orden]).slice(0, 10);
    res.json({ available: true, periodo, modo, canal: canalParam, marca, orden, rows });
  } catch (e) { res.status(500).json({ error: 'Error calculando top de productos: ' + e.message }); }
});

app.get('/admin/comercial/home', requireAdmin, async (req, res) => {
  try {
    const periodo = comercialResolvePeriodo(String(req.query.period || 'mes_actual'), String(req.query.from || ''), String(req.query.to || ''));
    if (!periodo) return res.status(400).json({ error: 'Rango de fechas inválido.' });
    const [cuadro1, cuadro2] = await Promise.all([comercialCuadro1(), comercialCuadro2(periodo)]);
    res.json({ available: true, periodo, cuadro1, cuadro2 });
  } catch (e) { res.status(500).json({ error: 'Error calculando el inicio de Comercial: ' + e.message }); }
});

// Resumen IA del HOME — mismo patrón de finanzas-resumen.json: cache plano
// (solo la última generación), nunca se regenera solo, botón "Actualizar"
// explícito. TODO: restringir por rol (Gerencia/Finanzas) — hoy visible para
// todos los usuarios autenticados del panel, se pidió así explícitamente por
// ahora.
const COMERCIAL_RESUMEN_FILE = join(PROMPTS_EFFECTIVE_DIR, 'comercial-resumen.json');
function comercialResumenLoad(){ try { if (existsSync(COMERCIAL_RESUMEN_FILE)) return JSON.parse(readFileSync(COMERCIAL_RESUMEN_FILE, 'utf-8')); } catch (e) { console.warn('comercial resumen load:', e.message); } return null; }
function comercialResumenSave(o){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(COMERCIAL_RESUMEN_FILE, JSON.stringify(o, null, 2)); }
app.get('/admin/comercial/resumen', requireAdmin, (_req, res) => res.json(comercialResumenLoad() || { texto: null, generadoEn: null }));
app.post('/admin/comercial/resumen/generar', requireAdmin, async (req, res) => {
  try {
    const today = new Date();
    const month = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;
    const periodo = { tipo: 'mes_actual', month, rango: null, label: 'Mes actual' };
    const [c2, fc] = await Promise.all([comercialCuadro2(periodo), fcMonthCompute(month)]);
    const fmt = n => n == null ? 'sin dato' : '$' + Math.round(n).toLocaleString('es-CL');
    const ritmoNecesario = (c2.meta != null && c2.diasDelMes) ? Math.round(c2.meta / c2.diasDelMes) : null;
    const ritmoReal = (c2.vendidoAHoy != null && c2.diaHoy) ? Math.round(c2.vendidoAHoy / c2.diaHoy) : null;
    const porCanalTxt = Object.entries(fc.porCanal).map(([canal, v]) => `  · ${FC_GRID[canal].label}: proyectado ${fmt(v.plataProyectado || null)}, meta ${fmt(v.plataMeta || null)}`).join('\n');
    const datos = [
      `Día ${c2.diaHoy ?? '?'} de ${c2.diasDelMes ?? '?'} del mes ${month}.`,
      `Proyección del mes (Forecast Comercial): ${fmt(c2.proyectado)}.`,
      `Meta configurada por canal/marca (default +15%): ${fmt(c2.meta)}.`,
      `Vendido hasta hoy: ${fmt(c2.vendidoAHoy)}.`,
      `% de la meta alcanzado a la fecha: ${c2.pctMeta != null ? c2.pctMeta + '%' : 'sin dato'}.`,
      `Ritmo diario necesario para llegar a la meta: ${ritmoNecesario != null ? fmt(ritmoNecesario) + '/día' : 'sin dato'}.`,
      `Ritmo diario real hasta hoy: ${ritmoReal != null ? fmt(ritmoReal) + '/día' : 'sin dato'}.`,
      ``, `Por canal (proyección vs meta):`, porCanalTxt || '  (sin datos)',
    ].join('\n');
    const sys = 'Sos analista comercial de K-BROS. Analizás si el equipo va a tiempo para llegar a la meta comercial del mes (Forecast Comercial, +15% configurable). Escribe en español chileno neutro (tuteo), 2 o 3 frases breves, directas y accionables — por ejemplo "el mes recién comienza, trabajá día a día" o "esta semana se movió menos de lo esperado, a este ritmo está difícil, subí la intensidad". REGLA ABSOLUTA: usá ÚNICAMENTE los números que te paso abajo; NO inventes ni estimes NINGÚN número; si falta un dato, omitilo; no inventes causas ni hechos que no se deduzcan de las cifras.';
    const msg = await client.messages.create({ model: 'claude-sonnet-4-6', max_tokens: 600, system: sys, messages: [{ role: 'user', content: 'Cifras reales ya calculadas por el sistema:\n' + datos }] });
    const texto = (msg.content || []).filter(c => c.type === 'text').map(c => c.text).join('').trim();
    const out = { texto, generadoEn: new Date().toISOString(), month };
    comercialResumenSave(out);
    res.json(out);
  } catch (e) { res.status(500).json({ error: 'No se pudo generar el resumen: ' + String(e.message || e).slice(0, 200) }); }
});

function monthLabel(m){
  return ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'][m] || '';
}

