    lata = { id: randomUUID(), descripcion: GARDEN_LATA_CHICA_INS, precioNeto: (ref && Number(ref.precioNeto) > 0) ? ref.precioNeto : GARDEN_LATA_CHICA_PRECIO_DEFAULT, unidad: 'litro', volumen: 1, ila: 0, despacho: 0, rendimiento: null };
