// ─── Clientes mayoristas ────────────────────────────────────────────────────
// Lista de clientes Shopify con tag que contenga "mayorista" (case-insensitive),
// enriquecidos con métricas de sus órdenes. Notas internas en JSON propio.

const CUSTOMER_NOTES_FILE = join(PROMPTS_EFFECTIVE_DIR, 'customer-notes.json');
function loadCustomerNotes(){
  try {
    if (!existsSync(CUSTOMER_NOTES_FILE)) return {};
    const p = JSON.parse(readFileSync(CUSTOMER_NOTES_FILE, 'utf-8'));
    return (p && typeof p === 'object') ? p : {};
  } catch { return {}; }
}
function saveCustomerNotes(data){ writeFileSync(CUSTOMER_NOTES_FILE, JSON.stringify(data, null, 2)); }

const CUSTOMERS_QUERY = `query($cursor: String) {
  customers(first: 100, after: $cursor, query: "tag:mayorista") {
    edges { cursor node {
      id firstName lastName email phone note createdAt numberOfOrders tags
      amountSpent { amount }
      defaultAddress { address1 address2 city province company phone }
    } }
    pageInfo { hasNextPage }
  }
}`;

let wholesaleCache = null, wholesaleCacheAt = 0;
const WHOLESALE_TTL_MS = 10 * 60 * 1000;

function hasMayoristaTagArr(tags){
  return (tags || []).some(t => String(t).toLowerCase().includes('mayorista'));
}

async function loadWholesaleCustomers(force = false){
  if (!force && wholesaleCache && Date.now() - wholesaleCacheAt < WHOLESALE_TTL_MS) {
    return { available: true, customers: wholesaleCache };
  }
  if (!process.env.SHOPIFY_ADMIN_TOKEN) {
    return { available: false, reason: 'Shopify no conectado (falta SHOPIFY_ADMIN_TOKEN).' };
  }
  try {
    const customers = [];
    let cursor = null;
    for (let page = 0; page < 10; page++) {
      const resp = await shopifyAdminFetch('/graphql.json', {
        method: 'POST',
        body: JSON.stringify({ query: CUSTOMERS_QUERY, variables: { cursor } }),
      });
      if (resp.errors) {
        const msg = JSON.stringify(resp.errors);
        if (/access denied|read_customers|scope/i.test(msg)) {
          return { available: false, reason: 'El token de Shopify no tiene read_customers. Re-autorizá la app.' };
        }
        throw new Error(msg);
      }
      const conn = resp.data.customers;
      for (const e of conn.edges) {
        const n = e.node;
        const tags = n.tags || [];
        if (!hasMayoristaTagArr(tags)) continue; // doble check case-insensitive
        const addr = n.defaultAddress || {};
        customers.push({
          id: stripGid(n.id, 'Customer'),
          name: [n.firstName, n.lastName].filter(Boolean).join(' ').trim() || addr.company || '(sin nombre)',
          company: addr.company || null,
          email: n.email || null,
          phone: n.phone || addr.phone || null,
          address: [addr.address1, addr.address2, addr.city, addr.province].filter(Boolean).join(', ') || null,
          shopifyNote: n.note || null,
          createdAt: n.createdAt,
          numberOfOrders: Number(n.numberOfOrders || 0),
          amountSpent: parseFloat(n.amountSpent?.amount || 0),
          tags,
        });
      }
      if (!conn.pageInfo.hasNextPage) break;
      cursor = conn.edges[conn.edges.length - 1].cursor;
    }
    wholesaleCache = customers;
    wholesaleCacheAt = Date.now();
    return { available: true, customers };
  } catch (e) {
    const msg = String(e.message || e);
    if (/\b40[13]\b|access denied|read_customers/i.test(msg)) {
      return { available: false, reason: 'El token de Shopify no tiene read_customers. Re-autorizá la app.' };
    }
    return { available: false, reason: 'Error consultando clientes: ' + msg.slice(0, 200) };
  }
}

// Agrega métricas de órdenes a cada cliente (total, count, last, top product).
function ordersByCustomer(orders){
  const map = new Map();
  for (const o of orders) {
    if (!o.customerId) continue;
    if (!map.has(o.customerId)) map.set(o.customerId, []);
    map.get(o.customerId).push(o);
  }
  return map;
}

app.get('/admin/customers/wholesale', requireAdmin, async (req, res) => {
  const cust = await loadWholesaleCustomers(String(req.query.refresh||'')==='1');
  if (!cust.available) return res.json({ available: false, reason: cust.reason });
  const ord = await loadOrders(false);
  const byCust = ord.available ? ordersByCustomer(ord.orders) : new Map();
  const notes = loadCustomerNotes();

  const list = cust.customers.map(c => {
    const cOrders = byCust.get(c.id) || [];
    let total = 0, lastDate = null;
    const prodQty = new Map();
    for (const o of cOrders) {
      total += o.total;
      if (!lastDate || new Date(o.createdAt) > new Date(lastDate)) lastDate = o.createdAt;
      for (const li of o.lineItems) prodQty.set(li.title, (prodQty.get(li.title)||0) + li.qty);
    }
    // Si Shopify ya da amountSpent/numberOfOrders, preferimos eso para total
    // histórico; las órdenes del cache sirven para "última compra" y top.
    const topProduct = [...prodQty.entries()].sort((a,b)=>b[1]-a[1])[0];
    return {
      id: c.id, name: c.name, email: c.email, phone: c.phone,
      totalSpent: Math.round(c.amountSpent || total),
      orders: c.numberOfOrders || cOrders.length,
      lastOrder: lastDate,
      topProduct: topProduct ? topProduct[0] : null,
      hasNote: !!(notes[c.id] && notes[c.id].note),
      channels: Array.isArray(notes[c.id]?.channels) ? notes[c.id].channels : [],
    };
  });

  res.json({ available: true, total: list.length, customers: list });
});

app.get('/admin/customers/:id', requireAdmin, async (req, res) => {
  const id = String(req.params.id);
  const cust = await loadWholesaleCustomers(false);
  if (!cust.available) return res.json({ available: false, reason: cust.reason });
  const c = cust.customers.find(x => x.id === id);
  if (!c) return res.status(404).json({ error: 'Cliente no encontrado.' });

  const ord = await loadOrders(false);
  const cOrders = (ord.available ? ord.orders.filter(o => o.customerId === id) : [])
    .sort((a,b)=> new Date(b.createdAt) - new Date(a.createdAt));

  // Métricas
  let total = 0; const prodQty = new Map(); const monthly = {};
  for (const o of cOrders) {
    total += o.total;
    const mk = String(o.createdAt).slice(0,7); // YYYY-MM
    monthly[mk] = (monthly[mk] || 0) + o.total;
    for (const li of o.lineItems) prodQty.set(li.title, (prodQty.get(li.title)||0) + li.qty);
  }
  const orderCount = cOrders.length;
  const firstOrder = orderCount ? cOrders[cOrders.length-1].createdAt : null;
  const lastOrder  = orderCount ? cOrders[0].createdAt : null;
  const avgTicket  = orderCount ? Math.round(total / orderCount) : 0;
  // Frecuencia: días promedio entre órdenes
  let freqDays = null;
  if (orderCount >= 2) {
    const span = (new Date(lastOrder) - new Date(firstOrder)) / 86400e3;
    freqDays = Math.round(span / (orderCount - 1));
  }
  const topProducts = [...prodQty.entries()].map(([name,qty])=>({name,qty})).sort((a,b)=>b.qty-a.qty).slice(0,5);
  const monthlySpend = Object.entries(monthly).map(([month,amount])=>({month, amount: Math.round(amount)})).sort((a,b)=>a.month.localeCompare(b.month));

  // Conversaciones asociadas (match por email o teléfono en los mensajes)
  let conversations = [];
  try {
    const allConv = Array.isArray(readLog(CONV_LOG)) ? readLog(CONV_LOG) : [];
    const needles = [c.email, c.phone].filter(Boolean).map(s => String(s).toLowerCase());
    if (needles.length) {
      conversations = allConv.filter(cv => {
        const txt = (cv.messages||[]).map(m => String(m.content||'').toLowerCase()).join(' ');
        return needles.some(n => txt.includes(n));
      }).map(summarizeConversation).slice(0, 50);
    }
  } catch {}

  const notes = loadCustomerNotes();
  res.json({
    available: true,
    customer: {
      ...c,
      metrics: {
        totalSpent: Math.round(c.amountSpent || total),
        ordersCount: c.numberOfOrders || orderCount,
        avgTicket, freqDays, firstOrder, lastOrder,
      },
      orders: cOrders.map(o => ({
        id: o.id, name: o.name, createdAt: o.createdAt, total: Math.round(o.total),
        status: o.status,
        items: o.lineItems.map(li => ({ title: li.title, qty: li.qty })),
      })),
      topProducts, monthlySpend, conversations,
      note: notes[id]?.note || '',
      noteUpdatedAt: notes[id]?.updatedAt || null,
      channels: Array.isArray(notes[id]?.channels) ? notes[id].channels : [],
    },
  });
});

app.post('/admin/customers/:id/note', requireAdmin, (req, res) => {
  const id = String(req.params.id);
  const { note = '' } = req.body || {};
  if (typeof note !== 'string') return res.status(400).json({ error: 'Nota inválida.' });
  if (note.length > 10000) return res.status(413).json({ error: 'Nota demasiado larga.' });
  try {
    const data = loadCustomerNotes();
    const cur = data[id] || {};
    const channels = Array.isArray(cur.channels) ? cur.channels : [];
    if (!note.trim() && !channels.length) delete data[id];
    else data[id] = { ...cur, note: note.trim(), updatedAt: new Date().toISOString() };
    saveCustomerNotes(data);
    res.json({ ok: true });
  } catch (e) {
    res.status(500).json({ error: 'Error guardando nota: ' + e.message });
  }
});

// Canal(es) comercial(es) del cliente mayorista (Horeca/Retail/Hospitality) —
// base de la atribución de Sell In por canal (Fase 4). Mismo criterio que el
// canal de producto: nunca se infiere, lo asigna una persona desde la ficha
// del cliente. Reutiliza el mismo store de notas (customer-notes.json) para
// no crear un archivo nuevo por un solo campo adicional.
const SELLIN_CANALES = ['horeca', 'retail', 'hospitality'];
app.put('/admin/customers/:id/channels', requireAdmin, (req, res) => {
  const id = String(req.params.id).trim();
  const channels = Array.isArray((req.body || {}).channels) ? req.body.channels : null;
  if (!channels) return res.status(400).json({ error: 'Falta channels (array).' });
  const clean = [...new Set(channels.map(c => String(c)))].filter(c => SELLIN_CANALES.includes(c));
  try {
    const data = loadCustomerNotes();
    const cur = data[id] || {};
    data[id] = { ...cur, channels: clean, updatedAt: new Date().toISOString() };
    saveCustomerNotes(data);
    res.json({ ok: true, id, channels: clean });
  } catch (e) {
    res.status(500).json({ error: 'Error guardando canal: ' + e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// HOSPITALITY — perfil propio (unidad de negocio de restaurantes), separado
// del perfil madre. Primera sección: Rendimientos (aprovechamiento de
// proteínas por local/corte/proveedor). Esta etapa construye el modelo de
// datos y el dashboard de lectura del gerente; la app del operario que
// escribe estos registros (QR + PIN por restaurante, wizard mobile) es una
// etapa posterior — el POST de abajo ya es el contrato de datos funcional
// para que esa app se conecte sin fricción cuando se construya.
// ═══════════════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════════════
// HOSPITALITY · INGRESOS por cierre de caja
// Los restaurantes venden en caja, no por Shopify, así que el ingreso se carga
// a mano: un cierre por local y día, con el desglose por forma de pago. El
// TOTAL nunca se digita — se suma de las formas de pago.
// El total de estos cierres es lo que consume el Estado de Resultado como
// "ingresos" de ese centro (ver pnlCompute): mismo mecanismo que ya existía,
// solo cambia de dónde sale la cifra para estos 3 CD.
// ═══════════════════════════════════════════════════════════════════════════
// Los 3 centros de restaurante. cd_kairos NO está: el perfil madre queda igual.
const HOSP_CD_IDS = ['garden_antofagasta', 'garden_vespucio', 'badass'];
const esCdHospitality = (cd) => HOSP_CD_IDS.includes(String(cd || ''));
const HOSP_INGRESOS_FILE = join(PROMPTS_EFFECTIVE_DIR, 'hosp-ingresos.json');
const HOSP_FORMAS_PAGO_DEFAULT = ['CMR', 'Débito', 'Crédito', 'Efectivo'];
function hospIngLoad(){
  let d = { formasPago: [...HOSP_FORMAS_PAGO_DEFAULT], cierres: [] };
  try {
    if (existsSync(HOSP_INGRESOS_FILE)) {
      const p = JSON.parse(readFileSync(HOSP_INGRESOS_FILE, 'utf-8'));
      if (Array.isArray(p.formasPago) && p.formasPago.length) d.formasPago = p.formasPago;
      if (Array.isArray(p.cierres)) d.cierres = p.cierres;
    }
  } catch (e) { console.warn('hosp ingresos load:', e.message); }
  return d;
}
function hospIngSave(d){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(HOSP_INGRESOS_FILE, JSON.stringify(d, null, 2)); }
const hospIngUsuario = (req) => { const s = adminSessionFor(req); return (s && s.username) || 'sin sesión'; };
// Normaliza el desglose y calcula el total. El total SIEMPRE sale de acá: si el
// cliente manda uno, se ignora.
function hospIngNormalizarFormas(raw){
  const out = [];
  for (const f of (Array.isArray(raw) ? raw : [])) {
    const forma = String((f && f.forma) || '').trim().slice(0, 40);
    if (!forma) continue;
    const monto = Math.round(Number((f && f.monto) || 0));
    const transacciones = Math.round(Number((f && f.transacciones) || 0));
    if (!Number.isFinite(monto) || monto < 0) return { error: `Monto inválido en "${forma}".` };
    if (!Number.isFinite(transacciones) || transacciones < 0) return { error: `Cantidad de transacciones inválida en "${forma}".` };
    if (!monto && !transacciones) continue; // fila vacía: se ignora
    out.push({ forma, transacciones, monto });
  }
  if (!out.length) return { error: 'Cargá al menos una forma de pago con monto.' };
  return { formas: out, total: out.reduce((a, f) => a + f.monto, 0), transacciones: out.reduce((a, f) => a + f.transacciones, 0) };
}
// Candado anti-duplicado: un solo cierre por (restaurante + fecha).
const hospIngExistente = (d, cd, fecha, exceptoId) => (d.cierres || []).find(c => c.restaurante === cd && c.fecha === fecha && c.id !== exceptoId);
// Total de cierres de un CD en un mes o rango — lo que consume el EERR.
function hospIngresosPeriodo(cd, month, rango){
  const d = hospIngLoad();
  return (d.cierres || [])
    .filter(c => c.restaurante === cd)
    .filter(c => (rango && rango.from && rango.to) ? (c.fecha >= rango.from && c.fecha <= rango.to) : (String(c.fecha).slice(0, 7) === month))
    .reduce((a, c) => a + (Number(c.total) || 0), 0);
}
app.get('/admin/hospitality/ingresos', requireAdmin, (req, res) => {
  const d = hospIngLoad();
  const cd = esCdHospitality(req.query.cd) ? String(req.query.cd) : null;
  const mes = /^\d{4}-\d{2}$/.test(String(req.query.mes)) ? String(req.query.mes) : null;
  let cierres = d.cierres.slice();
  if (cd) cierres = cierres.filter(c => c.restaurante === cd);
  if (mes) cierres = cierres.filter(c => String(c.fecha).slice(0, 7) === mes);
  cierres.sort((a, b) => String(b.fecha).localeCompare(String(a.fecha)));
  res.json({
    formasPago: d.formasPago, cds: CD_LIST.filter(c => esCdHospitality(c.id)),
    cierres, total: cierres.reduce((a, c) => a + (Number(c.total) || 0), 0),
    meses: [...new Set(d.cierres.map(c => String(c.fecha).slice(0, 7)))].sort().reverse(),
  });
});
app.post('/admin/hospitality/ingresos', requireAdmin, (req, res) => {
  const b = req.body || {};
  if (!esCdHospitality(b.restaurante)) return res.status(400).json({ error: 'Elegí un restaurante.' });
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(b.fecha || ''))) return res.status(400).json({ error: 'Elegí la fecha del cierre.' });
  const n = hospIngNormalizarFormas(b.formas);
  if (n.error) return res.status(400).json({ error: n.error });
  const d = hospIngLoad();
  const ya = hospIngExistente(d, b.restaurante, b.fecha);
  // No se crea un segundo cierre para el mismo día y local: duplicaría el
  // ingreso en el EERR. Se devuelve el que ya existe para que se edite.
  if (ya) return res.status(409).json({ error: 'Ya hay un cierre de caja para ese local y esa fecha.', existente: ya });
  const ahora = new Date().toISOString(), quien = hospIngUsuario(req);
  const cierre = {
    id: 'hi_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7),
    restaurante: b.restaurante, fecha: String(b.fecha),
    formas: n.formas, total: n.total, transacciones: n.transacciones,
    origen: 'manual', creadoPor: quien, creadoEn: ahora, actualizadoPor: quien, actualizadoEn: ahora,
  };
  d.cierres.push(cierre); hospIngSave(d);
  res.json({ ok: true, cierre });
});
app.put('/admin/hospitality/ingresos/:id', requireAdmin, (req, res) => {
  const d = hospIngLoad();
  const c = d.cierres.find(x => x.id === String(req.params.id));
  if (!c) return res.status(404).json({ error: 'Cierre no encontrado.' });
  const b = req.body || {};
  if (b.restaurante !== undefined && !esCdHospitality(b.restaurante)) return res.status(400).json({ error: 'Restaurante inválido.' });
  const cd = b.restaurante || c.restaurante;
  const fecha = b.fecha || c.fecha;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(fecha))) return res.status(400).json({ error: 'Fecha inválida.' });
  if (hospIngExistente(d, cd, fecha, c.id)) return res.status(409).json({ error: 'Ya hay otro cierre para ese local y esa fecha.' });
  if (b.formas !== undefined) {
    const n = hospIngNormalizarFormas(b.formas);
    if (n.error) return res.status(400).json({ error: n.error });
    c.formas = n.formas; c.total = n.total; c.transacciones = n.transacciones;
  }
  c.restaurante = cd; c.fecha = String(fecha);
  c.actualizadoPor = hospIngUsuario(req); c.actualizadoEn = new Date().toISOString();
  hospIngSave(d);
  res.json({ ok: true, cierre: c });
});
app.delete('/admin/hospitality/ingresos/:id', requireAdmin, (req, res) => {
  const d = hospIngLoad();
  const n = d.cierres.length;
  d.cierres = d.cierres.filter(x => x.id !== String(req.params.id));
  if (d.cierres.length === n) return res.status(404).json({ error: 'Cierre no encontrado.' });
  hospIngSave(d); res.json({ ok: true });
});
// Formas de pago configurables (agregar transferencia, delivery, etc.).
app.put('/admin/hospitality/ingresos/config/formas', requireAdmin, (req, res) => {
  const arr = Array.isArray((req.body || {}).formasPago) ? req.body.formasPago : null;
  if (!arr) return res.status(400).json({ error: 'formasPago tiene que ser una lista.' });
  const vistas = new Set(); const limpio = [];
  for (const f of arr) {
    const v = String(f || '').trim().slice(0, 40);
    if (!v || vistas.has(v.toLowerCase())) continue;
    vistas.add(v.toLowerCase()); limpio.push(v);
  }
  if (!limpio.length) return res.status(400).json({ error: 'Dejá al menos una forma de pago.' });
  const d = hospIngLoad(); d.formasPago = limpio; hospIngSave(d);
  res.json({ ok: true, formasPago: limpio });
});

const HOSP_RENDIMIENTOS_FILE = join(PROMPTS_EFFECTIVE_DIR, 'hosp-rendimientos.json');
const HOSP_RESTAURANTES = [
  { id: 'kg_antofagasta',       label: 'Kairos Garden Antofagasta' },
  { id: 'kg_vespucio',          label: 'Kairos Garden Vespucio' },
  { id: 'badass_parque_arauco', label: 'Badass Parque Arauco' },
];
const HOSP_RESTAURANTE_IDS = new Set(HOSP_RESTAURANTES.map(r => r.id));
const HOSP_ORIGENES = ['Chile', 'Brasil', 'USA', 'Paraguay', 'Argentina'];
const HOSP_TIPOS = [{ id: 'carne', label: 'Carne' }, { id: 'pescado', label: 'Pescado' }, { id: 'pollo', label: 'Pollo' }];
const HOSP_TIPO_IDS = new Set(HOSP_TIPOS.map(t => t.id));
// Cortes por tipo: configurables (viven en el archivo de datos, no hardcodeados
// en el frontend) — arrancan con estos valores por defecto la primera vez.
// Pollo arranca solo con "Otro" a propósito: no se inventan cortes que nadie
// pidió. La lista se llena sola — lo que se escribe en "Otro" se agrega, igual
// que ya pasa con operarios y proveedores.
const HOSP_CORTES_DEFAULT = {
  carne:   ['Lomo', 'Entraña', 'Posta rosada', 'Tapapecho', 'Sobrecostilla', 'Churrasco', 'Otro'],
  pescado: ['Salmón', 'Merluza', 'Reineta', 'Congrio', 'Atún', 'Otro'],
  pollo:   ['Otro'],
};
const hospNormTxt = (s) => String(s == null ? '' : s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
// Deja "Otro" siempre al final de la lista de cortes.
function hospOrdenarCortes(arr){
  const otros = arr.filter(c => hospNormTxt(c) === 'otro');
  const resto = arr.filter(c => hospNormTxt(c) !== 'otro');
  return [...resto, ...(otros.length ? ['Otro'] : [])];
}
// Agrega un valor a una lista si no está (comparando normalizado). Es lo que
// hace que las listas de cortes y orígenes crezcan con el uso.
function hospAgregarSiFalta(arr, valor){
  const v = String(valor || '').trim().slice(0, 60);
  if (!v || hospNormTxt(v) === 'otro') return false;
  if (arr.some(x => hospNormTxt(x) === hospNormTxt(v))) return false;
  arr.push(v);
  return true;
}
// Migración de las listas de cortes (dato persistido, así que va versionada).
// v2: operación pidió sacar Asado / Molido / Costilla de carne, sumar los
// cortes que sí usan, y habilitar pollo. NO toca los cortes que el equipo haya
// agregado por su cuenta desde la app.
const HOSP_CORTES_V = 2;
const HOSP_CORTES_V2_QUITAR = ['asado', 'molido', 'costilla'];
function hospMigrarCortes(data){
  if (Number(data.cortesV) >= HOSP_CORTES_V) return false;
  const quitar = new Set(HOSP_CORTES_V2_QUITAR.map(hospNormTxt));
  data.cortes.carne = (data.cortes.carne || []).filter(c => !quitar.has(hospNormTxt(c)));
  for (const c of HOSP_CORTES_DEFAULT.carne) hospAgregarSiFalta(data.cortes.carne, c);
  data.cortes.carne = hospOrdenarCortes([...data.cortes.carne, 'Otro']);
  if (!Array.isArray(data.cortes.pollo) || !data.cortes.pollo.length) data.cortes.pollo = HOSP_CORTES_DEFAULT.pollo.slice();
  data.cortesV = HOSP_CORTES_V;
  return true;
}
// PINs por local: gate liviano de acceso público para la app del operario (no
// es una contraseña por persona — filtra que sea alguien del local, nada más).
// Defaults de arranque, cambiables desde el ERP vía PUT /admin/hospitality/
// config/pin sin tocar código.
const HOSP_PIN_DEFAULT = { kg_antofagasta: '1111', kg_vespucio: '2222', badass_parque_arauco: '3333' };
function hospLoad(){
  let data = {
    cortes: { carne: HOSP_CORTES_DEFAULT.carne.slice(), pescado: HOSP_CORTES_DEFAULT.pescado.slice(), pollo: HOSP_CORTES_DEFAULT.pollo.slice() },
    cortesV: HOSP_CORTES_V,
    origenes: [...HOSP_ORIGENES],  // también se llena sola con lo que se cargue en "Otro"
    registros: [],
    pins: { ...HOSP_PIN_DEFAULT },
    operarios: {},           // { restauranteId: [nombre, ...] } — arranca vacío, se llena solo (sin inventar personal)
    proveedoresFrecuentes: [], // lista global (compartida entre locales), también se llena sola
  };
  let migrado = false;
  try {
    if (existsSync(HOSP_RENDIMIENTOS_FILE)) {
      const p = JSON.parse(readFileSync(HOSP_RENDIMIENTOS_FILE, 'utf-8'));
      if (p && p.cortes && typeof p.cortes === 'object') {
        for (const t of ['carne', 'pescado', 'pollo']) if (Array.isArray(p.cortes[t]) && p.cortes[t].length) data.cortes[t] = p.cortes[t];
      }
      data.cortesV = Number(p && p.cortesV) || 0;
      if (p && Array.isArray(p.origenes) && p.origenes.length) data.origenes = p.origenes;
      if (p && Array.isArray(p.registros)) data.registros = p.registros;
      if (p && p.pins && typeof p.pins === 'object') data.pins = { ...data.pins, ...p.pins };
      if (p && p.operarios && typeof p.operarios === 'object') data.operarios = p.operarios;
      if (p && Array.isArray(p.proveedoresFrecuentes)) data.proveedoresFrecuentes = p.proveedoresFrecuentes;
      if (hospMigrarCortes(data)) migrado = true;
    }
  } catch (e) { console.warn('hosp load:', e.message); }
  if (migrado) hospSave(data);
  return data;
}
function hospSave(d){
  if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true });
  writeFileSync(HOSP_RENDIMIENTOS_FILE, JSON.stringify(d, null, 2));
}
let HOSP_ID_SEQ = 0;
function hospNewId(){ HOSP_ID_SEQ = (HOSP_ID_SEQ + 1) % 100000; return 'hr_' + Date.now().toString(36) + '_' + HOSP_ID_SEQ.toString(36); }
// Turno derivado de la hora (HH:MM) — no lo tipea el operario, se calcula solo.
function hospTurnoDeHora(hora){
  const h = parseInt(String(hora || '').slice(0, 2), 10);
  if (!Number.isFinite(h)) return '';
  if (h >= 6 && h < 12) return 'mañana';
  if (h >= 12 && h < 19) return 'tarde';
  return 'noche';
}
// Rendimiento % y balance de masa se calculan siempre desde los pesos crudos
// (no se guardan aparte) para que nunca queden desincronizados si un registro
// se edita más adelante.
function hospDecorar(r){
  const bruto = Number(r.pesoBrutoKg) || 0;
  const util = Number(r.pesoUtilKg) || 0;
  const sub = Number(r.subproductoKg) || 0;
  const desecho = Number(r.desechoKg) || 0;
  return {
    ...r,
    rendimientoPct: bruto > 0 ? Math.round((util / bruto) * 1000) / 10 : 0,
    balanceKg: Math.round((bruto - (util + sub + desecho)) * 1000) / 1000,
  };
}
// pins solo se agrega cuando lo pide el admin (nunca al público — ver
// GET /rendimientos/config más abajo, que llama esta misma función sin pins).
function hospConfig(cortes, pins, origenes){
  // "Otro" siempre al final del selector de origen (la app lo abre como texto libre).
  const orig = [...(Array.isArray(origenes) && origenes.length ? origenes : HOSP_ORIGENES), 'Otro'];
  const cfg = { restaurantes: HOSP_RESTAURANTES, origenes: orig, tipos: HOSP_TIPOS, cortes, turnos: ['mañana', 'tarde', 'noche'] };
  if (pins) cfg.pins = pins;
  return cfg;
}

// GET: config + todos los registros (decorados). El dashboard del gerente
// filtra/agrupa en el cliente — el volumen esperado (lotes procesados por
// local) no justifica duplicar esa lógica en un endpoint de agregación aparte.
app.get('/admin/hospitality/rendimientos', requireAdmin, (_req, res) => {
  const data = hospLoad();
  res.json({ config: hospConfig(data.cortes, data.pins, data.origenes), registros: data.registros.map(hospDecorar) });
});

// Cambiar el PIN de un local (el equipo lo hace desde el ERP, sin redeploy).
app.put('/admin/hospitality/config/pin', requireAdmin, (req, res) => {
  const { restaurante, pin } = req.body || {};
  if (!HOSP_RESTAURANTE_IDS.has(restaurante)) return res.status(400).json({ error: 'Restaurante inválido.' });
  if (typeof pin !== 'string' || !/^\d{4,6}$/.test(pin)) return res.status(400).json({ error: 'El PIN debe ser numérico, de 4 a 6 dígitos.' });
  const data = hospLoad();
  data.pins[restaurante] = pin;
  hospSave(data);
  res.json({ ok: true, pins: data.pins });
});

// Desecho = bruto − útil − subproducto. Nunca negativo: si los pesos no cuadran
// el POST se rechaza antes (ver validación), esto es solo el redondeo final.
function hospDesecho(b){
  const d = (Number(b.pesoBrutoKg) || 0) - (Number(b.pesoUtilKg) || 0) - (Number(b.subproductoKg) || 0);
  return Math.max(0, Math.round(d * 1000) / 1000);
}
// Detalle de reparto del subproducto por destino (solo lo manda la app para
// Pescado, cuando el operario asignó al menos un destino). Se sanea acá en
// vez de confiar en el body: filas sin "uso" o con "kg" inválido se
// descuelgan solas en vez de tirar abajo el guardado de todo el registro.
function hospSanitizeDestinos(arr){
  if (!Array.isArray(arr)) return undefined;
  const out = arr
    .map(d => ({ uso: String((d && d.uso) || '').trim(), kg: Number(d && d.kg) }))
    .filter(d => d.uso && Number.isFinite(d.kg) && d.kg >= 0);
  return out.length ? out : undefined;
}
function hospCrearRegistroDesdeBody(b, data){
  const now = new Date();
  const fecha = /^\d{4}-\d{2}-\d{2}$/.test(b.fecha) ? b.fecha : now.toISOString().slice(0, 10);
  const hora = /^\d{2}:\d{2}$/.test(b.hora) ? b.hora : now.toTimeString().slice(0, 5);
  const registro = {
    id: hospNewId(),
    restaurante: b.restaurante,
    operario: String(b.operario || '').trim(),
    origen: b.origen || '',
    tipo: b.tipo,
    corte: b.corte,
    proveedorLote: String(b.proveedorLote || '').trim(),
    // Factura / folio del documento con el que llegó la proteína.
    factura: String(b.factura || '').trim().slice(0, 80),
    pesoBrutoKg: Number(b.pesoBrutoKg),
    pesoUtilKg: Number(b.pesoUtilKg),
    subproductoKg: Number(b.subproductoKg),
    // Para qué se va a usar el subproducto (carne molida, fondo, etc.) — en
    // Pescado, la app manda acá un resumen legible del reparto ("Tártar 3kg,
    // Relleno 2kg") para que el panel siga mostrando algo sin cambios ahí.
    subproductoDestino: String(b.subproductoDestino || '').trim().slice(0, 80),
    // El desecho NO lo tipea nadie: es lo que sobra del balance de masa. Se
    // calcula acá, no en el cliente, para que el número no dependa de qué
    // versión de la app haya quedado cacheada en la tablet.
    desechoKg: hospDesecho(b),
    fecha, hora,
    turno: hospTurnoDeHora(hora),
    creadoEn: now.toISOString(),
  };
  // Detalle estructurado del reparto (hoy solo Pescado) — opcional, no
  // reemplaza subproductoKg/subproductoDestino de arriba, que son los que ya
  // usan el balance de masa y el panel.
  if (b.subproducto_total_kg != null && Number.isFinite(Number(b.subproducto_total_kg))) {
    registro.subproducto_total_kg = Number(b.subproducto_total_kg);
  }
  const destinos = hospSanitizeDestinos(b.subproducto_destinos);
  if (destinos) registro.subproducto_destinos = destinos;
  data.registros.push(registro);
  return registro;
}

// POST: acá escribe la app del operario (junto con el propio ERP, si algún
// día hace falta cargar un registro a mano). requireAdminOrHospPortal acepta
// la sesión de admin de siempre O la sesión liviana por PIN de local que abre
// la app pública (ver más abajo) — en ese segundo caso el restaurante queda
// fijo al del PIN usado, nunca al que mande el body, así nadie carga a
// nombre de otro local sin su PIN.
app.post('/admin/hospitality/rendimientos', requireAdminOrHospPortal, (req, res) => {
  const b = { ...(req.body || {}) };
  if (req.hospPortalSess) b.restaurante = req.hospPortalSess.restauranteId;
  const data = hospLoad();
  if (!HOSP_RESTAURANTE_IDS.has(b.restaurante)) return res.status(400).json({ error: 'Restaurante inválido.' });
  if (!HOSP_TIPO_IDS.has(b.tipo)) return res.status(400).json({ error: 'Tipo inválido (carne o pescado).' });
  // Corte: el de la lista, o uno nuevo escrito en "Otro" — en ese caso se suma
  // a la lista del tipo para que la próxima vez esté disponible de un toque.
  data.cortes[b.tipo] = Array.isArray(data.cortes[b.tipo]) ? data.cortes[b.tipo] : ['Otro'];
  const corteLibre = String(b.corteOtro || '').trim().slice(0, 60);
  if (hospNormTxt(b.corte) === 'otro' && corteLibre) {
    b.corte = corteLibre;
    if (hospAgregarSiFalta(data.cortes[b.tipo], corteLibre)) data.cortes[b.tipo] = hospOrdenarCortes(data.cortes[b.tipo]);
  }
  const cortesValidos = new Set((data.cortes[b.tipo] || []).map(hospNormTxt));
  if (!b.corte || !cortesValidos.has(hospNormTxt(b.corte))) return res.status(400).json({ error: 'Corte inválido para ese tipo.' });
  // Origen: idem, la lista crece con lo que se cargue en "Otro".
  data.origenes = Array.isArray(data.origenes) && data.origenes.length ? data.origenes : [...HOSP_ORIGENES];
  const origenLibre = String(b.origenOtro || '').trim().slice(0, 60);
  if (hospNormTxt(b.origen) === 'otro' && origenLibre) { b.origen = origenLibre; hospAgregarSiFalta(data.origenes, origenLibre); }
  if (b.origen && !data.origenes.some(o => hospNormTxt(o) === hospNormTxt(b.origen))) return res.status(400).json({ error: 'Origen inválido.' });
  for (const k of ['pesoBrutoKg', 'pesoUtilKg', 'subproductoKg']) {
    if (b[k] == null || !Number.isFinite(Number(b[k])) || Number(b[k]) < 0) return res.status(400).json({ error: `Falta o es inválido: ${k}.` });
  }
  // El desecho sale del balance, así que útil + subproducto no puede pasarse del
  // bruto: si se pasa, algún peso está mal cargado y hay que revisarlo.
  const sobra = (Number(b.pesoBrutoKg) || 0) - (Number(b.pesoUtilKg) || 0) - (Number(b.subproductoKg) || 0);
  if (sobra < -0.001) return res.status(400).json({ error: 'Peso útil + subproducto supera el peso bruto. Revisá los pesos.' });
  const registro = hospCrearRegistroDesdeBody(b, data);
  hospSave(data);
  res.json({ ok: true, registro: hospDecorar(registro) });
});

// ═══════════════════════════════════════════════════════════════════════════
// APP DEL OPERARIO — portal público (sin login de admin) para cargar
// rendimientos desde el piso, con acceso filtrado por PIN de local. Mismo
// patrón que /proveedores (portal-views, cookie propia, sesión en memoria) —
// ver requirePortal/PORTAL_SESSIONS más abajo en el archivo para la
// referencia que se siguió acá.
// ═══════════════════════════════════════════════════════════════════════════
const HOSP_PORTAL_COOKIE = 'hosprend';
const HOSP_PORTAL_TTL_MS = 12 * 60 * 60 * 1000; // 12h: alcanza un turno largo sin re-pedir PIN
const HOSP_PORTAL_SESSIONS = new Map(); // token → { restauranteId, expiresAt }
// La sesión del portal se PERSISTE en disco. Es una tablet en la cocina que
// nadie mira: si las sesiones vivieran solo en memoria, cada deploy o reinicio
// del server la dejaría con 401 y los lotes cargados se quedarían colgados en
// "Sincronizando…" sin que nadie se entere. Con esto un reinicio es
// transparente para el que está pesando.
const HOSP_PORTAL_SESS_FILE = join(PROMPTS_EFFECTIVE_DIR, 'hosp-portal-sesiones.json');
function hospPortalSessionsLoad(){
  try {
    if (!existsSync(HOSP_PORTAL_SESS_FILE)) return;
    const arr = JSON.parse(readFileSync(HOSP_PORTAL_SESS_FILE, 'utf-8'));
    const now = Date.now();
    for (const s of (Array.isArray(arr) ? arr : [])) {
      if (s && s.token && s.restauranteId && Number(s.expiresAt) > now) HOSP_PORTAL_SESSIONS.set(s.token, { restauranteId: s.restauranteId, expiresAt: Number(s.expiresAt) });
    }
  } catch (e) { console.warn('hosp portal sesiones:', e.message); }
}
function hospPortalSessionsSave(){
  try {
    if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true });
    writeFileSync(HOSP_PORTAL_SESS_FILE, JSON.stringify([...HOSP_PORTAL_SESSIONS].map(([token, s]) => ({ token, ...s }))));
  } catch (e) { console.warn('hosp portal sesiones (save):', e.message); }
}
hospPortalSessionsLoad();
function hospPortalSessionFor(req){
  const token = parseCookies(req)[HOSP_PORTAL_COOKIE];
  if (!token) return null;
  const s = HOSP_PORTAL_SESSIONS.get(token);
  if (!s) return null;
  if (s.expiresAt < Date.now()) { HOSP_PORTAL_SESSIONS.delete(token); hospPortalSessionsSave(); return null; }
  return { token, ...s };
}
function requireHospPortal(req, res, next){
  const sess = hospPortalSessionFor(req);
  if (!sess) return res.status(401).json({ error: 'Sesión de local vencida. Ingresá el PIN de nuevo.' });
  req.hospPortalSess = sess;
  next();
}
// Acepta admin O portal — usada solo en el POST de arriba (el GET del
// dashboard sigue siendo admin-only: expone TODOS los locales/registros).
function requireAdminOrHospPortal(req, res, next){
  // La sesión del portal se resuelve SIEMPRE primero: de ella sale el local al
  // que se imputa el registro. Si se saltara con el bypass de auth, el POST
  // llegaría sin restaurante y se rechazaría por "Restaurante inválido".
  const sess = hospPortalSessionFor(req);
  if (sess) { req.hospPortalSess = sess; return next(); }
  if (process.env.ADMIN_AUTH_ENABLED === '0') return next();
  if (adminSessionFor(req)) return next();
  return res.status(401).json({ error: 'No autorizado.' });
}
setInterval(() => {
  const now = Date.now();
  let purgadas = false;
  for (const [t, s] of HOSP_PORTAL_SESSIONS) if (s.expiresAt < now) { HOSP_PORTAL_SESSIONS.delete(t); purgadas = true; }
  if (purgadas) hospPortalSessionsSave();
}, 60 * 60 * 1000).unref?.();

// La app en sí — HTML/CSS/JS autocontenido, sin build, mobile-first.
app.get('/rendimientos', (_req, res) => {
  res.sendFile(join(__dirname, 'portal-views', 'rendimientos-app.html'));
});

// Config pública (sin pines): restaurantes, tipos, orígenes, cortes. Los
// mismos valores exactos que usa el dashboard del gerente, para que crucen.
app.get('/rendimientos/config', (_req, res) => {
  const data = hospLoad();
  res.json(hospConfig(data.cortes, null, data.origenes));
});

app.post('/rendimientos/pin', async (req, res) => {
  const { restaurante, pin } = req.body || {};
  if (!HOSP_RESTAURANTE_IDS.has(restaurante)) return res.status(400).json({ error: 'Restaurante inválido.' });
  await new Promise(r => setTimeout(r, 200)); // anti fuerza bruta, mismo patrón que /proveedores/login
  const data = hospLoad();
  const real = (data.pins && data.pins[restaurante]) || '';
  const ok = typeof pin === 'string' && pin.length > 0 && real && pin === real;
  if (!ok) return res.status(401).json({ error: 'PIN incorrecto.' });
  const token = randomBytes(32).toString('hex');
  const expiresAt = Date.now() + HOSP_PORTAL_TTL_MS;
  HOSP_PORTAL_SESSIONS.set(token, { restauranteId: restaurante, expiresAt });
  hospPortalSessionsSave();
  const secure = req.secure || req.headers['x-forwarded-proto'] === 'https';
  const parts = [`${HOSP_PORTAL_COOKIE}=${encodeURIComponent(token)}`, 'HttpOnly', 'Path=/', 'SameSite=Lax', `Max-Age=${Math.floor(HOSP_PORTAL_TTL_MS / 1000)}`];
  if (secure) parts.push('Secure');
  res.setHeader('Set-Cookie', parts.join('; '));
  res.json({ ok: true, restaurante: HOSP_RESTAURANTES.find(r => r.id === restaurante) });
});
app.post('/rendimientos/salir', (req, res) => {
  const sess = hospPortalSessionFor(req);
  if (sess) { HOSP_PORTAL_SESSIONS.delete(sess.token); hospPortalSessionsSave(); }
  res.setHeader('Set-Cookie', `${HOSP_PORTAL_COOKIE}=; HttpOnly; Path=/; SameSite=Lax; Max-Age=0`);
  res.json({ ok: true });
});
app.get('/rendimientos/me', requireHospPortal, (req, res) => {
  res.json({ restaurante: HOSP_RESTAURANTES.find(r => r.id === req.hospPortalSess.restauranteId) });
});

// Roster de operarios del local: arranca vacío (no se inventa personal) y se
// completa solo — cada operario nuevo se agrega la primera vez que entra.
const hospNorm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
app.get('/rendimientos/operarios', requireHospPortal, (req, res) => {
  const data = hospLoad();
  res.json({ operarios: (data.operarios && data.operarios[req.hospPortalSess.restauranteId]) || [] });
});
app.post('/rendimientos/operarios', requireHospPortal, (req, res) => {
  const nombre = String((req.body || {}).nombre || '').trim();
  if (!nombre) return res.status(400).json({ error: 'Falta el nombre.' });
  const data = hospLoad();
  const restId = req.hospPortalSess.restauranteId;
  if (!data.operarios[restId]) data.operarios[restId] = [];
  if (!data.operarios[restId].some(o => hospNorm(o) === hospNorm(nombre))) {
    data.operarios[restId].push(nombre);
    hospSave(data);
  }
  res.json({ ok: true, operarios: data.operarios[restId] });
});

// Proveedores frecuentes: lista global (un proveedor de carne puede surtir a
