// ── Config admin: ver/cambiar los 4 códigos desde el ERP, sin redeploy ──
app.get('/admin/costeo-consulta/codigos', requireAdmin, (req, res) => {
  res.json({ locales: CONSULTA_LOCALES, codigos: consultaCodigosLoad() });
});
app.put('/admin/costeo-consulta/codigos', requireAdmin, (req, res) => {
  const b = req.body || {};
  const codigos = consultaCodigosLoad();
  const claves = [...CONSULTA_LOCAL_IDS, 'admin'];
  for (const k of claves) {
    if (b[k] === undefined) continue;
    const v = String(b[k] || '').trim();
    if (!/^\d{4,8}$/.test(v)) return res.status(400).json({ error: `El código de "${k}" debe ser numérico, de 4 a 8 dígitos.` });
    codigos[k] = v;
  }
  consultaCodigosSave(codigos);
  res.json({ ok: true, codigos });
});

// ─────────────────────────────────────────────────────────────────────────────
// Asistente del admin por ÁREA (Motor A). Chat propio del panel (distinto al bot
// público /chat): sabe en qué área está el usuario y responde/ genera entregables
// con el contexto de esa área. Streaming SSE. Solo lectura por ahora (no edita).
// ─────────────────────────────────────────────────────────────────────────────
const ADMIN_AREAS = {
  marketing:   { label: 'Marketing', desc: 'Analítica, conversaciones del bot Zorbot, campañas de ads, contenido y tono de las marcas (Kairos Brewing, Firulais, Banny), página web y tutoriales.' },
  comercial:   { label: 'Comercial', desc: 'Catálogo de productos (Shopify), puntos de venta, top clientes, y ventas HORECA de Pyxis (cervezas Kairos vs competencia, documentos/facturas de compra de bebidas/licores con precio de referencia).' },
  distribucion:{ label: 'Distribución', desc: 'Distribuidora (proveedores, costos, márgenes, órdenes de compra), rutas de despacho, trazabilidad y mantenimiento de máquinas/barriles.' },
  operacion:   { label: 'Operación', desc: 'Costeo de insumos/recetas/platos y precios; OEE, calidad, catas e inventario.' },
  produccion:  { label: 'Producción', desc: 'Centro de producción: tanques, cocción, recetas, envasado, limpiezas, paradas; integración con el ERP Gestión Cervecera.' },
  finanzas:    { label: 'Finanzas', desc: 'Ingreso por venta (4 canales, automático de Shopify), costos, gastos, Estado de Resultado (margen bruto, EBITDA), notas de crédito y objetivos.' },
  personas:    { label: 'Personas', desc: 'Nómina de trabajadores, costo empresa por mes y boletas de honorarios.' },
  herramientas:{ label: 'Herramientas', desc: 'Forecast (EERR proyectado, presupuestos, simulación anual) y cuentas del equipo.' },
};
// Base de conocimiento global de K-BROS (el asistente conoce TODO el sistema, no por
// secciones). Se arma con las 8 áreas + el negocio + las integraciones.
const ASST_KBROS_KNOWLEDGE = [
  'Sos el asistente de K-BROS, el panel interno de administración de Kairos — una empresa chilena de bebidas artesanales. Marcas: Kairos Brewing (cervezas), Firulais (cheladas craft), Banny (destilados / RTD). Conocés TODO el sistema K-BROS y ayudás al equipo con lo que necesite, de cualquier área, sin limitarte a una sección.',
  'K-BROS (admin en k-bros.cl) tiene 8 áreas:\n' + Object.entries(ADMIN_AREAS).map(([id, a]) => `• ${a.label}: ${a.desc}`).join('\n'),
  'Integraciones y datos: Shopify (ventas online + catálogo + clientes; el ingreso por venta se arma automático de Shopify por 4 canales: HORECA, Venta Online, Retail/Walmart, Hospitality/Garden-Badass). Pyxis / BiPyxis (ERP gastronómico de Grupo Mil Sabores: data de compras y ventas de los locales HORECA — sirve para comparar Kairos vs la competencia y ver a qué precio compran bebidas/licores). Gestión Cervecera (ERP de producción cervecera: recetas y lotes). Marketplace público: zorbo.cl (con su propio bot Zorbot).',
  'Impuestos Chile relevantes: IVA 19%; ILA (impuesto a bebidas alcohólicas) 20,5% en cervezas y vinos, 31% en destilados. El precio de referencia de un producto = precio sin impuestos × (1 + IVA + ILA).',
].join('\n\n');
// Snapshot compacto de datos reales del negocio (todas las áreas con data fácil), para
// que el asistente responda con cifras de verdad. Best-effort: si algo falla, se omite.
async function asistenteContexto(){
  const fmt = n => '$' + Math.round(Number(n) || 0).toLocaleString('es-CL');
  const lineas = [];
  try {
    const m = finCurMonth(); const p = await pnlCompute(m, null).catch(() => null);
    if (p) lineas.push(`FINANZAS · Estado de Resultado ${estadoMonthLabel(m)}: ingresos ${fmt(p.ingresos.total)}, margen bruto ${p.ratios.margenBruto}%, EBITDA ${fmt(p.ebitda)} (${p.ratios.ebitda}%), gasto de personal ${p.ratios.gastoPersonal}%.` + (p.shopifyLimitado ? ' [Shopify solo entrega los últimos ~60 días; meses viejos salen en $0.]' : ''));
  } catch (e) { /* best-effort */ }
  try {
    const cred = pyxisCredsSafe();
    if (cred.emailSet && cred.passwordSet) { const c = await pyxisCervezasResumen('2', {}).catch(() => null); if (c) lineas.push(`COMERCIAL · Ventas HORECA cervezas (${(c.meses || []).join(', ')}): total ${fmt(c.totales.cervezas)}, Kairos ${fmt(c.totales.kairos)} (${c.totales.shareKairos}% del total), competencia ${fmt(c.totales.otras)}.`); }
  } catch (e) { /* best-effort */ }
  return lineas.join('\n');
}
// Almacenamiento: chats persistentes por usuario (sandbox privado) + solicitudes.
const ASST_CHATS_FILE = join(PROMPTS_EFFECTIVE_DIR, 'asistente-chats.json');
function asstChatsLoad(){ try { if (existsSync(ASST_CHATS_FILE)) return JSON.parse(readFileSync(ASST_CHATS_FILE, 'utf-8')); } catch (e) { console.warn('asst chats:', e.message); } return {}; }
function asstChatsSave(o){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(ASST_CHATS_FILE, JSON.stringify(o, null, 2)); }
function asstUserKey(req){ const s = adminSessionFor(req); return String((s && (s.teamId || s.username)) || 'anon'); }
function asstIsAdmin(req){ const s = adminSessionFor(req); return !!(s && s.role === 'admin'); }
const asstNewId = (p) => p + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
const ASST_SOL_FILE = join(PROMPTS_EFFECTIVE_DIR, 'asistente-solicitudes.json');
function asstSolLoad(){ try { if (existsSync(ASST_SOL_FILE)) return JSON.parse(readFileSync(ASST_SOL_FILE, 'utf-8')); } catch (e) { console.warn('asst sol:', e.message); } return []; }
function asstSolSave(a){ if (PROMPTS_OVERRIDE_DIR && !existsSync(PROMPTS_OVERRIDE_DIR)) mkdirSync(PROMPTS_OVERRIDE_DIR, { recursive: true }); writeFileSync(ASST_SOL_FILE, JSON.stringify(a, null, 2)); }
app.post('/admin/asistente', requireAdmin, async (req, res) => {
  const b = req.body || {};
  const message = String(b.message || '').slice(0, 8000).trim();
  if (!message) return res.status(400).json({ error: 'Mensaje vacío.' });
  const seccion = String(b.seccion || '').slice(0, 60);
  const sess = adminSessionFor(req); const nombre = (sess && (sess.nombre || sess.apodo || sess.username)) || '';
  const uk = asstUserKey(req);
  const all = asstChatsLoad(); const mine = all[uk] || (all[uk] = []);
  let chat = b.chatId ? mine.find(c => c.id === b.chatId) : null;
  if (!chat) { chat = { id: asstNewId('chat'), area: null, mode: 'normal', titulo: message.slice(0, 48), messages: [], createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }; mine.unshift(chat); }
  const ctx = await asistenteContexto();
  const ubic = seccion ? `Contexto: ahora mismo el usuario está viendo la sección "${seccion}" del panel (pero podés ayudarlo con cualquier tema de K-BROS, no solo eso).` : '';
  const sys = [
    ASST_KBROS_KNOWLEDGE,
    'Escribí en español chileno neutro (tuteo), claro y directo. Podés usar markdown (títulos, listas, tablas, bloques de código). Si te piden un archivo/documento, entregá el contenido completo listo para copiar/descargar. Respondés preguntas, analizás, y generás entregables (resúmenes, textos, tablas, borradores) de cualquier área.',
    ubic,
    ctx ? ('Datos reales del negocio ahora mismo (usá SOLO estos, no inventes cifras):\n' + ctx) : '',
    nombre ? `Le hablás a ${nombre}.` : '',
    'REGLA: NO inventes números ni datos que no te hayan pasado o no estén en el contexto. Si falta un dato, decílo y explicá cómo verlo en el panel. No editás el sistema: asesorás y generás contenido.',
  ].filter(Boolean).join('\n\n');
  const historia = chat.messages.slice(-10).map(m => ({ role: m.role, content: String(m.content).slice(0, 6000) }));
  // Adjuntos (imágenes / PDF / texto). Van solo en este turno (no se guardan en el chat).
  const atts = Array.isArray(b.attachments) ? b.attachments.slice(0, 6) : [];
  const userContent = [];
  for (const at of atts) {
    const mt = String(at.media_type || ''); const data = at.data ? String(at.data) : '';
    if (/^image\/(png|jpe?g|webp|gif)$/i.test(mt) && data) userContent.push({ type: 'image', source: { type: 'base64', media_type: mt.toLowerCase(), data } });
    else if (mt === 'application/pdf' && data) userContent.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data } });
    else if (at.text) userContent.push({ type: 'text', text: 'Archivo adjunto "' + String(at.name || '').slice(0, 80) + '":\n' + String(at.text).slice(0, 24000) });
  }
  userContent.push({ type: 'text', text: message });
  const apiMessages = [...historia, { role: 'user', content: userContent.length > 1 ? userContent : message }];
  const attNota = atts.length ? (' (adjuntó ' + atts.length + ' archivo' + (atts.length > 1 ? 's' : '') + ')') : '';
  res.setHeader('Content-Type', 'text/event-stream'); res.setHeader('Cache-Control', 'no-cache'); res.setHeader('Connection', 'keep-alive');
  res.write(`data: ${JSON.stringify({ start: true, chatId: chat.id })}\n\n`);
  let full = '';
  try {
    const stream = client.messages.stream({ model: 'claude-sonnet-4-6', max_tokens: 2400, system: sys, messages: apiMessages });
    for await (const chunk of stream) { if (chunk.type === 'content_block_delta' && chunk.delta.type === 'text_delta') { full += chunk.delta.text; res.write(`data: ${JSON.stringify({ delta: chunk.delta.text })}\n\n`); } }
    res.write('data: [DONE]\n\n');
  } catch (err) { console.error('asistente error:', err.message); res.write(`data: ${JSON.stringify({ error: 'No pude responder ahora: ' + String(err.message || err).slice(0, 120) })}\n\n`); }
  res.end();
  try { chat.messages.push({ role: 'user', content: message + attNota, ts: new Date().toISOString() }); if (full) chat.messages.push({ role: 'assistant', content: full, ts: new Date().toISOString() }); if (chat.messages.length > 200) chat.messages = chat.messages.slice(-200); if (chat.titulo === 'Nuevo chat' || !chat.titulo) chat.titulo = message.slice(0, 48); chat.updatedAt = new Date().toISOString(); asstChatsSave(all); } catch (e) { /* no romper */ }
});
// Chats persistentes (privados por usuario).
app.get('/admin/asistente/chats', requireAdmin, (req, res) => {
  const mine = asstChatsLoad()[asstUserKey(req)] || [];
  res.json({ chats: mine.map(c => ({ id: c.id, area: c.area, mode: c.mode, titulo: c.titulo, n: (c.messages || []).length, updatedAt: c.updatedAt })).sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || ''))) });
});
app.post('/admin/asistente/chats', requireAdmin, (req, res) => {
  const all = asstChatsLoad(); const uk = asstUserKey(req); const mine = all[uk] || (all[uk] = []);
  const area = ADMIN_AREAS[(req.body || {}).area] ? req.body.area : null;
  const chat = { id: asstNewId('chat'), area, mode: (req.body || {}).mode === 'code' ? 'code' : 'normal', titulo: 'Nuevo chat', messages: [], createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() };
  mine.unshift(chat); asstChatsSave(all); res.json(chat);
});
app.get('/admin/asistente/chats/:id', requireAdmin, (req, res) => {
  const c = (asstChatsLoad()[asstUserKey(req)] || []).find(x => x.id === req.params.id);
  if (!c) return res.status(404).json({ error: 'No encontrado.' }); res.json(c);
});
app.delete('/admin/asistente/chats/:id', requireAdmin, (req, res) => {
  const all = asstChatsLoad(); const mine = all[asstUserKey(req)] || []; const i = mine.findIndex(x => x.id === req.params.id);
  if (i < 0) return res.status(404).json({ error: 'No encontrado.' }); mine.splice(i, 1); asstChatsSave(all); res.json({ ok: true });
});
// Solicitudes al "general" (piden aprobación del admin).
app.post('/admin/asistente/solicitudes', requireAdmin, (req, res) => {
  const b = req.body || {}; const titulo = String(b.titulo || '').slice(0, 140).trim(); const detalle = String(b.detalle || '').slice(0, 8000).trim();
  if (!titulo) return res.status(400).json({ error: 'Ponele un título a la solicitud.' });
  const sess = adminSessionFor(req); const autor = (sess && (sess.nombre || sess.apodo || sess.username)) || 'alguien';
  const list = asstSolLoad(); const sol = { id: asstNewId('sol'), area: ADMIN_AREAS[b.area] ? b.area : null, titulo, detalle, autor, autorKey: asstUserKey(req), chatId: String(b.chatId || ''), estado: 'pendiente', createdAt: new Date().toISOString(), resueltoEn: null, resueltoPor: null, nota: '' };
  list.unshift(sol); asstSolSave(list); res.json(sol);
});
app.get('/admin/asistente/solicitudes', requireAdmin, (req, res) => {
  const list = asstSolLoad(); const admin = asstIsAdmin(req); const uk = asstUserKey(req);
  res.json({ admin, solicitudes: (admin ? list : list.filter(s => s.autorKey === uk)), pendientes: list.filter(s => s.estado === 'pendiente').length });
});
app.put('/admin/asistente/solicitudes/:id', requireAdmin, (req, res) => {
  if (!asstIsAdmin(req)) return res.status(403).json({ error: 'Solo un admin aprueba o rechaza solicitudes.' });
  const list = asstSolLoad(); const s = list.find(x => x.id === req.params.id); if (!s) return res.status(404).json({ error: 'No encontrada.' });
  const b = req.body || {}; if (['aprobada', 'rechazada', 'pendiente'].includes(b.estado)) s.estado = b.estado;
  s.nota = String(b.nota || '').slice(0, 500); const sess = adminSessionFor(req); s.resueltoPor = (sess && (sess.nombre || sess.username)) || 'admin'; s.resueltoEn = new Date().toISOString();
  asstSolSave(list); res.json(s);
});

